/**
 * Workflow history management — undo/redo stack, state snapshots.
 *
 * Extracted from workflow-designer-advanced.vue so the logic can be
 * unit-tested without re-implementing methods in every test.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface HistoryState {
  nodes: any[];
  edges: any[];
  model: Record<string, any>;
}

/**
 * Minimal interface that the component satisfies via `this`.
 * Orchestration functions accept this instead of the full component instance.
 */
export interface HistoryContext {
  nodes: any[];
  edges: any[];
  workflowModel: Record<string, any>;
  history: HistoryState[];
  redoHistory: HistoryState[];
  isRestoring: boolean;
  hasUnsavedChanges: boolean;
  MAX_HISTORY: number;
  flow: {
    setNodes: (nodes: any[]) => void;
    setEdges: (edges: any[]) => void;
    getEdges?: { value: any[] };
  };
  $nextTick: () => Promise<void>;
  recreateEdgeData: (edge: any) => any;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const MAX_HISTORY = 50;

// ---------------------------------------------------------------------------
// Pure functions (no context needed)
// ---------------------------------------------------------------------------

/**
 * Strip VueFlow internal properties from nodes so history snapshots
 * only contain user-authored data.  When restored, VueFlow recalculates
 * `dimensions`, `handleBounds`, `computedPosition`, etc. from scratch,
 * avoiding stale-internal bugs (e.g. notes disappearing after undo).
 */
export function cleanNodesForHistory(nodes: any[]): any[] {
  return nodes.map(n => ({
    id: n.id,
    type: n.type,
    position: n.position ? { x: n.position.x, y: n.position.y } : { x: 0, y: 0 },
    data: n.data ? JSON.parse(JSON.stringify(n.data)) : {},
    connectable: n.connectable,
    selectable: n.selectable,
    ...(n.parentNode !== undefined && { parentNode: n.parentNode }),
    ...(n.extent !== undefined && { extent: n.extent }),
    ...(n.expandParent !== undefined && { expandParent: n.expandParent }),
    ...(n.dragHandle !== undefined && { dragHandle: n.dragHandle }),
    ...(n.class !== undefined && { class: n.class }),
    ...(n.style !== undefined && { style: JSON.parse(JSON.stringify(n.style)) }),
  }));
}

/** Strip VueFlow internal properties to get clean, serializable edge data. */
export function cleanEdgesForHistory(edges: any[]): any[] {
  return edges.map(e => ({
    id: e.id,
    source: e.source,
    target: e.target,
    sourceHandle: e.sourceHandle,
    targetHandle: e.targetHandle,
    type: e.type,
    label: e.label,
    animated: e.animated,
    style: e.style ? JSON.parse(JSON.stringify(e.style)) : undefined,
    labelStyle: e.labelStyle ? JSON.parse(JSON.stringify(e.labelStyle)) : undefined,
    data: e.data ? { color: e.data.color } : undefined,
  }));
}

/** Deep-clone a workflowModel object. */
export function snapshotWorkflowModel(model: Record<string, any>): Record<string, any> {
  return JSON.parse(JSON.stringify(model));
}

/** Mutate `target` in-place so it matches `snapshot`. */
export function restoreWorkflowModel(
  target: Record<string, any>,
  snapshot: Record<string, any>,
): void {
  // Remove keys that no longer exist in the snapshot
  for (const key of Object.keys(target)) {
    if (!(key in snapshot)) {
      delete target[key];
    }
  }
  // Restore snapshot values
  for (const [key, value] of Object.entries(snapshot)) {
    target[key] = value;
  }
}

/**
 * Read edges from VueFlow's internal store, not the reactive `edges` array.
 * v-model:edges sync is async, so the reactive array can be stale.
 */
export function getFlowEdges(flow: any, fallbackEdges: any[]): any[] {
  const flowEdges = flow?.getEdges?.value;
  return Array.isArray(flowEdges) && flowEdges.length > 0
    ? (flowEdges as any[])
    : fallbackEdges;
}

// ---------------------------------------------------------------------------
// Orchestration functions (operate on HistoryContext)
// ---------------------------------------------------------------------------

/** Snapshot current state and push to history stack (with dedup + trim). */
export function saveHistoryImmediate(ctx: HistoryContext): void {
  const currentState: HistoryState = {
    nodes: cleanNodesForHistory(ctx.nodes),
    edges: cleanEdgesForHistory(getFlowEdges(ctx.flow, ctx.edges)),
    model: snapshotWorkflowModel(ctx.workflowModel),
  };

  // Only save if something actually changed
  const lastState = ctx.history[ctx.history.length - 1];
  if (
    lastState &&
    JSON.stringify(lastState.nodes) === JSON.stringify(currentState.nodes) &&
    JSON.stringify(lastState.edges) === JSON.stringify(currentState.edges)
  ) {
    // Snapshot deduped, but the caller performed an action — mark dirty.
    // Baseline call sites (loadWorkflow, mounted) reset this to false
    // immediately after.
    ctx.hasUnsavedChanges = true;
    return;
  }

  ctx.history.push(currentState);

  // Trim history if too large
  if (ctx.history.length > ctx.MAX_HISTORY) {
    ctx.history.shift();
  }

  ctx.redoHistory = []; // Clear redo stack on new action
  ctx.hasUnsavedChanges = true;
}

/** Undo the last action, restoring from history stack. */
export async function undoCanvas(ctx: HistoryContext): Promise<void> {
  if (ctx.history.length === 0) return;

  // If we're at the baseline (single entry) and nothing changed, skip restore
  // to avoid VueFlow churn that can drop transient state like notes.
  if (ctx.history.length === 1) {
    const baseline = ctx.history[0];
    const currentNodes = cleanNodesForHistory(ctx.nodes);
    const currentEdges = cleanEdgesForHistory(getFlowEdges(ctx.flow, ctx.edges));
    if (
      JSON.stringify(baseline.nodes) === JSON.stringify(currentNodes) &&
      JSON.stringify(baseline.edges) === JSON.stringify(currentEdges)
    ) {
      return; // Nothing to undo — current state matches baseline
    }
  }

  ctx.isRestoring = true;

  try {
    const currentState: HistoryState = {
      nodes: cleanNodesForHistory(ctx.nodes),
      edges: cleanEdgesForHistory(getFlowEdges(ctx.flow, ctx.edges)),
      model: snapshotWorkflowModel(ctx.workflowModel),
    };

    const targetState = ctx.history.length > 1
      ? ctx.history.pop()!       // Normal undo: pop and restore previous
      : ctx.history[0];           // Last entry: restore but keep in history

    ctx.redoHistory.push(currentState);

    const restoredNodes = JSON.parse(JSON.stringify(targetState.nodes));
    const restoredEdges = JSON.parse(JSON.stringify(targetState.edges)).map(
      (edge: any) => ctx.recreateEdgeData(edge),
    );

    // Use flow.setNodes/setEdges only — let v-model sync handle reactive arrays.
    // Direct assignment triggers a v-model watcher AFTER isRestoring=false,
    // causing setEdges to re-run isValidConnection (duplicate rejection).
    ctx.flow.setNodes(restoredNodes);
    ctx.flow.setEdges(restoredEdges);
    if (targetState.model) restoreWorkflowModel(ctx.workflowModel, targetState.model);
    await ctx.$nextTick();
  } finally {
    ctx.isRestoring = false;
  }
}

/** Redo a previously undone action. */
export async function redoCanvas(ctx: HistoryContext): Promise<void> {
  if (ctx.redoHistory.length === 0) return;
  ctx.isRestoring = true;

  try {
    const redoState = ctx.redoHistory.pop()!;
    const currentState: HistoryState = {
      nodes: cleanNodesForHistory(ctx.nodes),
      edges: cleanEdgesForHistory(getFlowEdges(ctx.flow, ctx.edges)),
      model: snapshotWorkflowModel(ctx.workflowModel),
    };
    ctx.history.push(currentState);

    const restoredNodes = JSON.parse(JSON.stringify(redoState.nodes));
    const restoredEdges = JSON.parse(JSON.stringify(redoState.edges)).map(
      (edge: any) => ctx.recreateEdgeData(edge),
    );

    ctx.flow.setNodes(restoredNodes);
    ctx.flow.setEdges(restoredEdges);
    if (redoState.model) restoreWorkflowModel(ctx.workflowModel, redoState.model);
    await ctx.$nextTick();
  } finally {
    ctx.isRestoring = false;
  }
}

