import {
  WFValidationError,
  WFValidationWarning,
  WFValidationErrorTypes,
  WFValidationWarningTypes,
  NodeType,
  HandleType,
  VF_NODE_TYPE,
  NODE_TYPE_TRANSLATION_KEYS,
} from '../workflow-advanced-models';
import { i18n } from 'src/boot/i18n';
import { getSourceHandles } from './workflowHandleConfig';

/**
 * Frontend validation result.
 * Uses 'valid' for frontend consistency (backend uses 'is_valid').
 */
export interface ValidationResult {
  valid: boolean;
  errors: WFValidationError[];
  warnings: WFValidationWarning[];
}

/**
 * VueFlow node structure for validation.
 * Maps to backend AdvancedNode but in VueFlow format:
 * - id → node_id
 * - data.nodeType → node_type
 */
export interface WorkflowNode {
  id: string;
  type: typeof VF_NODE_TYPE[keyof typeof VF_NODE_TYPE] | string;
  data?: {
    nodeType?: NodeType;
    config?: Record<string, any>;
  };
}

/**
 * VueFlow edge structure for validation.
 * Maps to backend AdvancedEdge but in VueFlow format:
 * - source → source_node_id
 * - target → target_node_id
 */
export interface WorkflowEdge {
  id?: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle?: string;
}

/** Trigger node types (WHEN, START) */
const TRIGGER_TYPES: NodeType[] = [NodeType.WHEN, NodeType.START];

/** Control node types that require multiple inputs */
const MULTI_INPUT_TYPES: NodeType[] = [NodeType.ALL, NodeType.ANY, NodeType.OR];

/** Valid target node types for triggers */
const VALID_TRIGGER_TARGETS: NodeType[] = [
  NodeType.AND,
  NodeType.THEN,
  NodeType.DELAY,
  NodeType.ALL,
  NodeType.ANY,
  NodeType.OR,
];

/** Maximum delay in seconds (24 hours) */
const MAX_DELAY_SECONDS = 86400;


/**
 * Detects cycles in the workflow graph using DFS.
 */
export function hasCycle(nodes: WorkflowNode[], edges: WorkflowEdge[]): boolean {
  const adjacency: Record<string, string[]> = {};
  for (const node of nodes) {
    adjacency[node.id] = [];
  }
  for (const edge of edges) {
    if (adjacency[edge.source]) {
      adjacency[edge.source].push(edge.target);
    }
  }

  const visited = new Set<string>();
  const recStack = new Set<string>();

  function dfs(nodeId: string): boolean {
    visited.add(nodeId);
    recStack.add(nodeId);

    for (const neighbor of adjacency[nodeId] || []) {
      if (!visited.has(neighbor)) {
        if (dfs(neighbor)) {
          return true;
        }
      } else if (recStack.has(neighbor)) {
        return true;
      }
    }

    recStack.delete(nodeId);
    return false;
  }

  for (const node of nodes) {
    if (!visited.has(node.id)) {
      if (dfs(node.id)) {
        return true;
      }
    }
  }

  return false;
}

/**
 * Helper to create a validation error.
 */
function createError(
  translationKey: string,
  errorType: WFValidationErrorTypes,
  nodeId: string | null = null,
  edgeId: string | null = null,
  params?: Record<string, string | number>,
): WFValidationError {
  return { message: i18n.t(translationKey, params ?? {}) as string, translation_key: translationKey, translation_params: params, error_type: errorType, node_id: nodeId, edge_id: edgeId };
}

/**
 * Helper to create a validation warning.
 */
function createWarning(
  translationKey: string,
  warningType: WFValidationWarningTypes,
  nodeId: string | null = null,
  edgeId: string | null = null,
  params?: Record<string, string | number>,
): WFValidationWarning {
  return { message: i18n.t(translationKey, params ?? {}) as string, translation_key: translationKey, translation_params: params, warning_type: warningType, node_id: nodeId, edge_id: edgeId };
}

/** Get the node type for a given node */
function getNodeType(node: WorkflowNode): NodeType | undefined {
  return node.data?.nodeType;
}

/** Get translated display name for a node type */
function getNodeTypeLabel(nodeType: NodeType | undefined): string {
  if (!nodeType) return 'Unknown';
  const key = NODE_TYPE_TRANSLATION_KEYS[nodeType];
  return key ? (i18n.t(key) as string) : nodeType;
}

