/** Rule: Check for cycles in the workflow graph */
function validateNoCycles(
  nodes: WorkflowNode[],
  edges: WorkflowEdge[],
  errors: WFValidationError[],
): void {
  if (hasCycle(nodes, edges)) {
    errors.push(
      createError('wf_validation_cycle', WFValidationErrorTypes.CYCLE),
    );
  }
}

/** Rule: Must have at least one trigger (When/Start) node */
function validateHasTrigger(
  triggerNodes: WorkflowNode[],
  errors: WFValidationError[],
): void {
  if (triggerNodes.length === 0) {
    errors.push(
      createError('wf_validation_no_trigger', WFValidationErrorTypes.NO_TRIGGER),
    );
  }
}

/** Rule: Must have at least one Then (action) node */
function validateHasAction(
  thenNodes: WorkflowNode[],
  errors: WFValidationError[],
): void {
  if (thenNodes.length === 0) {
    errors.push(
      createError('wf_validation_no_action', WFValidationErrorTypes.NO_TRIGGER),
    );
  }
}

/** Rules: Trigger nodes must not have incoming edges and must connect to valid targets */
function validateTriggerNodes(
  triggerNodes: WorkflowNode[],
  logicNodes: WorkflowNode[],
  edges: WorkflowEdge[],
  errors: WFValidationError[],
): void {
  for (const triggerNode of triggerNodes) {
    const outEdges = edges.filter((e) => e.source === triggerNode.id);
    const inEdges = edges.filter((e) => e.target === triggerNode.id);

    // Rule: Triggers must not have incoming edges
    if (inEdges.length > 0) {
      errors.push(
        createError('wf_validation_trigger_has_incoming', WFValidationErrorTypes.TRIGGER_HAS_INCOMING, triggerNode.id),
      );
    }

    // Rule: Triggers must connect to valid targets
    if (outEdges.length === 0) {
      errors.push(
        createError('wf_validation_trigger_not_connected', WFValidationErrorTypes.NO_TRIGGER, triggerNode.id),
      );
    } else {
      for (const edge of outEdges) {
        const target = logicNodes.find((n) => n.id === edge.target);
        if (target && !VALID_TRIGGER_TARGETS.includes(getNodeType(target) as NodeType)) {
          errors.push(
            createError('wf_validation_invalid_trigger_target', WFValidationErrorTypes.INVALID_TARGET_HANDLE, triggerNode.id),
          );
        }
      }
    }
  }
}

/** Rule: Triggers cannot be edge targets */
function validateTriggerTargets(
  edges: WorkflowEdge[],
  logicNodes: WorkflowNode[],
  errors: WFValidationError[],
): void {
  for (const edge of edges) {
    const targetNode = logicNodes.find((n) => n.id === edge.target);
    if (targetNode && TRIGGER_TYPES.includes(getNodeType(targetNode) as NodeType)) {
      errors.push(
        createError('wf_validation_trigger_as_target', WFValidationErrorTypes.TRIGGER_AS_TARGET, targetNode.id, edge.id || null),
      );
    }
  }
}

/** Rule: ALL/ANY/OR nodes need at least 2 incoming connections */
function validateMultiInputNodes(
  multiInputNodes: WorkflowNode[],
  edges: WorkflowEdge[],
  errors: WFValidationError[],
): void {
  for (const node of multiInputNodes) {
    const inEdges = edges.filter((e) => e.target === node.id);
    const nodeTypeLabel = getNodeTypeLabel(getNodeType(node));

    // OR counts distinct source nodes (each may contribute multiple handle edges)
    if (getNodeType(node) === NodeType.OR) {
      const sourceNodes = new Set(inEdges.map((e) => e.source));
      if (sourceNodes.size < 2) {
        errors.push(
          createError('wf_validation_insufficient_inputs', WFValidationErrorTypes.INSUFFICIENT_INPUTS, node.id, null, { nodeType: nodeTypeLabel }),
        );
      }
    } else if (inEdges.length < 2) {
      errors.push(
        createError('wf_validation_insufficient_inputs', WFValidationErrorTypes.INSUFFICIENT_INPUTS, node.id, null, { nodeType: nodeTypeLabel }),
      );
    }
  }
}

/** Rule: DELAY node configuration validation */
function validateDelayNodes(
  logicNodes: WorkflowNode[],
  errors: WFValidationError[],
): void {
  for (const node of logicNodes) {
    if (getNodeType(node) !== NodeType.DELAY) continue;
    const delaySeconds = node.data?.config?.delay_seconds;
    if (delaySeconds == null) {
      errors.push(
        createError('wf_validation_delay_no_config', WFValidationErrorTypes.INVALID_DELAY_CONFIG, node.id),
      );
    } else if (typeof delaySeconds !== 'number' || delaySeconds <= 0) {
      errors.push(
        createError('wf_validation_delay_invalid', WFValidationErrorTypes.INVALID_DELAY_CONFIG, node.id),
      );
    } else if (delaySeconds > MAX_DELAY_SECONDS) {
      errors.push(
        createError('wf_validation_delay_too_long', WFValidationErrorTypes.INVALID_DELAY_CONFIG, node.id),
      );
    }
  }
}

/** Rule: Validate edge handle connections match node type constraints */
function validateEdgeHandles(
  logicNodes: WorkflowNode[],
  edges: WorkflowEdge[],
  errors: WFValidationError[],
): void {
  const nodeMap = new Map(logicNodes.map((n) => [n.id, n]));
  for (const edge of edges) {
    const sourceNode = nodeMap.get(edge.source);
    const targetNode = nodeMap.get(edge.target);
    if (!sourceNode || !targetNode) continue;

    // Validate source handle
    const sourceType = getNodeType(sourceNode);
    if (sourceType && edge.sourceHandle) {
      const validHandleIds = getSourceHandles(sourceType).map(s => s.id);
      if (validHandleIds.length > 0 && !validHandleIds.includes(edge.sourceHandle)) {
        errors.push(
          createError('wf_validation_invalid_source_handle', WFValidationErrorTypes.INVALID_SOURCE_HANDLE, edge.source, edge.id || null, { handle: edge.sourceHandle, nodeType: getNodeTypeLabel(sourceType) }),
        );
      }
    }

    // Validate target handle - all nodes use INPUT
    if (edge.targetHandle && edge.targetHandle !== HandleType.INPUT) {
      errors.push(
        createError('wf_validation_invalid_target_handle', WFValidationErrorTypes.INVALID_TARGET_HANDLE, edge.target, edge.id || null, { handle: edge.targetHandle }),
      );
    }
  }
}

/** Warning: Check for orphan nodes (no connections) */
function warnOrphanNodes(
  logicNodes: WorkflowNode[],
  edges: WorkflowEdge[],
  warnings: WFValidationWarning[],
): void {
  for (const node of logicNodes) {
    if (getNodeType(node) === NodeType.NOTE) continue;

    const incoming = edges.filter((e) => e.target === node.id);
    const outgoing = edges.filter((e) => e.source === node.id);

    if (incoming.length === 0 && outgoing.length === 0) {
      warnings.push(
        createWarning('wf_validation_orphan_node', WFValidationWarningTypes.ORPHAN, node.id),
      );
    }
  }
}

/** Warning: Multiple output handles from the same node targeting the same node */
function warnDuplicateOutputTargets(
  logicNodes: WorkflowNode[],
  edges: WorkflowEdge[],
  warnings: WFValidationWarning[],
): void {
  for (const node of logicNodes) {
    const outgoing = edges.filter((e) => e.source === node.id);
    const targetToHandles: Record<string, string[]> = {};
    for (const edge of outgoing) {
      if (!targetToHandles[edge.target]) {
        targetToHandles[edge.target] = [];
      }
      targetToHandles[edge.target].push(edge.sourceHandle || 'unknown');
    }
    for (const [, handles] of Object.entries(targetToHandles)) {
      if (handles.length > 1) {
        warnings.push(
          createWarning('wf_validation_duplicate_output_target', WFValidationWarningTypes.DUPLICATE_OUTPUT_TARGET, node.id, null, { count: handles.length, handles: handles.join(', ') }),
        );
      }
    }
  }
}

/**
 * Validates workflow structure for the advanced workflow designer.
 * Mirrors backend validate_model() for fast client-side feedback.
 */
export function validateWorkflowStructure(
  nodes: WorkflowNode[],
  edges: WorkflowEdge[],
): ValidationResult {
  const errors: WFValidationError[] = [];
  const warnings: WFValidationWarning[] = [];

  // Filter to only logic/control nodes (exclude UI-only nodes like notes)
  const logicNodes = nodes.filter(
    (n) => n.type === VF_NODE_TYPE.LOGIC || n.type === VF_NODE_TYPE.START || n.type === VF_NODE_TYPE.CONTROL,
  );

  const triggerNodes = logicNodes.filter((n) =>
    TRIGGER_TYPES.includes(getNodeType(n) as NodeType),
  );
  const thenNodes = logicNodes.filter((n) => getNodeType(n) === NodeType.THEN);
  const multiInputNodes = logicNodes.filter((n) =>
    MULTI_INPUT_TYPES.includes(getNodeType(n) as NodeType),
  );

  // Run all validation rules
  validateNoCycles(nodes, edges, errors);
  validateHasTrigger(triggerNodes, errors);
  validateHasAction(thenNodes, errors);
  validateTriggerNodes(triggerNodes, logicNodes, edges, errors);
  validateTriggerTargets(edges, logicNodes, errors);
  validateMultiInputNodes(multiInputNodes, edges, errors);
  validateDelayNodes(logicNodes, errors);
  validateEdgeHandles(logicNodes, edges, errors);
  warnOrphanNodes(logicNodes, edges, warnings);
  warnDuplicateOutputTargets(logicNodes, edges, warnings);

  return { valid: errors.length === 0, errors, warnings };
}

// ── Merge / dedup helpers used by validateWorkflow in the designer ──

type ValidationItem = { node_id?: string | null; translation_key?: string; message?: string };

/**
 * Deduplicates validation items (errors or warnings) by node_id + translation_key.
 * When both frontend and backend return the same finding, only the first is kept.
 */
export function deduplicateValidationItems<T extends ValidationItem>(items: T[]): T[] {
  const seen = new Set<string>();
  const result: T[] = [];
  for (const item of items) {
    const key = `${item.node_id || ''}::${item.translation_key || item.message || ''}`;
    if (!seen.has(key)) {
      seen.add(key);
      result.push(item);
    }
  }
  return result;
}

/**
 * Extracts errors from a backend validation response, normalizing plain
 * string errors into the structured WFValidationError shape.
 */
export function extractBackendErrors(response: any): WFValidationError[] {
  if (response?.is_valid) return [];
  if (response?.structured_errors?.length) {
    return response.structured_errors;
  }
  if (response?.errors?.length) {
    return response.errors.map((msg: string) => ({
      message: msg,
      translation_key: '',
      node_id: null,
      edge_id: null,
    }));
  }
  return [];
}

/**
 * Extracts structured warnings from a backend validation response.
 */
export function extractBackendWarnings(response: any): WFValidationWarning[] {
  return response?.structured_warnings || [];
}
