/**
 * Pure functions for serializing/deserializing workflow data
 * between VueFlow canvas state and the backend AdvancedFlowData format.
 *
 * The orchestration functions (serializeToAdvancedFlowData, deserializeFromAdvancedFlowData)
 * remain in the component and call these helpers.
 */

import {
  NodeType,
  VF_NODE_TYPE,
  HandleType,
  CONTROL_NODE_TYPES,
  NODE_TYPE_TRANSLATION_KEYS,
  NODE_TYPE_TOOLTIP_KEYS,
  NodeTypeHelpers,
  type AdvancedNode,
  type AdvancedEdge,
  type FlowNote,
} from '../workflow-advanced-models';

// ── Handle normalization ─────────────────────────────────────────────

/**
 * Normalizes legacy source handle names to canonical HandleType values.
 * Handles backend/legacy values: 'right'/'true' -> SUCCESS, 'false' -> ERROR.
 */
export function normalizeSourceHandle(h: string): HandleType {
  if (h === 'right' || h === 'true') return HandleType.SUCCESS;
  if (h === 'false') return HandleType.ERROR;
  if (
    [HandleType.SUCCESS, HandleType.ERROR, HandleType.FAILED_CONDITION].includes(
      h as HandleType,
    )
  )
    return h as HandleType;
  return HandleType.SUCCESS;
}

/**
 * Normalizes legacy target handle names to canonical HandleType values.
 * Handles backend/legacy value: 'left' -> INPUT.
 */
export function normalizeTargetHandle(h: string): HandleType {
  if (h === 'left') return HandleType.INPUT;
  if (h === HandleType.INPUT) return h as HandleType;
  return HandleType.INPUT;
}

// ── Serialization (VueFlow -> Backend) ───────────────────────────────

/**
 * Serializes a single VueFlow edge to AdvancedEdge format for the backend.
 */
export function serializeEdge(edge: any): AdvancedEdge {
  return {
    edge_id: edge.id,
    source_node_id: edge.source,
    source_handle: normalizeSourceHandle(edge.sourceHandle || ''),
    target_node_id: edge.target,
    target_handle: normalizeTargetHandle(edge.targetHandle || ''),
  };
}

/**
 * Serializes note nodes to FlowNote format for the backend.
 */
export function serializeNotes(
  nodes: any[],
  defaultNoteColor: string,
  defaultNoteWidth: number,
  defaultNoteHeight: number,
): FlowNote[] {
  return nodes
    .filter((n: any) => n.type === VF_NODE_TYPE.NOTE)
    .map((n: any) => ({
      node_id: n.id,
      position: { x: n.position.x, y: n.position.y },
      content: n.data?.content || '',
      color: n.data?.color || defaultNoteColor,
      width: n.data?.noteWidth || defaultNoteWidth,
      height: n.data?.noteHeight || defaultNoteHeight,
    }));
}

/**
 * Resolves the live edges array from VueFlow flow store or falls back to local edges.
 */
export function getLiveEdges(flow: any, fallbackEdges: any[]): any[] {
  let liveEdges: any[] | null = null;

  if (flow) {
    if (Array.isArray(flow.getEdges)) {
      liveEdges = flow.getEdges;
    } else if (typeof flow.getEdges === 'function') {
      const getterEdges = flow.getEdges();
      if (Array.isArray(getterEdges)) {
        liveEdges = getterEdges;
      }
    } else if (typeof flow.toObject === 'function') {
      const exported = flow.toObject();
      if (Array.isArray(exported?.edges)) {
        liveEdges = exported.edges;
      }
    }
  }

  const localEdges = Array.isArray(fallbackEdges) ? fallbackEdges : [];
  return Array.isArray(liveEdges)
    ? liveEdges.length > 0 || localEdges.length === 0
      ? liveEdges
      : localEdges
    : localEdges;
}

/**
 * Determines the NodeType for a VueFlow node based on its visual type and data.
 */
export function resolveNodeType(node: any): NodeType {
  if (node.type === VF_NODE_TYPE.START) {
    return NodeType.START;
  } else if (node.type === VF_NODE_TYPE.CONTROL) {
    return (node.data?.nodeType as NodeType) || NodeType.DELAY;
  } else {
    return (node.data?.nodeType as NodeType) || NodeType.WHEN;
  }
}

/**
 * Builds a serialized AdvancedNode from a VueFlow node.
 * Variables must be pre-processed externally (via processVariablesForSave).
 */
export function buildSerializedNode(
  node: any,
  nodeType: NodeType,
  processedCard: any | null,
): any {
  const isControl = NodeTypeHelpers.requiresNoCard(nodeType);

  const serializedNode: any = {
    node_id: node.id,
    node_type: nodeType,
    card: processedCard,
    position: { x: node.position.x, y: node.position.y },
    label: node.data?.label || node.data?.card?.text || '',
  };

  if (isControl && node.data?.config) {
    serializedNode.config = node.data.config;
  }

  return serializedNode;
}

// ── Deserialization (Backend -> VueFlow) ─────────────────────────────

/**
 * Deserializes a backend START node to a VueFlow node.
 */
export function deserializeStartNode(
  node: any,
  index: number,
  $t: (key: string) => string,
): any {
  return {
    id: node.node_id,
    type: VF_NODE_TYPE.START,
    position: { x: node.position?.x || 0, y: node.position?.y || 0 },
    data: {
      nodeId: node.node_id,
      cardIndex: index,
      label: node.label || NODE_TYPE_TRANSLATION_KEYS[NodeType.START],
      tooltip: $t(NODE_TYPE_TOOLTIP_KEYS[NodeType.START]),
    },
  };
}

/**
 * Deserializes a backend control node (DELAY, ALL, ANY, OR) to a VueFlow node.
 */
export function deserializeControlNode(
  node: any,
  index: number,
  $t: (key: string) => string,
): any {
  return {
    id: node.node_id,
    type: VF_NODE_TYPE.CONTROL,
    position: { x: node.position?.x || 0, y: node.position?.y || 0 },
    data: {
      card: {
        card_type: node.node_type,
        text: node.label || NODE_TYPE_TRANSLATION_KEYS[node.node_type],
        variables: [],
      },
      nodeType: node.node_type,
      nodeId: node.node_id,
      cardIndex: index,
      config: node.config || {},
      label: node.label || NODE_TYPE_TRANSLATION_KEYS[node.node_type],
      tooltip: $t(NODE_TYPE_TOOLTIP_KEYS[node.node_type]),
    },
  };
}

/**
 * Deserializes a backend logic node (WHEN/AND/THEN) to a VueFlow node.
 * Card processing (variable resolution, missing card detection) is handled externally.
 */
export function deserializeLogicNode(
  node: any,
  index: number,
  card: any | null,
): any {
  return {
    id: node.node_id,
    type: node.node_type === NodeType.START ? VF_NODE_TYPE.START : VF_NODE_TYPE.LOGIC,
    position: { x: node.position?.x || 0, y: node.position?.y || 0 },
    data: {
      card,
      cardIndex: index,
      nodeId: node.node_id,
      nodeType: node.node_type,
    },
  };
}

/**
 * Deserializes backend notes to VueFlow NOTE nodes.
 */
export function deserializeNotes(
  notes: any[],
  defaultNoteColor: string,
  defaultNoteWidth: number,
  defaultNoteHeight: number,
  generateId: () => string,
): any[] {
  return notes.map((note: any) => {
    const nodeId = note.node_id || note.id || generateId();
    return {
      id: nodeId,
      type: VF_NODE_TYPE.NOTE,
      position: { x: note.position.x, y: note.position.y },
      connectable: false,
      selectable: true,
      data: {
        noteId: nodeId,
        content: note.content || '',
        color: note.color || defaultNoteColor,
        noteWidth: note.width || defaultNoteWidth,
        noteHeight: note.height || defaultNoteHeight,
      },
    };
  });
}

// ── ID counter extraction ────────────────────────────────────────────

/**
 * Finds the maximum numeric ID from an array of nodes (for nodeIdCounter).
 */
export function extractMaxNodeId(nodes: any[]): number {
  return nodes.reduce((max: number, node: any) => {
    const match = node.id.match(/\d+/);
    return match ? Math.max(max, parseInt(match[0])) : max;
  }, 0);
}

/**
 * Finds the maximum numeric ID from an array of edges (for edgeIdCounter).
 * Expects edge IDs in format "edge-N".
 */
export function extractMaxEdgeId(edges: any[]): number {
  return edges.reduce((max: number, edge: any) => {
    const match = edge.id.match(/edge-(\d+)/);
    return match ? Math.max(max, parseInt(match[1])) : max;
  }, 0);
}

/**
 * Checks if a backend node is a control node (not START).
 */
export function isNonStartControlNode(nodeType: string): boolean {
  return (
    (CONTROL_NODE_TYPES as readonly string[]).includes(nodeType) &&
    nodeType !== NodeType.START
  );
}
