/**
 * Operator inversion for workflow condition nodes.
 *
 * Mirrors backend Operators(StrEnum) — each operator maps to its logical opposite.
 *
 * Note: match_any ↔ match_all is a De Morgan-style quantifier swap, not a pure
 * negation of a single predicate. The backend treats this as the standard way to
 * "reverse" a multi-match condition (flip between "any match" and "all must match").
 */

import { notify } from 'src/components/notifications/notify';
import { NodeType, VF_NODE_TYPE } from '../workflow-advanced-models';

export const OPERATOR_INVERT_MAP: Record<string, string> = {
  eq: 'neq',
  neq: 'eq',
  is: 'isnot',
  isnot: 'is',
  gt: 'le',
  le: 'gt',
  ge: 'lt',
  lt: 'ge',
  in: 'ot',
  ot: 'in',
  cont: 'not_cont',
  not_cont: 'cont',
  match_any: 'match_all',
  match_all: 'match_any',
};

export interface CardVariable {
  display_name?: string;
  data_type?: string;
  data?: string;
  [key: string]: any;
}

/**
 * Check whether a variable is an operator/comparison variable eligible for inversion.
 * Matches when:
 * - display_name contains 'operator' (e.g. 'operator', 'operator_any_all')
 * - display_name contains 'comparison' (e.g. 'comparison_operator')
 * - data_type === 'comparison_data'
 * AND the variable has a truthy `data` value.
 */
export function isOperatorVariable(v: CardVariable): boolean {
  const displayName = (v.display_name || '').toLowerCase();
  return (
    (displayName.includes('comparison') ||
      displayName.includes('operator') ||
      v.data_type === 'comparison_data') &&
    !!v.data
  );
}

/**
 * Returns true if the card has at least one operator variable that can be inverted.
 */
export function hasReversibleOperator(variables: CardVariable[]): boolean {
  return variables.some(
    (v) => isOperatorVariable(v) && !!OPERATOR_INVERT_MAP[String(v.data)],
  );
}

/**
 * Returns a new variables array with all operator/comparison variables inverted.
 * Non-operator variables are returned unchanged.
 */
export function invertCardVariables(variables: CardVariable[]): CardVariable[] {
  return variables.map((v) => {
    if (!isOperatorVariable(v)) return v;
    const inverted = OPERATOR_INVERT_MAP[String(v.data)];
    return inverted ? { ...v, data: inverted } : v;
  });
}

// ── Orchestration ────────────────────────────────────────────

/** Context interface for reverseNodeCondition — matches the component's `this`. */
export interface ReverseConditionContext {
  nodes: any[];
  workflowModel: Record<string, any>;
  flow: { setNodes: (nodes: any[]) => void };
  saveHistory: (force: boolean) => void;
  $t: (key: string) => string;
}

/**
 * Reverse (invert) the operator on the single selected WHEN/AND node.
 * This is the actual implementation used by workflow-designer-advanced.vue.
 */
export function reverseNodeCondition(ctx: ReverseConditionContext): void {
  const selectedNodes = ctx.nodes.filter(
    (n: any) => n.selected && n.type !== VF_NODE_TYPE.START,
  );
  if (selectedNodes.length !== 1) return;

  const node = selectedNodes[0];
  const nodeType = node.data?.nodeType;
  if (nodeType !== NodeType.WHEN && nodeType !== NodeType.AND) return;

  const card = node.data?.card;
  if (!card?.variables?.length) return;

  // For newly added cards, variable.data may still be empty while the
  // user's selection lives only in workflowModel. Sync before inverting.
  const variables: CardVariable[] = card.variables.map((v: CardVariable) => {
    const modelValue = v.uuid && ctx.workflowModel[v.uuid]?.value;
    return modelValue && modelValue !== v.data ? { ...v, data: String(modelValue) } : v;
  });

  if (!hasReversibleOperator(variables)) {
    notify.warning(ctx.$t('reverse_condition_no_operator'));
    return;
  }

  ctx.saveHistory(true);

  const updatedVariables = invertCardVariables(variables);

  const nodeIndex = ctx.nodes.findIndex((n: any) => n.id === node.id);
  if (nodeIndex !== -1) {
    const updatedNode = {
      ...ctx.nodes[nodeIndex],
      data: {
        ...ctx.nodes[nodeIndex].data,
        card: {
          ...card,
          variables: updatedVariables,
        },
      },
    };
    ctx.nodes.splice(nodeIndex, 1, updatedNode);

    for (const v of updatedVariables) {
      if (v.uuid && ctx.workflowModel[v.uuid] && isOperatorVariable(v)) {
        ctx.workflowModel[v.uuid].data = v.data;
        ctx.workflowModel[v.uuid].value = v.data;
        ctx.workflowModel[v.uuid].badgeValue = v.data;
      }
    }

    ctx.flow.setNodes([...ctx.nodes]);
  }

  notify.success(ctx.$t('reverse_condition_success'));
}
