import { i18n } from 'src/boot/i18n';

/**
 * Formats a Date into a human-readable relative time string.
 * Used by AdvancedWorkflowToolbar to show auto-save indicator.
 *
 * @param date - The date to format (null returns empty string)
 * @param now  - Current timestamp in ms (defaults to Date.now(), injectable for testing)
 */
export function formatAutoSaveTime(date: Date | null, now?: number): string {
  if (!date) return '';
  const diff = (now ?? Date.now()) - date.getTime();
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);

  if (minutes < 1) return i18n.t('just_now');
  if (minutes === 1) return i18n.t('n_minutes_ago', { n: 1 });
  if (minutes < 60) return i18n.t('n_minutes_ago', { n: minutes });

  const hours = Math.floor(minutes / 60);
  if (hours === 1) return i18n.t('n_hours_ago', { n: 1 });
  return i18n.t('n_hours_ago', { n: hours });
}
