import { HandleType, PathResult, NodeType } from '../workflow-advanced-models';
import { Position } from '@vue-flow/core';

export interface HandleSpec {
  id: string;
  type: 'source' | 'target';
  position: Position;
  handleClass: string;
}

/** Handle CSS class mapping based on handle id */
const HANDLE_CLASSES: Record<string, string> = {
  [HandleType.INPUT]: 'handle handle-input',
  [PathResult.SUCCESS]: 'handle handle-success',
  [PathResult.FAILED_CONDITION]: 'handle handle-failed-condition',
  [PathResult.ERROR]: 'handle handle-error',
};

function createHandleSpec(id: string, type: 'source' | 'target', position: Position): HandleSpec {
  return { id, type, position, handleClass: HANDLE_CLASSES[id] || 'handle' };
}

export const CARD_HANDLE_CONFIG: Record<string, HandleSpec[]> = {
  [NodeType.START]: [
    createHandleSpec(PathResult.SUCCESS, 'source', Position.Right),
  ],
  [NodeType.WHEN]: [
    createHandleSpec(PathResult.SUCCESS, 'source', Position.Right),
  ],
  [NodeType.AND]: [
    createHandleSpec(HandleType.INPUT, 'target', Position.Left),
    { ...createHandleSpec(PathResult.SUCCESS, 'source', Position.Right), handleClass: 'handle handle-success handle-right-paired' },
    { ...createHandleSpec(PathResult.FAILED_CONDITION, 'source', Position.Right), handleClass: 'handle handle-failed-condition handle-right-paired' },
    createHandleSpec(PathResult.ERROR, 'source', Position.Bottom),
  ],
  [NodeType.THEN]: [
    createHandleSpec(HandleType.INPUT, 'target', Position.Left),
    createHandleSpec(PathResult.SUCCESS, 'source', Position.Right),
    createHandleSpec(PathResult.ERROR, 'source', Position.Bottom),
  ],
  [NodeType.OR]: [
    createHandleSpec(HandleType.INPUT, 'target', Position.Left),
    createHandleSpec(PathResult.SUCCESS, 'source', Position.Right),
  ],
  [NodeType.DELAY]: [
    createHandleSpec(HandleType.INPUT, 'target', Position.Left),
    createHandleSpec(PathResult.SUCCESS, 'source', Position.Right),
  ],
  [NodeType.ALL]: [
    createHandleSpec(HandleType.INPUT, 'target', Position.Left),
    createHandleSpec(PathResult.SUCCESS, 'source', Position.Right),
  ],
  [NodeType.ANY]: [
    createHandleSpec(HandleType.INPUT, 'target', Position.Left),
    createHandleSpec(PathResult.SUCCESS, 'source', Position.Right),
  ],
};

/** Get handle specs for a node type, returns empty array for unknown types */
export function getHandlesForNodeType(nodeType: string): HandleSpec[] {
  return CARD_HANDLE_CONFIG[nodeType] || [];
}

/** Get source handles only (for edge validation) */
export function getSourceHandles(nodeType: string): HandleSpec[] {
  return getHandlesForNodeType(nodeType).filter(spec => spec.type === 'source');
}
