<template>
  <q-page padding class="body-bg body-height no-padding">
    <SubHeader
      name="advanced_workflow_builder"
      :label="$t('advanced_workflow_builder')"
      :show_expiry_alert="true"
      :onSearch="false"
    />

    <div class="row justify-center scrolle-y">
      <div class="col-12 q-pa-none">
        <AdvancedWorkflowToolbar
          :show="true"
          :conditionsList="conditionsList"
          :otherOptions="otherOptions"
          :footerOptions="footerOptions"
          :workflowName="workflowName"
          :saving="saving"
          :validating="validating"
          :testing="testing"
          :lastAutoSave="lastAutoSave"
          @update:workflowName="onWorkflowNameInput"
          @zoom-in="zoomInCanvas"
          @zoom-out="zoomOutCanvas"
          @undo="undoCanvas"
          @redo="redoCanvas"
          @add-node="handleAddNode"
          @save="saveWorkflow"
          @validate="validateWorkflow"
          @test="testWorkflow"
          @open-logs="openLogsPanel"
          @toggle-snap="toggleSnap"
          @toggle-minimap="toggleMiniMap"
          :snapEnabled="snapEnabled"
          @save-as-template="showSaveTemplateDialog = true"
          @show-shortcuts="showShortcutsHelp = true"
          @export-image="exportAsImage"
          @search-nodes="searchNodes"
          @edit-description="showDescriptionDialog = true"
          @show-variables="showVariablesPanel = true"
          :workflowId="workFlowId"
          :workflowEnabled="workflowEnabled"
          @toggle-enabled="toggleWorkflowEnabled"
        />

        <AdvancedWorkflowVariables
          v-model="showVariablesPanel"
          :variables="workflowVariables"
          @create="onCreateVariable"
          @update="onUpdateVariable"
          @delete="onDeleteVariable"
        />

        <div
          class="workflow-canvas-container"
          style="position: relative; width: 100%; height: 100%"
        >
          <div v-if="validationErrors.length > 0 || validationWarnings.length > 0" class="validation-banner-container">
            <div class="validation-banner-header">
              <q-icon :name="validationErrors.length > 0 && !validationIsWarning ? 'error' : 'warning'"
                      :color="validationErrors.length > 0 && !validationIsWarning ? 'red' : 'orange'" size="sm" class="q-mr-sm" />
              <div class="text-bold">
                <span v-if="validationErrors.length > 0 && !validationIsWarning" class="text-red-9">
                  {{ $t('workflow_has_validation_errors', { count: validationErrors.length }) }}
                </span>
                <span v-else-if="validationErrors.length > 0 && validationIsWarning" class="text-orange-9">
                  {{ $t('workflow_saved_with_warnings', { count: validationErrors.length }) }}
                </span>
                <span v-if="validationErrors.length > 0 && validationWarnings.length > 0" class="text-grey-6"> | </span>
                <span v-if="validationWarnings.length > 0" class="text-orange-9">
                  {{ $t('workflow_has_validation_warnings', { count: validationWarnings.length }) }}
                </span>
              </div>
              <q-space />
              <q-btn flat dense round icon="close" size="sm" @click="validationErrors = []; validationWarnings = []; clearNodeHighlights()" />
            </div>
            <div class="validation-items-scroll">
              <div v-for="(err, idx) in validationErrors" :key="'e-' + idx"
                   :class="['q-ml-sm validation-error-item', err.node_id ? 'cursor-pointer clickable-error' : '']"
                   @click="err.node_id && focusNode(err.node_id)">
                <q-icon name="error" color="red" size="xs" class="q-mr-xs" />
                {{ err.translation_key ? $t(err.translation_key, err.translation_params || {}) : err.message }}
              </div>
              <div v-for="(warn, idx) in validationWarnings" :key="'w-' + idx"
                   :class="['q-ml-sm validation-error-item', warn.node_id ? 'cursor-pointer clickable-error' : '']"
                   @click="warn.node_id && focusNode(warn.node_id)">
                <q-icon name="warning" color="orange" size="xs" class="q-mr-xs" />
                {{ warn.translation_key ? $t(warn.translation_key, warn.translation_params || {}) : warn.message }}
              </div>
            </div>
          </div>
          <VueFlow
            v-model:nodes="nodes"
            v-model:edges="edges"
            :zoom-on-scroll="zoomEnabled"
            :zoom-on-pinch="zoomEnabled"
            @connect="onConnect"
            @connectStart="isConnecting = true"
            @connectEnd="isConnecting = false"
            :zoomOnDoubleClick="false"
            :class="['workflow-canvas', { 'workflow-canvas--dark': $q.dark.isActive, 'workflow-canvas--connecting': isConnecting }]"
            ref="vueFlowRef"
            @contextmenu.prevent
            :edge-types="edgeTypes"
            :default-edge-options="{ type: 'removableEdge' }"
            @nodeDragStart="onNodeDragStart"
            :snap-to-grid="snapEnabled"
            :snap-grid="[20, 20]"
            :is-valid-connection="isValidConnection"
            :connection-line-style="connectionLineStyle"
            :translate-extent="translateExtent"
            :multi-selection-key-code="['Shift', 'Meta', 'Control']"
            :pan-on-drag="true"
            :nodes-draggable="!testing"
            :nodes-connectable="!testing"
            :elements-selectable="!testing"
          >
            <template #node-logicNode="{ data }">
              <div class="logic-node-wrapper" :class="{ 'tree-dimmed': isTreeDimmed(data.nodeId) }">
                <div class="node-tooltip-stack" v-if="data.testWarnings?.length || data.validationErrors?.length || getNodeTooltip(data.nodeType)">
                  <div class="node-custom-tooltip node-tooltip-warning" v-if="data.testWarnings?.length">
                    <div v-for="(w, i) in data.testWarnings" :key="i">{{ w.translation_key ? $t(w.translation_key, w.translation_params || {}) : (w.message || w) }}</div>
                  </div>
                  <div class="node-custom-tooltip node-tooltip-error" v-if="data.validationErrors?.length">
                    <div v-for="(err, i) in data.validationErrors" :key="i">{{ err.translation_key ? $t(err.translation_key, err.translation_params || {}) : (err.message || err) }}</div>
                  </div>
                  <div class="node-custom-tooltip" v-else-if="getNodeTooltip(data.nodeType)">
                    {{ getNodeTooltip(data.nodeType) }}
                  </div>
                </div>
                <!-- Target handles (input) -->
                <SmartHandle
                  v-for="handle in getHandlesForNodeType(data.nodeType).filter(h => h.type === 'target')"
                  :key="handle.id"
                  :type="handle.type"
                  :position="handle.position"
                  :id="handle.id"
                  :node-id="data.nodeId"
                  :handle-class="handle.handleClass"
                />

                <AdvancedWorkflowCard
                  :item="data.card"
                  :isDialog="false"
                  :parentSvg="data.card.svg"
                  :color="data.card.svg_background_color"
                  :version="data.card.card_version"
                  :itemIndex="data.cardIndex"
                  :class="getTestResultNodeClass(data.testResult, !!data.testWarnings?.length)"
                  @removeNode="removeNode"
                  @copyNode="copyNode"
                  @duplicateNode="duplicateNode"
                  :nodeId="data.nodeId"
                  :cardType="data.nodeType"
                  @createNote="createNote"
                  @testCard="handleTestCard"
                  @changeCardVersion="changeCardVersion"
                />

                <!-- Source handles (success, failed_condition, error) -->
                <SmartHandle
                  v-for="handle in getHandlesForNodeType(data.nodeType).filter(h => h.type === 'source')"
                  :key="handle.id"
                  :type="handle.type"
                  :position="handle.position"
                  :id="handle.id"
                  :node-id="data.nodeId"
                  :handle-class="handle.handleClass"
                  :is-connectable="true"
                />

                <!-- Execution order badge -->
                <div v-if="data.executionOrder" class="execution-order-badge">
                  {{ data.executionOrder }}
                </div>

                <!-- Test result indicator badge -->
                <div v-if="data.testResult" class="test-result-badge" :class="getTestResultBadgeClass(data.testResult)">
                  <q-icon :name="getTestResultIcon(data.testResult)" size="14px" />
                  <q-tooltip>
                    <div v-if="data.testResult.error">{{ data.testResult.error }}</div>
                    <div v-else-if="!data.testResult.executed">{{ $t('wf_skipped') }}</div>
                    <div v-else-if="data.testResult.path_taken">{{ data.testResult.path_taken }}</div>
                    <div v-else>{{ data.testResult.success ? $t('success') : $t('failed') }}</div>
                  </q-tooltip>
                </div>

                <div v-if="showDebugInfo" class="node-info-badge">
                  <span class="node-info-id">{{ data.nodeId }}</span>
                  <span class="node-info-type">{{ data.nodeType }}</span>
                  <span v-if="data.card?.id" class="node-info-card-id" @click.stop="copyToClipboard(data.card.id)">{{ data.card.id }}<q-tooltip>{{ $t('click_to_copy') }}</q-tooltip></span>
                  <span v-if="data.card?.card_type" class="node-info-card-type" @click.stop="copyToClipboard(data.card.card_type)">{{ data.card.card_type }}<q-tooltip>{{ $t('click_to_copy') }}</q-tooltip></span>
                  <span class="node-info-edges node-info-in" v-if="getNodeConnections(data.nodeId).in.length">
                    ← {{ getNodeConnections(data.nodeId).in.join(', ') }}
                  </span>
                  <span class="node-info-edges node-info-success" v-if="getNodeConnections(data.nodeId).success.length">
                    ✓ {{ getNodeConnections(data.nodeId).success.join(', ') }}
                  </span>
                  <span class="node-info-edges node-info-failed" v-if="getNodeConnections(data.nodeId).failed_condition.length">
                    ✗ {{ getNodeConnections(data.nodeId).failed_condition.join(', ') }}
                  </span>
                  <span class="node-info-edges node-info-error" v-if="getNodeConnections(data.nodeId).error.length">
                    ⚠ {{ getNodeConnections(data.nodeId).error.join(', ') }}
                  </span>
                </div>
                <div v-if="showDebugInfo && data.card?.variables?.length" class="node-debug-variables">
                  <div v-for="v in data.card.variables" :key="v.uuid" class="node-debug-var-row">
                    <span class="node-debug-var-name">{{ v.display_name }}</span>
                    <span class="node-debug-var-uuid">{{ v.uuid }}</span>
                    <span class="node-debug-var-value">{{ getDebugVarModel(v) }}</span>
                  </div>
                </div>

                <!-- Test log entries below node -->
                <div class="node-log-tooltip" v-if="data.testLogs?.length">
                  <div v-for="(entry, i) in data.testLogs" :key="i" class="node-log-entry">
                    <q-icon :name="getLogEntryIcon(entry)" :color="getLogEntryColor(entry)" size="14px" class="node-log-entry-icon" />
                    <span v-if="entry.translation_key">{{ $t('wf_log_' + entry.translation_key, translateData(entry.data)) }}</span>
                    <span v-else>{{ entry.message }}</span>
                  </div>
                </div>
              </div>
            </template>

            <template #node-startNode="{ data }">
              <div class="start-node-wrapper" :class="[getTestResultNodeClass(data.testResult, !!data.testWarnings?.length), { 'tree-dimmed': isTreeDimmed(data.nodeId), 'start-node--testing': testing }]">
                <q-tooltip>{{ $t('start_node_tooltip') }}</q-tooltip>
                <div class="start-node-inner start-node-play" @click.stop="testWorkflowDirect()">
                  <q-icon :name="testing ? 'hourglass_top' : 'play_arrow'" size="36px" color="white" :class="{ 'spin-icon': testing }" />
                </div>
                <SmartHandle
                  v-for="handle in getHandlesForNodeType(NodeType.START)"
                  :key="handle.id"
                  :type="handle.type"
                  :position="handle.position"
                  :id="handle.id"
                  :node-id="data.nodeId"
                  :handle-class="handle.handleClass"
                />
                <div v-if="data.testResult" class="test-result-badge test-result-badge-start" :class="getTestResultBadgeClass(data.testResult)">
                  <q-icon :name="getTestResultIcon(data.testResult)" size="14px" />
                </div>
                <div v-if="showDebugInfo" class="node-info-badge node-info-badge-start">
                  <span class="node-info-id">{{ data.nodeId }}</span>
                  <span class="node-info-type">start</span>
                  <span class="node-info-edges node-info-success" v-if="getNodeConnections(data.nodeId).success.length">
                    ✓ {{ getNodeConnections(data.nodeId).success.join(', ') }}
                  </span>
                </div>

                <div class="node-log-tooltip" v-if="data.testLogs?.length">
                  <div v-for="(entry, i) in data.testLogs" :key="i" class="node-log-entry">
                    <q-icon :name="getLogEntryIcon(entry)" :color="getLogEntryColor(entry)" size="14px" class="node-log-entry-icon" />
                    <span v-if="entry.translation_key">{{ $t('wf_log_' + entry.translation_key, translateData(entry.data)) }}</span>
                    <span v-else>{{ entry.message }}</span>
                  </div>
                </div>
              </div>
            </template>
            <template #node-controlNode="{ data }">
              <div
                class="control-node-wrapper"
                :class="['control-node-' + data.nodeType, getTestResultNodeClass(data.testResult, !!data.testWarnings?.length), { 'tree-dimmed': isTreeDimmed(data.nodeId) }]"
              >
                <!-- Target handles -->
                <SmartHandle
                  v-for="handle in getHandlesForNodeType(data.nodeType).filter(h => h.type === 'target')"
                  :key="handle.id"
                  :type="handle.type"
                  :position="handle.position"
                  :id="handle.id"
                  :node-id="data.nodeId"
                  :handle-class="'control-node-handle-input ' + handle.handleClass"
                />

                <div class="node-tooltip-stack" v-if="data.testWarnings?.length || data.validationErrors?.length || data.tooltip">
                  <div class="node-custom-tooltip node-tooltip-warning" v-if="data.testWarnings?.length">
                    <div v-for="(w, i) in data.testWarnings" :key="i">{{ w.translation_key ? $t(w.translation_key, w.translation_params || {}) : (w.message || w) }}</div>
                  </div>
                  <div class="node-custom-tooltip node-tooltip-error" v-if="data.validationErrors?.length">
                    <div v-for="(err, i) in data.validationErrors" :key="i">{{ err.translation_key ? $t(err.translation_key, err.translation_params || {}) : (err.message || err) }}</div>
                  </div>
                  <div class="node-custom-tooltip" v-else-if="data.tooltip">
                    {{ data.tooltip }}
                  </div>
                </div>

                <div class="control-node-content">
                  <div class="control-node-icon-wrapper">
                    <q-icon :name="getControlNodeIcon(data.nodeType)" size="24px" />
                  </div>
                  <span
                    v-if="
                      data.nodeType === NodeType.DELAY && data.config?.delay_seconds
                    "
                    class="control-node-detail"
                  >
                    {{ formatDelay(data.config.delay_seconds) }}
                  </span>
                  <span v-else class="control-node-label">{{
                    $t(data.label)
                  }}</span>
                </div>

                <!-- Source handles -->
                <SmartHandle
                  v-for="handle in getHandlesForNodeType(data.nodeType).filter(h => h.type === 'source')"
                  :key="handle.id"
                  :type="handle.type"
                  :position="handle.position"
                  :id="handle.id"
                  :node-id="data.nodeId"
                  :handle-class="handle.handleClass"
                />

                <!-- Execution order badge -->
                <div v-if="data.executionOrder" class="execution-order-badge">
                  {{ data.executionOrder }}
                </div>

                <div v-if="data.testResult" class="test-result-badge test-result-badge-control" :class="getTestResultBadgeClass(data.testResult)">
                  <q-icon :name="getTestResultIcon(data.testResult)" size="14px" />
                  <q-tooltip anchor="top middle" self="bottom middle">
                    <div v-if="data.testResult.error">{{ data.testResult.error }}</div>
                    <div v-else-if="!data.testResult.executed">{{ $t('wf_skipped') }}</div>
                    <div v-else>{{ data.testResult.success ? $t('success') : $t('failed') }}</div>
                  </q-tooltip>
                </div>
                <div v-if="showDebugInfo" class="node-info-badge node-info-badge-control">
                  <span class="node-info-id">{{ data.nodeId }}</span>
                  <span class="node-info-type">{{ data.nodeType }}</span>
                  <span class="node-info-edges node-info-in" v-if="getNodeConnections(data.nodeId).in.length">
                    ← {{ getNodeConnections(data.nodeId).in.join(', ') }}
                  </span>
                  <span class="node-info-edges node-info-success" v-if="getNodeConnections(data.nodeId).success.length">
                    ✓ {{ getNodeConnections(data.nodeId).success.join(', ') }}
                  </span>
                </div>

                <div class="node-log-tooltip" v-if="data.testLogs?.length">
                  <div v-for="(entry, i) in data.testLogs" :key="i" class="node-log-entry">
                    <q-icon :name="getLogEntryIcon(entry)" :color="getLogEntryColor(entry)" size="14px" class="node-log-entry-icon" />
                    <span v-if="entry.translation_key">{{ $t('wf_log_' + entry.translation_key, translateData(entry.data)) }}</span>
                    <span v-else>{{ entry.message }}</span>
                  </div>
                </div>
              </div>
            </template>
            <template #node-noteNode="{ data }">
              <noteCardForNodes
                :noteId="data.noteId"
                :initial-content="data.content || ''"
                :color="data.color || '#fef48a'"
                :initial-width="data.noteWidth || 280"
                :initial-height="data.noteHeight || 80"
                :zoom="viewport?.zoom || 1"
                @editNote="updateNoteContent"
                @resizeNote="resizeNote"
              />
            </template>
            <Background variant="lines" :gap="20" :size="1.5" :pattern-color="gridPatternColor" />
            <MiniMap
              v-if="showMiniMap"
              :node-color="getMiniMapNodeColor"
              :mask-color="$q.dark.isActive ? 'rgba(30, 30, 30, 0.7)' : 'rgba(240, 240, 240, 0.7)'"
              :style="{ backgroundColor: $q.dark.isActive ? '#1e1e1e' : '#ffffff' }"
              pannable
              zoomable
            />
          </VueFlow>

          <!-- Test Running Overlay -->
          <div v-if="testing" class="test-running-overlay">
            <q-spinner-orbit color="primary" size="4em" />
            <div class="text-body1 q-mt-md">{{ $t('running_test') }}</div>
          </div>

          <!-- Test Results Summary Banner -->
          <transition name="slide-down">
            <div v-if="testResultsSummary" class="test-results-summary-banner" :class="'test-result-' + testResultsSummary.status">
              <div class="test-summary-content">
                <q-icon
                  :name="testResultsSummary.status === 'success' ? 'check_circle' : testResultsSummary.status === 'error' ? 'error' : 'warning'"
                  size="sm"
                  class="q-mr-sm"
                />
                <span class="text-weight-medium">{{ $t(testResultsSummary.label) }}</span>
                <span v-if="testResultsSummary.executionTime" class="q-ml-sm text-caption">
                  {{ testResultsSummary.executionTime + 's' }}
                </span>
                <span v-if="testResultsSummary.warnings?.length" class="q-ml-sm text-caption text-orange cursor-pointer">
                  {{ testResultsSummary.warnings.length }} {{ $t('warnings') }}
                  <q-tooltip max-width="400px" class="text-body2">
                    <div v-for="(w, i) in testResultsSummary.warnings" :key="i" class="q-mb-xs">
                      {{ w.translation_key ? $t(w.translation_key, w.translation_params || {}) : (w.message || w) }}
                    </div>
                  </q-tooltip>
                </span>
              </div>
              <div class="test-summary-actions">
                <q-btn flat dense size="sm" :label="$t('details')" @click="showTestResults = true" />
                <q-btn flat dense size="sm" icon="close" @click="clearTestResults" />
              </div>
            </div>
          </transition>

          <AdvancedWorkflowContextMenu
            v-model="menuState"
            @add-node="handleAddNode"
            :conditionsList="conditionsList"
            :otherOptions="otherOptions"
            :footerOptions="footerOptions"
            :position-x="menuX"
            :position-y="menuY"
            :selected-nodes="nodes.filter(n => n.selected)"
            :selected-edges="edges.filter(e => e.selected)"
            :has-copied-nodes="hasCopiedNodes"
            @pasteNodes="pasteNodes"
            @copyNode="copySelectedNodes"
            @duplicateNodes="duplicateSelectedNodes"
            @replaceNode="replaceSelectedNode"
            @testFromNode="testFromNode"
            @reverseNode="reverseNodeCondition"
            @removeNode="removeSelectedNodes"
            @changeNoteColor="changeNoteColor"
            @deleteNote="deleteNote"
          />

        </div>
      </div>
    </div>

    <WorkflowCardPickerDialog
      v-model="showItemPanel"
      :card-type="cardType"
      :category="category"
      :filtered-cards="filteredCardsList"
      :active-sub-category="activeSubCategory"
      :search-value="search"
      @update:search-value="inputSearchValueChanges"
      @select-category="setSubCategory"
    >
      <template #cards="{ cards, svg }">
        <AdvancedWorkflowCard
          v-for="(card, key) in cards"
          :key="key + '_' + card.id"
          :item="card"
          :itemIndex="Number(key)"
          :isDialog="true"
          :parentSvg="svg"
          :color="card.svg_background_color"
          :version="version"
          @onCardClick="onCardClick"
        />
      </template>
    </WorkflowCardPickerDialog>

    <!-- Execution Logs Drawer -->
    <q-drawer
      v-model="showLogsPanel"
      side="right"
      :width="420"
      overlay
      bordered
      class="logs-drawer"
    >
      <q-toolbar class="bg-primary text-white">
        <q-toolbar-title>{{
          $t('execution_logs')
        }}</q-toolbar-title>
        <q-btn
          flat
          round
          dense
          icon="refresh"
          @click="loadExecutionLogs"
          :loading="logsLoading"
        />
        <q-btn flat round dense icon="close" @click="showLogsPanel = false" />
      </q-toolbar>

      <q-list v-if="!selectedLogDetail" separator>
        <q-item
          v-for="(log, idx) in executionLogs"
          :key="log.node_id || idx"
          clickable
          @click="loadLogDetail(log.node_id)"
        >
          <q-item-section avatar>
            <q-icon
              :name="
                log.status === 'success'
                  ? 'check_circle'
                  : log.status === 'error'
                    ? 'error'
                    : log.status === 'skipped'
                      ? 'skip_next'
                      : 'warning'
              "
              :color="
                log.status === 'success'
                  ? 'positive'
                  : log.status === 'error'
                    ? 'negative'
                    : log.status === 'skipped'
                      ? 'grey'
                      : 'warning'
              "
            />
          </q-item-section>
          <q-item-section>
            <q-item-label>{{ log.label || log.node_type }}</q-item-label>
            <q-item-label caption>{{ log.node_type }}{{ log.card_type ? ' — ' + log.card_type : '' }}</q-item-label>
          </q-item-section>
          <q-item-section side>
            <q-badge
              :color="log.success ? 'positive' : log.status === 'skipped' ? 'grey' : 'negative'"
            >
              {{ log.duration_ms != null ? log.duration_ms + 'ms' : '-' }}
            </q-badge>
          </q-item-section>
        </q-item>
        <q-item v-if="executionLogs.length === 0 && !logsLoading">
          <q-item-section class="text-grey text-center">
            {{ $t('no_execution_logs') }}
          </q-item-section>
        </q-item>
      </q-list>

      <!-- Log Detail View -->
      <div v-if="selectedLogDetail" class="q-pa-md">
        <q-btn
          flat
          dense
          icon="arrow_back"
          :label="$t('back')"
          @click="selectedLogDetail = null"
          class="q-mb-md"
        />
        <div class="text-subtitle1 q-mb-sm">
          {{ selectedLogDetail.label || selectedLogDetail.node_type }}
        </div>
        <div class="text-caption q-mb-md text-grey">
          <q-badge
            :color="selectedLogDetail.success ? 'positive' : selectedLogDetail.status === 'skipped' ? 'grey' : 'negative'"
          >
            {{ selectedLogDetail.status }}
          </q-badge>
          <span class="q-ml-sm">{{ selectedLogDetail.duration_ms }}ms</span>
          <span class="q-ml-sm text-grey-6">{{ selectedLogDetail.node_type }}{{ selectedLogDetail.card_type ? ' — ' + selectedLogDetail.card_type : '' }}</span>
        </div>

        <div v-if="selectedLogDetail.error" class="q-mb-md text-negative">
          <q-icon name="error" size="xs" class="q-mr-xs" />
          {{ selectedLogDetail.error }}
        </div>

        <q-list v-if="selectedLogDetail.logs?.length" separator dense bordered class="rounded-borders">
          <q-item v-for="(entry, idx) in selectedLogDetail.logs" :key="idx" dense>
