const DEFAULT_DELAY_SECONDS = 60;

// Auto-save key helpers are imported from workflowAutoSave.ts

interface CopiedNodesData {
  nodes: Node[];
  edges: Edge[];
  variableValues?: Record<string, any>;
}

export default defineComponent({
  name: 'AdvancedWorkflowBuilder',
  mixins: [Cache, helperMixin],
  props: {
    zoomEnabled: {
      type: Boolean,
      default: true,
    },
  },
  components: {
    VueFlow,
    Handle,
    SmartHandle,
    SubHeader,
    AdvancedWorkflowToolbar,
    AdvancedWorkflowCard,
    AdvancedWorkflowContextMenu,
    noteCardForNodes,
    WorkflowTestResultDialog,
    WorkflowTestDocumentPicker,
    AdvancedWorkflowVariables,
    WorkflowCardPickerDialog,
    MiniMap,
    Background,
    Loader,
  },
  setup(): Record<string, any> {
    const vueFlowRef = ref<typeof VueFlow | null>(null);
    // Store full vueFlow instance to eliminate duplicate calls
    const vueFlow = useVueFlow();
    const { onPaneContextMenu, onNodeContextMenu, viewport, onNodesChange } = vueFlow;
    const { startHandle, endHandle, status } = useConnection();
    const menuState = ref(false);
    const menuX = ref(0);
    const menuY = ref(0);
    const menuOpenedAt = ref(0);
    // Store cleanup object for context menu - has off() method
    const contextMenuCleanup = onPaneContextMenu((event: MouseEvent) => {
      if (event.button === 2 && vueFlowRef.value) {
        event.preventDefault();
        event.stopPropagation();

        // Clear node/edge selection — pane click means no node context
        vueFlow.removeSelectedElements();

        menuX.value = event.clientX;
        menuY.value = event.clientY;
        menuState.value = true;
        menuOpenedAt.value = Date.now();
        // Store flow-space position for node placement (accounts for canvas offset and zoom)
        lastContextMenuFlowPosition.value = vueFlow.screenToFlowCoordinate({
          x: event.clientX,
          y: event.clientY,
        });
      }
    });

    const lastContextMenuFlowPosition = ref<{ x: number; y: number } | null>(null);

    onNodeContextMenu(({ event, node }: { event: MouseEvent; node: any }) => {
      event.preventDefault();
      event.stopPropagation();

      if (!node.selected) {
        // Node wasn't part of existing selection — deselect everything, select only this node
        vueFlow.removeSelectedElements();
        vueFlow.addSelectedNodes([node]);
      }

      menuX.value = event.clientX;
      menuY.value = event.clientY;
      menuState.value = true;
      menuOpenedAt.value = Date.now();
      lastContextMenuFlowPosition.value = vueFlow.screenToFlowCoordinate({
        x: event.clientX,
        y: event.clientY,
      });
    });

    const zoom = ref(1);
    const viewportX = ref(0);
    const viewportY = ref(0);
    // Use vueFlow instance from above instead of creating duplicate
    const { onMove } = vueFlow;

    // Store cleanup object for viewport listener - has off() method
    const zoomListenerCleanup = onMove(({ flowTransform }) => {
      zoom.value = flowTransform.zoom;
      viewportX.value = flowTransform.x;
      viewportY.value = flowTransform.y;
    });

    // Listen for node changes (including deletions by VueFlow's built-in handlers)
    // Note: START node management handled by watch:nodes in component
    const nodesChangeCleanup = onNodesChange(() => {});

    // Clean up event listeners when component unmounts
    onBeforeUnmount(() => {
      contextMenuCleanup?.off();
      zoomListenerCleanup?.off();
      nodesChangeCleanup?.off();
    });

    const shared = useWorkflowStoreSetup();

    return {
      ...shared,
      vueFlow: vueFlow as any, // Expose VueFlow instance to Options API (cast to avoid deep type serialization)
      search: ref(''),
      getControlNodeIcon,
      getLogEntryIcon,
      getLogEntryColor,
      EDGE_STROKE_COLORS,
      translateData,
      getTestResultNodeClass,
