  computed: {
    gridPatternColor(): string {
      const zoom = this.viewport?.zoom ?? 1;
      // Interpolate opacity: 0.05 at min zoom (0.5), 0.08 at max zoom (2)
      const opacity = 0.05 + (zoom - 0.5) / (2 - 0.5) * (0.08 - 0.05);
      const clamped = Math.min(0.08, Math.max(0.05, opacity));
      return this.$q.dark.isActive
        ? `rgba(255, 255, 255, ${clamped.toFixed(3)})`
        : `rgba(0, 0, 0, ${clamped.toFixed(3)})`;
    },
    // Show debug info badges on nodes when ?debug is in URL
    showDebugInfo() {
      return this.$route.query.debug !== undefined;
    },
    // Test results are currently displayed on canvas
    hasTestResults(): boolean {
      return !!this.testResultsSummary;
    },
    // Returns the single selected node ID for tree highlighting, or null
    treeHighlightNodeId(): string | null {
      if (this.hasTestResults) return null;
      const selected = this.nodes.filter((n: any) => n.selected);
      if (selected.length !== 1) return null;
      // Skip path highlighting for note nodes
      if (selected[0].type === VF_NODE_TYPE.NOTE) return null;
      return selected[0].id;
    },
    // Access VueFlow instance from setup() - eliminates duplicate useVueFlow() calls
    flow(): any {
      return this.vueFlow;
    },
    connectionLineStyle() {
      // No active connection
      if (!this.startHandle) {
        return {};
      }

      // Dragging with no target hovered
      if (!this.endHandle) {
        return {
          stroke: EDGE_STROKE_COLORS.success,
          strokeWidth: 2,
        };
      }

      // Valid target
      if (this.connectionStatus === 'valid') {
        return {
          stroke: NODE_STATUS_HEX_COLORS.success,
          strokeWidth: 3,
        };
      }

      // Invalid target
      if (this.connectionStatus === 'invalid') {
        return {
          stroke: NODE_STATUS_HEX_COLORS.error,
          strokeWidth: 3,
        };
      }

      return {};
    },
    /**
     * Calculate dynamic panning bounds based on node positions
     * Allows user to pan with some padding but prevents scrolling too far from workflow
     */
    translateExtent(): [[number, number], [number, number]] {
      if (!this.nodes || this.nodes.length === 0) {
        return [[-2000, -2000], [2000, 2000]];
      }

      const padding = 1000;
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

      this.nodes.forEach((node) => {
        const x = node.position?.x || 0;
        const y = node.position?.y || 0;
        minX = Math.min(minX, x);
        minY = Math.min(minY, y);
        maxX = Math.max(maxX, x);
        maxY = Math.max(maxY, y);
      });

      return [
        [minX - padding, minY - padding],
        [maxX + padding + 800, maxY + padding + 800],
      ];
    },
  },
  watch: {
    // Watch for node changes and manage START nodes accordingly
    nodes: {
      handler(newNodes, oldNodes) {
        if (this.isRestoring) return; // Skip during undo/redo restore
        // Only react to length changes (nodes added/removed)
        if (!oldNodes || newNodes.length !== oldNodes.length) {
          // Check if this was a removal (length decreased)
          if (oldNodes && newNodes.length < oldNodes.length) {
            // Use nextTick to ensure DOM and state are updated
            this.$nextTick(() => {
              this.manageStartNodes();
            });
          }
          // Remove onboarding notes when user adds their first real card
          if (newNodes.length > 1 && this.nodes.some((n: any) => n.type === VF_NODE_TYPE.NOTE && n.data?.isOnboarding)) {
            this.removeOnboardingNotes();
          }
          // Keep selectedThenCards in sync for DocOperator script_data handling
          this.syncSelectedThenCards();
        }
      },
      deep: false, // Don't watch deep changes, only array length
    },
    // Card variable widgets write straight into the shared store model,
    // so this watcher is the only seam that sees those edits.
    workflowModel: {
      handler() {
        this.markUnsavedChanges();
      },
      deep: true,
    },
    treeHighlightNodeId(nodeId: string | null) {
      if (nodeId) {
        applyTreeHighlight(this,nodeId);
      } else {
        clearTreeHighlight(this);
      }
    },
  },
  async mounted() {
    this.showLoading();
    this.indexToRemove = null;
    this.workFlowId = this.$route.params.id as string;
    try {
      await runWithBackendUnavailableWarning(async () => {
        (<any>window).vpo = this;

        let workflowResponse: any = null;
        const loadTasks: Promise<unknown>[] = [
          this.getWorkflowAllCards(),
          this.initChildDropdowns(),
        ];
        // Load org-level variables (non-blocking — don't hold up workflow load)
        this.loadOrgWorkflowVariables();
        if (this.workFlowId) {
          this.loading = true;
          loadTasks.push(
            this.fetchWorkflow().then((response) => {
              workflowResponse = response;
            }),
          );
        }
        await Promise.allSettled(loadTasks);

        this.filteredCardsList = this.cards;

        if (this.workFlowId) {
          try {
            if (workflowResponse) {
              await this.applyWorkflow(workflowResponse);
            }
          } finally {
            this.loading = false;
          }
          // Check if this is a reload (sessionStorage flag set by beforeunload)
          if (checkReloadFlag(this.workFlowId)) {
            this.restoreFromAutoSave();
          } else {
            // Fresh navigation — clear any stale auto-save for this workflow
            clearStaleAutoSave(this.workFlowId);
          }
        } else {
          // New workflow: check sessionStorage reload flag
          if (checkReloadFlag()) {
            this.restoreFromAutoSave();
          } else {
            // Fresh navigation — clear any stale auto-save for unnamed workflows
            clearStaleAutoSave();
          }
        }
      }, 'WorkflowDesignerAdvanced');
    } catch (err) {
      console.error('[WorkflowDesignerAdvanced] mount failed:', err);
    }

    // Ensure START nodes are correctly managed after load/restore
    this.manageStartNodes();

    // Save initial state to history for undo support (new workflows only —
    // loaded workflows handle this in loadWorkflow after deserialization)
    if (!this.workFlowId) {
      this.$nextTick(() => {
        if (this.history.length === 0) {
          this.saveHistory(true);
          this.hasUnsavedChanges = false;
        }
      });
    }

    // Start auto-save interval (every 30 seconds, only if changes exist)
    this.autoSaveInterval = setInterval(() => {
      if (this.hasUnsavedChanges) {
        this.autoSaveToLocalStorage();
      }
    }, AUTOSAVE_INTERVAL_MS);

    window.addEventListener('keydown', this.handleKeydown);
    window.addEventListener('beforeunload', this.handleBeforeUnload);
    document.addEventListener('click', this.handleMenuClose);
    this.hideLoading();
  },
  beforeUnmount() {
    window.removeEventListener('keydown', this.handleKeydown);
    window.removeEventListener('beforeunload', this.handleBeforeUnload);
    document.removeEventListener('click', this.handleMenuClose);
    if (this.autoSaveInterval) {
      clearInterval(this.autoSaveInterval);
    }
    if (this.autoSaveDialog) {
      this.autoSaveDialog.hide();
      this.autoSaveDialog = null;
    }
  },
  async beforeRouteLeave() {
    if (this.hasUnsavedChanges) {
      return new Promise<boolean>((resolve) => {
        this.$q
          .dialog({
            title: this.$t('unsaved_changes'),
            message: this.$t('unsaved_changes_leave'),
            cancel: {
              label: this.$t('cancel'),
              flat: true,
            },
            ok: {
              label: this.$t('leave'),
              color: 'negative',
            },
            persistent: true,
          })
          .onOk(() => resolve(true))
          .onCancel(() => resolve(false));
      });
    }
  },
  methods: {
    /**
     * Sync selectedThenCards in the store from VueFlow nodes.
     * Required for DocOperator script_data handling — the store's
     * setDocOperatorVariables and the generic-dropdown-searchable
     * component iterate selectedThenCards to find sibling script_data variables.
     */
    syncSelectedThenCards() {
      this.selectedThenCards = this.nodes
        .filter((n: any) => n.data?.nodeType === NodeType.THEN && n.data?.card)
        .map((n: any) => n.data.card);
    },

    handleMenuClose(event: MouseEvent) {
      // Ignore right-clicks (they open the menu, shouldn't close it)
      if (event.button === 2) {
        return;
      }

      // Ignore clicks that happen immediately after opening (prevents race condition)
      if (Date.now() - this.menuOpenedAt < 200) {
        return;
      }

      // Menu is teleported to body, so query from document
      const menuEl = document.querySelector('.custom-context-menu');

      // Close menu if clicked outside
      if (!menuEl || !menuEl.contains(event.target as unknown as globalThis.Node)) {
        this.menuState = false;
      }
    },
    async initChildDropdowns() {
      await sharedInitChildDropdowns(this);
    },
    zoomInCanvas() {
      this.flow.zoomIn();
    },
    zoomOutCanvas() {
      this.flow.zoomOut();
    },
    /**
     * Recreates full edge configuration (lost during JSON serialization).
     * Restores style, label, labelStyle, and data.remove function.
     * Uses lazy recreation - skips if data already complete (performance optimization).
     */
    getEdges(): any[] {
      return this.edges;
    },
    recreateEdgeData(edge: any) {
      return recreateEdgeDataImpl(this, edge, EDGE_LABEL_STYLE);
    },
    async undoCanvas() {
      await undoCanvasImpl(this);
    },
    async redoCanvas() {
      await redoCanvasImpl(this);
    },
    saveHistory(immediate = false) {
      saveHistoryWrapperImpl(this, immediate);
    },
    saveHistoryImmediate() {
      saveHistoryImmediateImpl(this);
    },
    debouncedSaveHistory: debounce(function (this: any) {
      this.saveHistoryImmediate();
    }, 100),
    setCardType(cardType: string) {
      this.cards = [];
      this.cardType = cardType;
      this.filteredCardsList.cards = [];
      this.filteredCardsList.cardType = cardType;
      this.filteredCardsList.category = this.getCardsByType(cardType);
      this.category = this.getCardsByType(cardType);
      this.displayAllCards();
      this.activeSubCategory = '';
      this.showItemPanel = true;
    },
    displayAllCards() {
      this.filteredCardsList.cards = [];
      this.allCardsListForCardType = [];
      this.selectedSubCategory = false;
      const allCards = this.getAllCards();
      this.allCardsListForCardType = allCards;
      this.filteredCardsList.cards = allCards;
      this.filterDeprecatedCards();
      this.filterLatestCardVersion();
      this.filterVersionOneConditionCards();
    },
    setSubCategory(cards: any) {
      // Toggle off if clicking same category
      if (
        this.activeSubCategory === cards.category &&
        this.selectedSubCategory
      ) {
        this.selectedSubCategory = false;
        this.activeSubCategory = '';
        this.cards = null;
        // Show all cards when deselecting category
        this.filteredCardsList.cards = this.allCardsListForCardType;
        this.inputSearchValueChanges(this.search_value);
        return;
      }
      this.version = '';
      this.selectedSubCategory = true;
      this.activeSubCategory = cards.category;
      if (cards && cards.cards) {
        this.cards = cards;
        this.filteredCardsList.cards = cards.cards;
        this.filterDeprecatedCards();
        this.filterLatestCardVersion();
        this.filterVersionOneConditionCards();
        this.filteredCardsList.cards = assignCategoryColor(
          this.filteredCardsList.cards,
          cards.svg_background_color,
        );
      }

      this.inputSearchValueChanges(this.search_value);
      this.clearTestResults();
    },
    inputSearchValueChanges(search_value: any) {
      this.search = search_value;
      this.search_value = search_value;
      this.filteredCardsList.cards = resolveCardSearch(
        search_value,
        this.selectedSubCategory,
        this.cards?.cards || null,
        this.allCardsListForCardType,
        this.$t,
      );
      if (this.selectedSubCategory && this.cards?.svg_background_color) {
        this.filteredCardsList.cards = assignCategoryColor(
          this.filteredCardsList.cards,
          this.cards.svg_background_color,
        );
      }
      this.filterDeprecatedCards();
      this.filterLatestCardVersion();
      this.filterVersionOneConditionCards();
    },
    filterLatestCardVersion() {
      filterLatestCardVersionImpl(this.filteredCardsList);
    },
    filterDeprecatedCards() {
      filterDeprecatedCardsImpl(this.filteredCardsList);
    },
    filterVersionOneConditionCards() {
      filterVersionOneConditionCardsImpl(this.filteredCardsList);
    },
    /**
     * Manages START nodes based on WHEN node presence.
     *
     * Backend validation rules:
     * - If WHEN nodes exist: Must have 0 START nodes
     * - If no WHEN nodes: Must have exactly 1 START node
     *
     * This method ensures workflows comply with these rules.
     */
    manageStartNodes() {
      manageStartNodesImpl(this, START_NODE_POSITION);
    },
    onCardClick(card: any) {
      if (this.testResultsSummary) this.clearTestResults();

      this.saveHistory(true);

      const clonedItem = JSON.parse(JSON.stringify(card));

      // Replace existing node
      if (this.indexToRemove !== null && this.indexToRemove >= 0 && this.indexToRemove < this.nodes.length) {
        const oldNode = this.nodes[this.indexToRemove];
        const oldNodeId = oldNode.id;

        // Clean up old workflowModel entries
        if (oldNode.data?.card?.variables) {
          for (const variable of oldNode.data.card.variables) {
            if (variable.uuid && this.workflowModel[variable.uuid]) {
              delete this.workflowModel[variable.uuid];
            }
          }
        }

        // Initialize new card variables
        initializeCardVariables(clonedItem.variables, this.workflowModel, this.getComponentName);

        // Replace the node in-place, keeping position and id so edges stay connected
        const replacementNode = {
          ...oldNode,
          type: this.cardType === NodeType.START ? VF_NODE_TYPE.START : VF_NODE_TYPE.LOGIC,
          data: {
            card: clonedItem,
            cardIndex: this.indexToRemove,
            nodeId: oldNodeId,
            nodeType: this.cardType,
          },
        };

        this.nodes.splice(this.indexToRemove, 1, replacementNode);
        this.flow.setNodes([...this.nodes]);

        this.indexToRemove = null;
        this.showItemPanel = false;
        this.activeSubCategory = '';

        if (this.cardType === NodeType.WHEN) {
          this.manageStartNodes();
        }

        this.syncSelectedThenCards();
        return;
      }

      // Add new node
      const nodeId = `logic-${this.nodeIdCounter}`;
      const position = getNewNodePosition(this);

      const newNode = {
        id: nodeId,
        type: this.cardType === NodeType.START ? VF_NODE_TYPE.START : VF_NODE_TYPE.LOGIC,
        position,
        data: {
          card: clonedItem,
          cardIndex: this.nodes.length,
          nodeId: nodeId,
          nodeType: this.cardType,
        },
      };

      this.flow.addNodes([newNode]);
      this.nodes.push(newNode);
      this.nodeIdCounter++;

      initializeCardVariables(clonedItem.variables, this.workflowModel, this.getComponentName);

      if (this.cardType === NodeType.WHEN) {
        this.manageStartNodes();
      }

      this.indexToRemove = null;
      this.showItemPanel = false;
      this.activeSubCategory = '';
      this.syncSelectedThenCards();
    },
    replaceCard(indexToRemove: number, cardType: string) {
      this.indexToRemove = indexToRemove;
      this.setCardType(cardType);
    },
    getComponentName(display_name: string) {
      return sharedGetComponentName(display_name);
    },
    initWorkFlowMode(variable: any, isDefaultElement: boolean) {
      sharedInitWorkFlowMode(
        this.workflowModel,
        variable,
        isDefaultElement,
        this.docOperatorVariables,
      );
    },
    handleAddNode(payload: any) {
      if (payload.type === 'condition') {
        this.setCardType(payload.item.label.toLowerCase());
      } else {
        const nodeName = (payload.item?.name || '').toLowerCase();
        if ([NodeType.DELAY, NodeType.ALL, NodeType.ANY, NodeType.OR].includes(nodeName as NodeType)) {
          this.addControlNode(nodeName);
        } else if (nodeName === NodeType.NOTE) {
          this.createStandaloneNote();
        }
      }
      this.menuState = false;
    },
    createStandaloneNote() {
      this.saveHistory(true);
      const noteId = 'note-' + uid();
      // Use flow-space position captured when context menu opened
      const flowPos = this.lastContextMenuFlowPosition || {
        x: (this.menuX - this.viewportX) / this.zoom,
        y: (this.menuY - this.viewportY) / this.zoom,
      };
      const noteNode = {
        id: noteId,
        type: VF_NODE_TYPE.NOTE,
        position: { x: flowPos.x, y: flowPos.y },
        connectable: false,
        selectable: true,
        data: {
          noteId,
          content: '',
          color: DEFAULT_NOTE_COLOR,
          noteWidth: DEFAULT_NOTE_WIDTH,
          noteHeight: DEFAULT_NOTE_HEIGHT,
        },
      };
      this.flow.addNodes([noteNode]);
      this.nodes.push(noteNode);
    },
    addControlNode(nodeType: string) {
      if (this.testResultsSummary) this.clearTestResults();

      this.saveHistory(true);

      const nodeId = `${nodeType}-${this.nodeIdCounter}`;
      this.nodeIdCounter++;

      const controlNodeConfig: Record<string, any> = {
        [NodeType.DELAY]: {
          label: NODE_TYPE_TRANSLATION_KEYS[NodeType.DELAY],
          config: { delay_seconds: DEFAULT_DELAY_SECONDS },
          tooltip: this.$t(NODE_TYPE_TOOLTIP_KEYS[NodeType.DELAY]),
        },
        [NodeType.ALL]: {
          label: NODE_TYPE_TRANSLATION_KEYS[NodeType.ALL],
          config: {},
          tooltip: this.$t(NODE_TYPE_TOOLTIP_KEYS[NodeType.ALL]),
        },
        [NodeType.ANY]: {
          label: NODE_TYPE_TRANSLATION_KEYS[NodeType.ANY],
          config: {},
          tooltip: this.$t(NODE_TYPE_TOOLTIP_KEYS[NodeType.ANY]),
        },
        [NodeType.OR]: {
          label: NODE_TYPE_TRANSLATION_KEYS[NodeType.OR],
          config: {},
          tooltip: this.$t(NODE_TYPE_TOOLTIP_KEYS[NodeType.OR]),
        },
      };

      const cfg = controlNodeConfig[nodeType];
      if (!cfg) return;

      const position = getNewNodePosition(this);

      const newNode = {
        id: nodeId,
        type: VF_NODE_TYPE.CONTROL,
        position,
        data: {
          card: { card_type: nodeType, text: cfg.label, variables: [] },
          nodeType: nodeType,
          nodeId: nodeId,
          cardIndex: this.nodes.length,
          config: cfg.config,
          label: cfg.label,
          tooltip: cfg.tooltip,
        },
      };

      this.flow.addNodes([newNode]);
      this.nodes.push(newNode);

      if (nodeType === NodeType.DELAY) {
        this.showDelayConfigDialog = true;
        this.delayConfigNodeId = nodeId;
        this.delayConfigValue = DEFAULT_DELAY_SECONDS;
      }
    },
    confirmDelayConfig() {
      confirmDelayConfigImpl(this, MAX_DELAY_SECONDS);
    },
    cancelDelayConfig() {
      cancelDelayConfigImpl(this);
    },
    getNodeTooltip(cardType: string): string {
      const tooltips: Record<string, string> = {
        when: this.$t('when_node_tooltip'),
        and: this.$t('and_node_tooltip'),
        then: this.$t('then_node_tooltip'),
      };
      return tooltips[cardType] || '';
    },
    getNodeConnections(nodeId: string) {
      return getNodeConnectionsImpl(this.edges, nodeId);
    },
    copyToClipboard(text: string) {
      navigator.clipboard.writeText(text).then(() => {
        notify.success(this.$t('copied_to_clipboard'));
      });
    },
    getDebugVarModel(variable: any): string {
      const entry = variable.uuid ? this.workflowModel[variable.uuid] : null;
      if (!entry) return '(no model entry)';
      const val = entry.value;
      if (val === '' || val === null || val === undefined) return '(empty)';
      if (Array.isArray(val)) return JSON.stringify(val);
      return String(val);
    },
    formatDelay,
    onConnect(params: any) {
      const ctx: OnConnectContext = {
        nodes: this.nodes,
        edges: this.edges,
        edgeIdCounter: this.edgeIdCounter,
        flow: this.flow,
        saveHistory: (immediate: boolean) => this.saveHistory(immediate),
        isValidConnection: (p: any) => this.isValidConnection(p),
        getConnectionErrorReason: (p: any) => this.getConnectionErrorReason(p),
        getEdges: () => this.edges,
        notify,
      };
      onConnectImpl(ctx, params, EDGE_LABEL_STYLE);
      this.edgeIdCounter = ctx.edgeIdCounter;
    },
    removeSelectedNodes() {
      removeSelectedNodesImpl(this);
    },
    removeNode(nodeId: string, skipHistory = false) {
      removeNodeImpl(this, nodeId, skipHistory);
    },
    duplicateNode(nodeId: string, skipHistory = false) {
      const nodeToDuplicate = this.nodes.find((node) => node.id === nodeId);
      if (!nodeToDuplicate) {
        return;
      }

      const childNodeIds = getAllChildNodesAndSelf(this.edges, nodeId);
      const nodesToDuplicate = this.nodes.filter((node) =>
        childNodeIds.includes(node.id),
      );

      if (!skipHistory) this.saveHistory(true);

      const edgesToDuplicate = this.edges.filter(
        (edge) =>
          childNodeIds.includes(edge.source) &&
          childNodeIds.includes(edge.target),
      );

      const newNodeMap: Record<string, string> = {};
      const newNodes: Node[] = [];
      const newEdges: Edge[] = [];

      // Calculate a paste offset
      const offsetX = DUPLICATE_OFFSET;
      const offsetY = DUPLICATE_OFFSET;

      // Create new nodes with unique IDs and adjusted positions
      nodesToDuplicate.forEach((node) => {
        const originalId = node.id;
        const newId = this.getNewNodeId(node);
        newNodeMap[originalId] = newId;

        const clonedNode = JSON.parse(JSON.stringify(node));
        clonedNode.id = newId;
        clonedNode.selected = false;
        clonedNode.position = {
          x: node.position.x + offsetX,
          y: node.position.y + offsetY,
        };

        if (clonedNode.type === VF_NODE_TYPE.NOTE) {
          clonedNode.data.noteId = newId;
        } else {
          clonedNode.data.nodeId = newId;
          clonedNode.data.cardIndex = this.nodes.length + newNodes.length;

          if (clonedNode.type === VF_NODE_TYPE.LOGIC) {
            // Capture old UUIDs before they are replaced
            const oldUuids = (clonedNode.data.card.variables || []).map((v: any) => v.uuid);

            initializeCardVariables(clonedNode.data.card.variables, this.workflowModel, this.getComponentName);

            // Restore variable values and docOperator state from the original node
            (clonedNode.data.card.variables || []).forEach((variable: any, index: number) => {
              const oldUuid = oldUuids[index];
              if (oldUuid && this.workflowModel[oldUuid] && this.workflowModel[variable.uuid]) {
                this.workflowModel[variable.uuid].value = JSON.parse(JSON.stringify(this.workflowModel[oldUuid].value));
                this.workflowModel[variable.uuid].badgeValue = this.workflowModel[oldUuid].badgeValue;
              }
              if (oldUuid && this.docOperatorVariables[oldUuid]) {
                restoreDocOperatorState(
                  {
                    variables: this.docOperatorVariables[oldUuid],
                    sensitive: this.docOperatorVariablesSensitive[oldUuid],
                    locked: this.docOperatorLockedSensitiveData[oldUuid],
                  },
                  variable.uuid,
                  this.docOperatorVariables,
                  this.docOperatorVariablesSensitive,
                  this.docOperatorLockedSensitiveData,
                );
              }
            });
          }
        }
        newNodes.push(clonedNode);
      });

      // Create new edges with updated source and target IDs
      edgesToDuplicate.forEach((edge) => {
        const newEdge: Edge = {
          ...edge,
          id: `edge-${newNodeMap[edge.source]}-${edge.sourceHandle || 'default'}-${newNodeMap[edge.target]}`,
          source: newNodeMap[edge.source],
          target: newNodeMap[edge.target],
        };
        newEdges.push(newEdge);
      });

      // Filter out edges that would duplicate existing connections
      const existingEdgeKeys = new Set(
        this.edges.map((e: any) => `${e.source}:${e.sourceHandle || ''}:${e.target}:${e.targetHandle || ''}`),
      );
      const uniqueNewEdges = newEdges.filter((e) => {
        const key = `${e.source}:${e.sourceHandle || ''}:${e.target}:${e.targetHandle || ''}`;
        return !existingEdgeKeys.has(key);
      });

      this.flow.addNodes(newNodes);
      this.flow.addEdges(uniqueNewEdges);
      this.nodes.push(...newNodes);
      this.edges.push(...uniqueNewEdges);
    },
    copyNode(nodeId: string) {
      copyNodeImpl(this, nodeId);
    },
    copySelectedNodes() {
      copySelectedNodesImpl(this);
    },
    duplicateSelectedNodes() {
      const selectedNodes = this.nodes.filter((n: any) => n.selected && n.type !== VF_NODE_TYPE.START);
      if (selectedNodes.length === 0) return;

      this.saveHistory(true);
      for (const node of selectedNodes) {
        this.duplicateNode(node.id, true);
      }
    },
    replaceSelectedNode() {
      const selected = this.nodes.filter((n: any) => n.selected && n.type !== VF_NODE_TYPE.START);
      if (selected.length !== 1) return;

      const node = selected[0];
      const nodeType = node.data?.nodeType;
      if (!nodeType) return;

      // Map nodeType to cardType for the card selector
      const typeMap: Record<string, string> = { [NodeType.WHEN]: NodeType.WHEN, [NodeType.AND]: NodeType.AND, [NodeType.THEN]: NodeType.THEN };
      const cardType = typeMap[nodeType];
      if (!cardType) return;

      // Store the node index for replacement, then open the card selector
      const nodeIndex = this.nodes.findIndex((n: any) => n.id === node.id);
      this.replaceCard(nodeIndex, cardType);
    },
    changeCardVersion(card_version: string, card: any, _itemIndex: number, cardType: string, nodeId: string) {
      this.saveHistory(true);

      // Find the new version card from the store
      const cardStoreMap: Record<string, any> = {
        when: this.workflowWhenCards,
        and: this.workflowAndCards,
        then: this.workflowThenCards,
      };

      const category = cardStoreMap[cardType]?.find((cat: any) => cat.category === card.category);
      const card_to_change = category?.cards.find(
        (c: any) => c.card_version == card_version && c.id == card.id
      );

      if (!card_to_change) return;

      card_to_change.svg_background_color = card.svg_background_color;

      // Find and update the node
      const node = this.nodes.find((n: any) => n.id === nodeId);
      if (!node) return;

      // Clean up old workflowModel entries
      if (node.data.card?.variables) {
        for (const variable of node.data.card.variables) {
          if (variable.uuid) delete this.workflowModel[variable.uuid];
        }
      }

      // Clone and initialize variables (same as v2 pattern)
      const clonedCard = JSON.parse(JSON.stringify(card_to_change));
      clonedCard.svg_background_color = card.svg_background_color;

      initializeCardVariables(clonedCard.variables, this.workflowModel, this.getComponentName);

      // Create a completely new node object to trigger Vue reactivity
      const updatedNode = {
        ...node,
        data: {
          ...node.data,
          card: clonedCard,
        },
      };

      // Update in nodes array
      const nodeIndex = this.nodes.findIndex((n: any) => n.id === nodeId);
      if (nodeIndex !== -1) {
        this.nodes.splice(nodeIndex, 1, updatedNode);
        this.flow.setNodes([...this.nodes]);
      }
    },
    handleTestCard(payload: { card: any; nodeId: string; cardType: string }) {
      // Find the node in the workflow
      const node = this.nodes.find((n) => n.id === payload.nodeId);
      if (!node) return;

      // Use testFromNode with the specific node
      this.testFromNode(payload.nodeId);
    },
    async testFromNode(nodeIdParam?: string) {
      // Get the selected node or use param
      const selectedNodes = this.nodes.filter((n: any) => n.selected && n.type !== VF_NODE_TYPE.START);
      const nodeId = nodeIdParam || (selectedNodes.length === 1 ? selectedNodes[0].id : null);
      if (!nodeId) return;

      // Center viewport on the node
      const node = this.nodes.find((n: any) => n.id === nodeId);
      if (node) {
        this.flow.setCenter(
          node.position.x + NODE_CENTER_OFFSET_X,
          node.position.y + NODE_CENTER_OFFSET_Y,
          { zoom: 1, duration: VIEWPORT_ANIMATE_DURATION },
        );
      }

      // Set starting node for partial test execution
      this.startingNodeIds = [nodeId];
      await this.testWorkflow();
    },
    reverseNodeCondition() {
      reverseNodeConditionImpl(this);
    },
    getNewNodeId(node: any): string {
      if (node.type === VF_NODE_TYPE.NOTE) {
        return 'note-' + uid();
      }
      const cardType = node.data?.nodeType;
      if (node.type === VF_NODE_TYPE.CONTROL && [NodeType.DELAY, NodeType.ALL, NodeType.ANY].includes(cardType)) {
        return `${cardType}-${this.nodeIdCounter++}`;
      }
      return `logic-${this.nodeIdCounter++}`;
    },
    async pasteNodes(position?: XYPosition) {
      // Try localStorage first (no macOS permission prompt), then system clipboard
      let copiedData: CopiedNodesData | null = null;
      const copiedDataRaw = this.getDataByKey('copiedWorkflowNodes');
      if (typeof copiedDataRaw === 'string') {
        try {
          const parsed = JSON.parse(copiedDataRaw);
          if (parsed?.nodes && Array.isArray(parsed.nodes)) {
            copiedData = parsed;
          }
        } catch { /* invalid JSON in localStorage */ }
      }

      if (!copiedData) {
        try {
          const clipText = await navigator.clipboard.readText();
          const parsed = JSON.parse(clipText);
          if (parsed?.nodes && Array.isArray(parsed.nodes)) {
            copiedData = parsed;
          }
        } catch { /* clipboard not available */ }
      }

      if (!copiedData || !copiedData.nodes) {
        return;
      }

      this.saveHistory(true);

      const newNodeMap: Record<string, string> = {};
      const newNodes: Node[] = [];
      const newEdges: Edge[] = [];

      // When pasting via keyboard (no position), place relative to the first copied node with an offset
      let pastePosition: XYPosition;
      if (position) {
        // Convert screen coordinates to canvas coordinates
        const { x: offsetX, y: offsetY, zoom } = this.viewport;
        pastePosition = {
          x: (position.x - offsetX) / zoom,
          y: (position.y - offsetY) / zoom,
        };
      } else {
        const firstNode = copiedData.nodes[0];
        pastePosition = {
          x: firstNode.position.x + DUPLICATE_OFFSET,
          y: firstNode.position.y + DUPLICATE_OFFSET,
        };
      }

      // Create new nodes with unique IDs and adjusted positions
      copiedData.nodes.forEach((node) => {
        const originalId = node.id;
        const newId = this.getNewNodeId(node);
        newNodeMap[originalId] = newId;

        const clonedNode = JSON.parse(JSON.stringify(node));
        clonedNode.id = newId;
        clonedNode.selected = false;
        clonedNode.position = {
          x:
            pastePosition.x +
            (node.position.x - copiedData.nodes[0].position.x),
          y:
            pastePosition.y +
            (node.position.y - copiedData.nodes[0].position.y),
        };

        if (clonedNode.type === VF_NODE_TYPE.NOTE) {
          clonedNode.data.noteId = newId;
        } else {
          clonedNode.data.nodeId = newId;
          clonedNode.data.cardIndex = this.nodes.length + newNodes.length;

          if (clonedNode.type === VF_NODE_TYPE.LOGIC) {
            // Capture old variable UUIDs before initializeCardVariables replaces them
            const oldUuids = (clonedNode.data.card.variables || []).map((v: any) => v.uuid);

            initializeCardVariables(clonedNode.data.card.variables, this.workflowModel, this.getComponentName);

            // Restore saved variable values from copy data (old UUID → new UUID mapping by index)
            if (copiedData.variableValues) {
              (clonedNode.data.card.variables || []).forEach((variable: any, index: number) => {
                const oldUuid = oldUuids[index];
                const savedEntry = copiedData.variableValues![oldUuid];
                if (savedEntry && this.workflowModel[variable.uuid]) {
                  this.workflowModel[variable.uuid].value = savedEntry.value;
                  this.workflowModel[variable.uuid].badgeValue = savedEntry.badgeValue;
                }
                // Restore docOperator state for script_data variables
                if (copiedData.docOperatorData?.[oldUuid]) {
                  restoreDocOperatorState(
                    copiedData.docOperatorData[oldUuid],
                    variable.uuid,
                    this.docOperatorVariables,
                    this.docOperatorVariablesSensitive,
                    this.docOperatorLockedSensitiveData,
                  );
                }
              });
            }
          }
        }
        newNodes.push(clonedNode);
      });

      // Create new edges with updated source and target IDs
      copiedData.edges.forEach((edge) => {
        const newEdge: Edge = {
          ...edge,
          id: `edge-${newNodeMap[edge.source]}-${edge.sourceHandle || 'default'}-${newNodeMap[edge.target]}`,
          source: newNodeMap[edge.source],
          target: newNodeMap[edge.target],
        };
        newEdges.push(newEdge);
      });

      this.flow.addNodes(newNodes);
      this.flow.addEdges(newEdges);
      this.nodes.push(...newNodes);
      this.edges.push(...newEdges);
      this.$nextTick(() => this.manageStartNodes());

      const count = newNodes.length;
      notify.success(this.$t('nodes_pasted', { count }), { duration: 1500 });
    },
    addOnboardingNotes() {
