    handleBeforeUnload() {
      if (this.hasUnsavedChanges && this.nodes.length > 0) {
        this.autoSaveToLocalStorage();
        setReloadFlag(this.workFlowId || undefined);
      }
    },
    autoSaveToLocalStorage() {
      const draft = buildAutoSaveDraft(this);
      if (!draft) return;
      // Only update the indicator when the draft content actually changed
      const snapshot = JSON.stringify({ n: draft.nodes, e: draft.edges, m: draft.model, w: draft.workflowName });
      if (snapshot === this.lastAutoSaveSnapshot) return;
      if (saveDraftToStorage(draft, this.workFlowId, this.workflowName)) {
        this.lastAutoSaveSnapshot = snapshot;
        this.lastAutoSave = new Date();
      }
    },
    markUnsavedChanges() {
      if (this.loading || this.isRestoring) return;
      this.hasUnsavedChanges = true;
    },
    onWorkflowNameInput(name: string) {
      this.workflowName = name;
      this.markUnsavedChanges();
    },
    onWorkflowDescriptionInput(description: string | number | null) {
      this.workflowDescription = description == null ? '' : String(description);
      this.markUnsavedChanges();
    },
    restoreFromAutoSave() {
      const result = findAutoSaveDraft(this.workFlowId);
      if (!result) return;

      const { key: storageKey, draft } = result;

      try {
        if (isAutoSaveExpired(draft)) {
          localStorage.removeItem(storageKey);
          return;
        }
        if (isAutoSaveStale(draft, this.lastModifiedOn)) {
          localStorage.removeItem(storageKey);
          return;
        }
        const formattedDate = dateUtils.methods.formatDateTimeZone(draft.timestamp);

        this.autoSaveDialog = this.$q.dialog({
          title: this.$t('restore_autosave_title'),
          message: this.$t('restore_autosave_message', { date: formattedDate }),
          cancel: { label: this.$t('discard'), flat: true },
          ok: { label: this.$t('restore'), color: 'primary' },
          persistent: true,
        }).onOk(async () => {
          this.autoSaveDialog = null;

          const result = await applyAutoSaveDraft(this, draft);
          this.nodeIdCounter = result.nodeIdCounter;
          this.edgeIdCounter = result.edgeIdCounter;

          // Re-initialize card variables after VueFlow syncs
          this.nodes.forEach((node: any) => {
            if (node.data?.card?.variables) {
              initializeCardVariables(node.data.card.variables, this.workflowModel, this.getComponentName, {
                preserveExistingUuids: true,
              });
            }
          });

          // Restored draft content is unsaved: keep leave warning and autosave alive.
          this.hasUnsavedChanges = true;

          notify.success(
            this.$t('autosave_restored'),
          );
        }).onCancel(() => {
          this.autoSaveDialog = null;
          localStorage.removeItem(storageKey);
        });
      } catch (err) {
        console.error('Error restoring auto-save:', err);
        localStorage.removeItem(storageKey);
      }
    },
    async prepareVariableData(variable: any): Promise<string> {
      return await sharedPrepareVariableData(
        this.workflowModel,
        variable,
        this.docOperatorVariables,
        this.docOperatorVariablesSensitive,
        this.docOperatorLockedSensitiveData,
      );
    },
    /**
     * Serializes VueFlow canvas state to AdvancedFlowData format for backend storage.
     *
     * Converts:
     * - VueFlow nodes → AdvancedNode (with card data, position, variables)
     * - VueFlow edges → AdvancedEdge (with handle mapping)
     * - Handles: right/true→success, false→error, left→input
     *
     * @returns {AdvancedFlowData} Serialized workflow data ready for API
     */
    async serializeToAdvancedFlowData(): Promise<AdvancedFlowData> {
      const edgesToSerialize = getLiveEdges(this.flow, this.edges);

      // Process nodes and their variables (exclude note nodes — serialized separately)
      const workflowNodes = this.nodes.filter((n: any) => n.type !== VF_NODE_TYPE.NOTE);
      const advancedNodes: AdvancedNode[] = await Promise.all(
        workflowNodes.map(async (node: any): Promise<AdvancedNode> => {
          const nodeType = resolveNodeType(node);
          const isControl = NodeTypeHelpers.requiresNoCard(nodeType);

          // Build card object for regular nodes (WHEN/AND/THEN)
          let card: Card | null = null;
          if (!isControl && node.data?.card) {
            const processedVariables: Variable[] = await processVariablesForSave(
              node.data.card.variables,
              this.workflowModel,
              this.docOperatorVariables,
              this.docOperatorVariablesSensitive,
              this.docOperatorLockedSensitiveData,
            );

            card = {
              id: node.data.card.id,
              card_version: node.data.card.card_version || 3,
              svg: node.data.card.svg || null,
              card_type: node.data.card.card_type,
              text: node.data.card.text,
              category: node.data.card.category || null,
              variables: processedVariables,
              latest_version: node.data.card.latest_version,
              is_partner_card: node.data.card.is_partner_card || false,
              description: node.data.card.description || null,
              title_formatted: node.data.card.title_formatted || null,
            };
          }

          return buildSerializedNode(node, nodeType, card);
        }),
      );

      const advancedEdges = edgesToSerialize.map(serializeEdgeImpl);
      const serializedNotes = serializeNotesImpl(
        this.nodes,
        DEFAULT_NOTE_COLOR,
        DEFAULT_NOTE_WIDTH,
        DEFAULT_NOTE_HEIGHT,
      );

      return {
        nodes: advancedNodes,
        edges: advancedEdges,
        notes: serializedNotes,
        viewport: {
          x: this.viewport?.x ?? 0,
          y: this.viewport?.y ?? 0,
          zoom: this.viewport?.zoom ?? 1,
        },
        // Variables are now org-scoped in DB, not embedded in flow data
      };
    },
    /**
     * Deserializes AdvancedFlowData from backend into VueFlow canvas state.
     *
     * Converts:
     * - AdvancedNode → VueFlow nodes (with regenerated UUIDs)
     * - AdvancedEdge → VueFlow edges
     * - Handles: success→right, error→false, input→left
     *
     * Also:
     * - Detects deleted/missing cards and creates placeholders
     * - Restores notes
     * - Updates nodeIdCounter
     * - Re-initializes card variables
     *
     * @param {any} response - API response containing workflow data
     */
    async deserializeFromAdvancedFlowData(response: any) {
      const data = response.data || {};
      const backendNodes = data.nodes || [];
      const backendEdges = data.edges || [];

      const missingCards: string[] = [];

      // Control nodes that don't have cards (START is special - rendered differently)
      const controlTypes = CONTROL_NODE_TYPES;
      const controlLabels = NODE_TYPE_TRANSLATION_KEYS;

      this.nodes = backendNodes.map((node: any, index: number) => {
        if (node.node_type === NodeType.START) {
          return deserializeStartNode(node, index, this.$t);
        }

        if (isNonStartControlNode(node.node_type)) {
          return deserializeControlNode(node, index, this.$t);
        }

        // Regular nodes (WHEN/AND/THEN) have a card object from backend
        const card = node.card || null;

        // Check if card exists in catalog and get category color + all_versions
        if (card && card.id) {
          const cardExists = this.checkCardExists(card.id);
          if (!cardExists) {
            missingCards.push(node.node_id);
            card.isMissingCard = true;
            card.originalCardId = card.id;
            card.missingCardTooltip = this.$t('partner_card_not_available');
            card.svg_background_color = NODE_STATUS_HEX_COLORS.failed_condition;
          } else {
            const fullCard = this.getCardFromStore(card.id, card.category, node.node_type);
            if (fullCard) {
              card.all_versions = fullCard.all_versions;
              card.latest_version = fullCard.latest_version;
              card.svg_background_color = fullCard.svg_background_color;
              if (!card.svg || card.svg === 'dummy') {
                card.svg = fullCard.svg;
              }
              if (card.variables && fullCard.variables) {
                mergeTemplateVariableMetadata(card.variables, fullCard.variables);
              }
            } else {
              const categoryColor = this.getCategoryColor(card.category);
              if (categoryColor) {
                card.svg_background_color = categoryColor;
              }
            }
          }
        }

        // Process card variables (shared logic with v2 workflow)
        if (card && card.variables) {
          processCardVariablesForLoad(
            card,
            this.docOperatorVariables,
            this.docOperatorLockedSensitiveData,
            this.setDocOperatorVariables,
            this.doc_operator_prompts,
            this.getComponentName,
            this.workflowModel,
            this.docOperatorVariablesSensitive,
          );
        }

        return deserializeLogicNode(node, index, card);
      });

      const mappedEdges = backendEdges.map((edge: any) => {
        const sourceHandle = edge.source_handle;
        const targetHandle = edge.target_handle;

        const color = getEdgeStrokeColor(sourceHandle);
        const edgeLabel =
          sourceHandle === HandleType.SUCCESS
            ? '✓'
            : sourceHandle === HandleType.FAILED_CONDITION
              ? '✗'
              : sourceHandle === HandleType.ERROR
                ? '⚠'
                : '';

        return {
          id: edge.edge_id,
          type: 'removableEdge',
          source: edge.source_node_id,
          sourceHandle,
          target: edge.target_node_id,
          targetHandle,
          style: markRaw({ stroke: color }),
          label: edgeLabel,
          labelStyle: { fill: color, ...EDGE_LABEL_STYLE },
          data: {
            color: color,
            remove: (id: string, pos: any) => {
              const edgeToRemove = this.edges.find((e) => e.id === id);
              if (edgeToRemove) {
                this.saveHistory(true);
                this.flow.removeEdges([edgeToRemove]);
              }
            },
          },
        };
      });

      // Set nodes first, wait for them to be ready, then add edges
      this.flow.setNodes(this.nodes);
      await nextTick();
      await nextTick();
      await new Promise((resolve) => setTimeout(resolve, 1000)); // Wait for nodes and handles to render

      // Clear ALL existing edges first (removes old colors/styling)
      this.flow.setEdges([]);
      await nextTick();

      // Add new edges with correct colors - v-model will update this.edges automatically
      if (mappedEdges.length > 0) {
        this.flow.addEdges(mappedEdges);
      }

      // Update ID counters
      this.nodeIdCounter = extractMaxNodeId(this.nodes) + 1;
      this.edgeIdCounter = extractMaxEdgeId(mappedEdges) + 1;

      // Load notes as VueFlow nodes
      if (data.notes?.length) {
        const noteNodes = deserializeNotesImpl(
          data.notes,
          DEFAULT_NOTE_COLOR,
          DEFAULT_NOTE_WIDTH,
          DEFAULT_NOTE_HEIGHT,
          () => 'note-' + uid(),
        );
        noteNodes.forEach((n: any) => this.nodes.push(n));
        this.flow.setNodes(this.nodes);
      }

      // Restore viewport (zoom/pan) if saved, otherwise fit all nodes
      const viewportData = data.viewport;
      if (viewportData?.x != null || viewportData?.y != null || viewportData?.zoom != null) {
        await nextTick();
        this.flow.setViewport({
          x: viewportData.x ?? 0,
          y: viewportData.y ?? 0,
          zoom: viewportData.zoom ?? 1,
        });
      } else {
        await nextTick();
        this.flow.fitView({ duration: VIEWPORT_ANIMATE_DURATION });
      }

      // Warn about missing cards
      if (missingCards.length > 0) {
        notify.warning(
          this.$t('workflow_has_missing_cards', {
            count: missingCards.length,
          }),
        );
      }

      // Clear history and capture the loaded state as the undo baseline.
      // Double nextTick ensures VueFlow's v-model sync has fully settled
      // (nodes including notes AND edges) before we snapshot.
      this.history = [];
      this.redoHistory = [];
      this.hasUnsavedChanges = false;
      await nextTick();
      await nextTick();
      this.saveHistory(true);
      this.hasUnsavedChanges = false;
    },
    /**
     * Checks if a card ID exists in the current card catalog.
     *
     * Used during workflow load to detect deleted/deprecated cards.
     * If card doesn't exist, a placeholder is created with warning icon.
     *
     * @param {string} cardId - The card ID to check
     * @returns {boolean} True if card exists, false if deleted/missing
     */
    checkCardExists(cardId: string): boolean {
      const allCards = [
        ...(this.workflowWhenCards || []),
        ...(this.workflowAndCards || []),
        ...(this.workflowThenCards || []),
      ];
      return checkCardExistsImpl(cardId, allCards);
    },
    /**
     * Gets a card from the catalog by ID.
     *
     * @param {string} cardId - The card ID to find
     * @returns {any | null} The card object if found, null if not found
     */
    getCardById(cardId: string): any | null {
      const allCards = [
        ...(this.workflowWhenCards || []),
        ...(this.workflowAndCards || []),
        ...(this.workflowThenCards || []),
      ];
      return getCardByIdImpl(cardId, allCards);
    },
    /**
     * Gets the category color (svg_background_color) by category name.
     *
     * @param {string | null | undefined} categoryName - The category name (e.g., "wf_cat_document")
     * @returns {string | null} The category color hex code, or null if not found
     */
    getCategoryColor(categoryName: string | null | undefined): string | null {
      const allCards = [
        ...(this.workflowWhenCards || []),
        ...(this.workflowAndCards || []),
        ...(this.workflowThenCards || []),
      ];
      return getCategoryColorImpl(categoryName, allCards);
    },
    getCardFromStore(cardId: string, categoryName: string, nodeType: string): any | null {
      const cardStoreMap: Record<string, any> = {
        when: this.workflowWhenCards,
        and: this.workflowAndCards,
        then: this.workflowThenCards,
      };
      return getCardFromStoreImpl(cardId, categoryName, nodeType, cardStoreMap);
    },
    async saveWorkflow() {
      if (!this.workflowName || this.workflowName.trim().length < 3) {
        notify.error(
          this.$t('workflow_name_required') ||
            'Please enter a workflow name (at least 3 characters)',
        );
        return;
      }

      this.manageStartNodes();

      const structureResult = validateWorkflowStructure(this.nodes, this.edges);
      if (!structureResult.valid) {
        this.validationIsWarning = false;
        this.validationErrors = structureResult.errors;
        this.highlightErrorNodes(structureResult.errors);
        // Don't return — save anyway, show warnings after
      }

      this.saving = true;
      try {
        const flowData = await this.serializeToAdvancedFlowData();
        const payload: any = {
          data: flowData,
          name: this.workflowName,
          description: this.workflowDescription || '',
          version: 3,
        };

        if (this.workFlowId) {
          payload.workflow_id = this.workFlowId;
        }

        const response =
          await this.workflowApiService.saveAdvancedWorkflow(payload);

        if (response?.success) {
          if (response.warnings?.length) {
            // Show persistent warning banner instead of transient toast
            this.validationIsWarning = true;
            this.validationErrors = response.warnings.map((w: any) =>
              typeof w === 'string'
                ? { message: w, node_id: null }
                : { message: w.message, translation_key: w.translation_key, node_id: w.node_id || null },
            );
            notify.warning(
              this.$t('workflow_saved_with_warnings'),
            );
          } else {
            this.validationErrors = [];
            this.validationWarnings = [];
            this.clearNodeHighlights();
            notify.success(
              this.$t('workflow_saved'),
            );
          }
          this.hasUnsavedChanges = false;

          // Update loaded version for next save
          this.loadedVersion = response.wf_version || 3;
          this.lastModifiedOn = response.last_modified_on || this.lastModifiedOn;

          // Clear auto-save after successful save
          clearAutoSaveAfterSave(this.workFlowId, this.workflowName);
          this.lastAutoSave = null;
          this.lastAutoSaveSnapshot = '';

          if (response.workflow_id && !this.workFlowId) {
            this.workFlowId = response.workflow_id;
            this.$router.replace({
              params: { id: response.workflow_id },
            });
          }
        } else if (response?.conflict) {
          // Version conflict - another user modified the workflow
          this.$q
            .dialog({
              title:
                this.$t('workflow_conflict_title'),
              message: this.$t('workflow_conflict_reload'),
              cancel: {
                label: this.$t('cancel'),
                flat: true,
              },
              ok: {
                label: this.$t('reload'),
                color: 'primary',
              },
              persistent: true,
            })
            .onOk(async () => {
              await this.loadWorkflow();
            });
        } else {
          notify.error(
            response?.message || 'Failed to save workflow',
          );
        }
      } catch (err: any) {
        // Extract Pydantic validation error details from 422 responses
        const details = err?.detail;
        if (Array.isArray(details)) {
          const messages = details.map((d: any) => d.msg || JSON.stringify(d));
          this.validationIsWarning = false;
          this.validationErrors = messages.map((msg: string) => ({
            message: msg,
            node_id: null,
          }));
        } else {
          notify.error(err?.message || 'Error saving workflow');
        }
      } finally {
        this.saving = false;
      }
    },
