    async toggleWorkflowEnabled() {
      if (!this.workFlowId) return;

      if (this.hasUnsavedChanges) {
        this.$q.dialog({
          title: this.$t('unsaved_changes'),
          message: this.$t('save_before_toggle_enabled'),
          cancel: { label: this.$t('cancel'), flat: true },
          ok: { label: this.$t('save_and_continue'), color: 'primary' },
          persistent: true,
        }).onOk(async () => {
          await this.saveWorkflow();
          if (!this.hasUnsavedChanges) {
            await this.performToggleEnabled();
          }
        });
        return;
      }

      await this.performToggleEnabled();
    },
    async performToggleEnabled() {
      const newEnabled = !this.workflowEnabled;
      try {
        const response = await this.workflowApiService.updateWorkflow({
          id: this.workFlowId,
          enabled: newEnabled,
        });
        if (response) {
          this.workflowEnabled = newEnabled;
          notify.success(
            newEnabled ? this.$t('workflow_activated') : this.$t('workflow_deactivated'),
          );
          document.dispatchEvent(new CustomEvent('workflow_status_changed', {
            detail: { workflowId: this.workFlowId, enabled: newEnabled },
          }));
        }
      } catch (err: any) {
        notify.error(err?.message || 'Error toggling workflow status');
      }
    },
    /**
     * Loads workflow from backend database by ID.
     *
     * Called automatically on mount if route contains :id parameter.
     *
     * Flow:
     * 1. Fetches workflow data from API
     * 2. Extracts name, description, version
     * 3. Deserializes data to VueFlow nodes/edges
     * 4. Shows loading indicator for large workflows (>50 nodes)
     * 5. Tracks loaded version for optimistic locking
     *
     * @throws Shows error notification if load fails
     */
    async fetchWorkflow() {
      try {
        return await this.workflowApiService.loadAdvancedWorkflow(
          this.workFlowId,
        );
      } catch (err: any) {
        notify.error(err?.message || 'Error loading workflow');
        return null;
      }
    },
    async applyWorkflow(response: any) {
      try {
        if (response?.success) {
          this.workflowName = response.name || '';
          this.workflowDescription = response.description || '';
          this.loadedVersion = response.wf_version || 3;
          this.lastModifiedOn = response.last_modified_on || '';
          this.workflowEnabled = response.enabled ?? false;

          // Show loading message for large workflows
          const nodeCount = response.data?.nodes?.length || 0;
          if (nodeCount > 50) {
            notify.info(
              this.$t('loading_large_workflow', { count: nodeCount }) ||
                `Loading large workflow (${nodeCount} nodes)...`,
            );
          }

          await this.deserializeFromAdvancedFlowData(response);
          // History is initialized at the end of deserializeFromAdvancedFlowData
          // after edges are fully synced via v-model.
        } else {
          notify.error(
            response?.message || 'Failed to load workflow',
          );
        }
      } catch (err: any) {
        notify.error(err?.message || 'Error loading workflow');
      } finally {
        this.syncSelectedThenCards();
      }
    },
    async loadWorkflow() {
      this.loading = true;
      try {
        const response = await this.fetchWorkflow();
        if (response) {
          await this.applyWorkflow(response);
        }
      } finally {
        this.loading = false;
      }
    },
    async validateWorkflow() {
      this.validating = true;
      this.validationErrors = [];
      this.validationWarnings = [];
      this.validationIsWarning = false;
      try {
        // Frontend structural validation
        const structureResult = validateWorkflowStructure(
          this.nodes,
          this.edges,
        );
        const frontendErrors = structureResult.valid ? [] : [...structureResult.errors];
        const frontendWarnings = [...structureResult.warnings];

        // Always run backend validation too
        const flowData = await this.serializeToAdvancedFlowData();
        const response =
          await this.workflowApiService.validateAdvancedWorkflow(flowData);

        const backendErrors = extractBackendErrors(response);
        const backendWarnings = extractBackendWarnings(response);

        // Merge and deduplicate
        const allErrors = deduplicateValidationItems([...frontendErrors, ...backendErrors]);
        const allWarnings = deduplicateValidationItems([...frontendWarnings, ...backendWarnings]);

        if (allErrors.length > 0) {
          this.validationErrors = allErrors;
          this.highlightErrorNodes(allErrors);
        }

        if (allWarnings.length > 0) {
          this.validationWarnings = allWarnings;
        }

        if (allErrors.length === 0 && allWarnings.length === 0) {
          notify.success(
            this.$t('workflow_valid'),
          );
          this.clearNodeHighlights();
        }
      } catch (err: any) {
        notify.error(err?.message || 'Error validating workflow');
      } finally {
        this.validating = false;
      }
    },
    async testWorkflowDirect() {
      // Start-node play button: run test immediately without document picker
      this.clearTestResults();
      this.startingNodeIds = null;
      await this.onTestDocumentSelected(null);
    },
    async testWorkflow() {
      // Toolbar test button: open document picker first
      this.clearTestResults();

      // Clear starting node IDs when running full test from toolbar
      // (testFromNode sets this before calling testWorkflow)
      if (!this.startingNodeIds) {
        this.startingNodeIds = null;
      }

      // Open document picker dialog
      this.showTestDocPicker = true;
    },
    async onTestDocumentSelected(testPayload: { doc_id?: string; doc_data?: Record<string, any> } | null) {
      this.showTestDocPicker = false;
      this.testing = true;
      this.testResults = null;
      this.testResultsSummary = null;
      this.validationErrors = [];
      this.validationWarnings = [];

      try {
        // Serialize current canvas state so unsaved changes are tested
        const flowData = await this.serializeToAdvancedFlowData();

        const payload: any = {
          data: flowData,
        };
        // doc_id and doc_data are mutually exclusive
        if (testPayload?.doc_id) {
          payload.doc_id = testPayload.doc_id;
        } else if (testPayload?.doc_data) {
          payload.doc_data = testPayload.doc_data;
        }
        if (this.startingNodeIds?.length) {
          payload.starting_node_ids = this.startingNodeIds;
        }
        this.startingNodeIds = null;

        const response = await this.workflowApiService.testAdvancedWorkflow(payload);

        this.testResults = response;

        if (!response.success && response.message) {
          notify.error(response.message);
          return;
        }

        // Apply persistent node result indicators on canvas
        this.applyTestResultsToNodes(response.node_results || {}, response.validation_warnings || [], response.logs || []);

        // Animate execution path
        if (response.logs && response.logs.length > 0) {
          await this.animateTestExecution(response.logs);
        }

        // Build summary banner
        const resultStatus = response.workflow_result === NodeExecutionStatus.SUCCESS ? 'success'
          : response.workflow_result === NodeExecutionStatus.ERROR ? 'error' : 'warning';
        this.testResultsSummary = {
          status: resultStatus,
          label: response.workflow_result === NodeExecutionStatus.SUCCESS
            ? this.$t('test_passed')
            : response.workflow_result === NodeExecutionStatus.ERROR
              ? this.$t('test_failed')
              : response.workflow_result || this.$t('test_completed'),
          executionTime: response.execution_time,
          warnings: response.validation_warnings,
        };

        if (this.isRetest) {
          this.showTestResults = true;
          this.isRetest = false;
        }

        if (response.workflow_result === NodeExecutionStatus.SUCCESS) {
          notify.success(this.$t('workflow_test_success'));
        } else {
          notify.warning(this.$t('workflow_test_with_errors'));
        }
      } catch (error: any) {
        console.error('Test workflow error:', error);
        const responseData = error?.response?.data;

        if (error?.response?.status === 422) {
          notify.error(responseData?.message || this.$t('workflow_test_validation_error'));
        } else if (responseData?.structured_errors?.length) {
          this.validationErrors = responseData.structured_errors;
          this.highlightErrorNodes(responseData.structured_errors);
          notify.warning(this.$t('wf_validation_errors_found'));
        } else if (error?.response?.status === 0 || error?.code === 'ERR_NETWORK') {
          notify.error(this.$t('workflow_test_error'));
        } else if (responseData?.message) {
          notify.error(responseData.message);
        } else {
          notify.error(this.$t('workflow_test_failed'));
        }
      } finally {
        this.testing = false;
      }
    },
    /**
     * Apply test result indicators (success/fail/skipped) to canvas nodes
     * using node_results keyed by node_id.
     */
    applyTestResultsToNodes(nodeResults: Record<string, NodeExecutionResultData>, warnings: any[] = [], logs: any[] = []) {
      this.nodes = applyTestResultsToNodesArray(this.nodes, nodeResults, warnings, logs);

      this.$nextTick(() => {
        this.flow?.setNodes([...this.nodes]);
        const flowEdges = getFlowEdges(this.flow, this.edges);
        for (const edge of flowEdges) {
          if (!edge.data?.testExecuting && !edge.data?.testResult) {
            this.flow?.updateEdgeData(edge.id, { hasTestResults: true });
          }
        }
      });
    },
    /**
     * Clear all test result indicators from canvas nodes.
     */
    clearTestResults() {
      this.testResultsSummary = null;
      this.testResults = null;
      this.nodes = clearTestResultsFromNodes(this.nodes);
      this.flow?.setNodes([...this.nodes]);

      // Clear edge test indicators
      const flowEdges = getFlowEdges(this.flow, this.edges);
      for (const edge of flowEdges) {
        if (edge.data?.testExecuting || edge.data?.testResult || edge.data?.hasTestResults) {
          this.flow?.updateEdgeData(edge.id, { testExecuting: false, testResult: null, testStatus: null, hasTestResults: false });
        }
      }
    },
    async animateTestExecution(logs: any[]) {
      const STEP_DELAY = TEST_STEP_DELAY_MS;
      const animatedEdgeIds: string[] = [];

      for (const log of logs) {
        const nodeId = log.node_id;
        if (!nodeId) continue;

        const status = log.status === NodeExecutionStatus.ERROR
          ? 'error'
          : log.status === NodeExecutionStatus.FAILED_CONDITION
            ? 'failed_condition'
            : 'success';

        // Animate incoming edges — only those whose source was executed and handle matches path_taken
        const flowEdges = getFlowEdges(this.flow, this.edges);
        const incomingEdges = flowEdges.filter((e: any) => {
          if (e.target !== nodeId) return false;
          const sourceResult = this.testResults?.node_results?.[e.source];
          // Skip edges from nodes that were not executed
          if (!sourceResult || !sourceResult.executed) return false;
          // Check if the source node's path_taken matches this edge's sourceHandle
          if (e.sourceHandle) {
            return e.sourceHandle === (sourceResult.path_taken || 'success');
          }
          return true;
        });
        for (const edge of incomingEdges) {
          // Color the edge based on the source node's path_taken (the handle that was used)
          const sourcePathTaken = this.testResults?.node_results?.[edge.source]?.path_taken || PathResult.SUCCESS;
          this.flow.updateEdgeData(edge.id, { testExecuting: true, testStatus: sourcePathTaken });
          if (!animatedEdgeIds.includes(edge.id)) animatedEdgeIds.push(edge.id);
        }

        // Animate only the outgoing edges matching the path_taken from node_results
        const nodeResult = this.testResults?.node_results?.[nodeId];
        const pathTaken = nodeResult?.path_taken || status; // e.g. "success", "failed_condition", "error"
        const takenTargetIds = (log.targets || {})[pathTaken] || [];
        if (takenTargetIds.length > 0) {
          const outEdges = flowEdges.filter(
            (e: any) => e.source === nodeId && e.sourceHandle === pathTaken && takenTargetIds.includes(e.target),
          );
          for (const edge of outEdges) {
            // Color the edge based on the path handle (failed_condition, error, success)
            this.flow.updateEdgeData(edge.id, { testExecuting: true, testStatus: pathTaken });
            if (!animatedEdgeIds.includes(edge.id)) animatedEdgeIds.push(edge.id);
          }
        }

        // Add highlight class to the node
        this.nodes = this.nodes.map((node: any) =>
          node.id === nodeId
            ? { ...node, class: ((node.class || '') + ` test-executing-node ${status}`).trim() }
            : node,
        );

        await this.$nextTick();
        this.flow.setNodes([...this.nodes]);

        // Wait for visual feedback
        await new Promise((resolve) => setTimeout(resolve, STEP_DELAY));

        // Replace pulse with flash animation on result arrival
        const flashClass = status === 'success'
          ? 'test-result-flash-success'
          : status === 'failed_condition'
            ? 'test-result-flash-failed-condition'
            : 'test-result-flash-error';

        this.nodes = this.nodes.map((node: any) =>
          node.id === nodeId
            ? { ...node, class: ((node.class || '').replace(/test-executing-node\s*\S*/g, '') + ` ${flashClass}`).trim() }
            : node,
        );

        await this.$nextTick();
        this.flow.setNodes([...this.nodes]);

        // Let flash animation play (600ms), then clear it
        await new Promise((resolve) => setTimeout(resolve, 600));

        this.nodes = this.nodes.map((node: any) =>
          node.id === nodeId
            ? { ...node, class: (node.class || '').replace(/test-result-flash-\S*/g, '').trim() }
            : node,
        );

        await this.$nextTick();
        this.flow.setNodes([...this.nodes]);
      }
      // Edges remain animated (testExecuting: true) — cleared by clearTestResults
    },
    /**
     * Build a map of node_id → messages from an array of error/log entries.
     */
    applyNodeHighlights(errorMap: Map<string, string[]>) {
      this.nodes = applyNodeHighlightsImpl(this.nodes, errorMap);
      this.flow.setNodes(this.nodes);
    },
    highlightErrorNodes(errors: any[]) {
      this.clearNodeHighlights();
      const errorMap = buildNodeMessageMap(errors);
      this.applyNodeHighlights(errorMap);
    },
    clearNodeHighlights() {
      clearTreeHighlight(this);
      this.nodes = clearNodeHighlightsFromNodes(this.nodes);
      this.flow.setNodes(this.nodes);
    },
    isTreeDimmed(nodeId: string): boolean {
      return isTreeDimmedImpl(this.treeHighlightSet, nodeId);
    },
    focusNode(nodeId: string) {
      if (!nodeId) return;
      const node = this.nodes.find((n: any) => n.id === nodeId);
      if (node) {
        this.flow.setCenter(
          node.position.x + NODE_CENTER_OFFSET_X,
          node.position.y + NODE_CENTER_OFFSET_Y,
          { zoom: 1, duration: VIEWPORT_ANIMATE_DURATION },
        );
      }
    },
    async saveAsTemplate() {
      if (!this.templateName || this.templateName.length < 3) return;
      this.savingTemplate = true;
      try {
        const flowData = await this.serializeToAdvancedFlowData();
        const response = await this.workflowApiService.saveAdvancedAsTemplate({
          name: this.templateName,
          description: this.templateDescription,
          data: flowData,
        });
        if (response?.success) {
          notify.success(
            this.$t('template_saved'),
          );
          this.showSaveTemplateDialog = false;
          this.templateName = '';
          this.templateDescription = '';
        } else {
          notify.error(
            response?.message || this.$t('error_saving_template'),
          );
        }
      } catch (err: any) {
        notify.error(err?.message || this.$t('error_saving_template'));
      } finally {
        this.savingTemplate = false;
      }
    },
    isValidConnection(connection: any) {
      return isValidConnectionImpl(this, connection);
    },
    toggleSnap() {
      this.snapEnabled = !this.snapEnabled;
      localStorage.setItem('advancedWf_snapToGrid', String(this.snapEnabled));
    },
    toggleMiniMap() {
      this.showMiniMap = !this.showMiniMap;
    },
    getMiniMapNodeColor(node: any) {
      if (node.type === VF_NODE_TYPE.START) {
        return getNodeTypeColor(NodeType.START);
      }
      if (node.type === VF_NODE_TYPE.NOTE) {
        return node.data?.color || DEFAULT_NOTE_COLOR;
      }
      return getNodeTypeColor(node.data?.nodeType);
    },
    applyNodeStatesFromTestResult(nodeResults: Record<string, any>) {
      this.nodes = applyNodeStates(this.nodes, nodeResults);
      this.flow.setNodes(this.nodes);
    },
    clearNodeStates() {
      this.nodes = clearNodeStatesImpl(this.nodes);
      this.flow.setNodes(this.nodes);
    },
    openLogsPanel() {
      if (!this.testResults?.logs?.length) {
        notify.info(this.$t('no_execution_logs'));
        return;
      }
      this.executionLogs = this.testResults.logs;
      this.selectedLogDetail = null;
      this.showLogsPanel = true;
    },
    loadExecutionLogs() {
      // Logs come from the last test run response, not a separate endpoint
      this.executionLogs = this.testResults?.logs || [];
    },
    loadLogDetail(logId: string) {
      // Find the log entry from the test results
      const log = this.executionLogs.find((l: any) => l.node_id === logId);
      if (log) {
        this.selectedLogDetail = log;
      }
    },
    formatLogDate(dateStr: string) {
      if (!dateStr) return '';
      const d = new Date(dateStr);
      return d.toLocaleString();
    },
    highlightLogNodes(logs: any[]) {
      this.clearNodeHighlights();
      const errorMap = buildErrorLogMap(logs, this.$t);
      if (errorMap.size > 0) {
        this.applyNodeHighlights(errorMap);
      }
      this.showLogsPanel = false;
    },
    async exportAsImage() {
      try {
        const canvas = this.$refs.vueFlowRef?.$el;
        if (!canvas) {
          notify.error(
            this.$t('canvas_not_found'),
          );
          return;
        }

        this.showLoading();

        // Save current viewport and fit all nodes into view for full export
        const { getViewport, fitView } = this.vueFlow;
        const savedViewport = getViewport();
        await fitView({ padding: 0.1 });
        // Wait for VueFlow to re-render at new viewport
        await new Promise((resolve) => setTimeout(resolve, 200));

        const { toPng } = await import('html-to-image');

        // Build font CSS: local @font-face rules + inlined Material Icons font
        let fontCSS = '';
        for (const sheet of document.styleSheets) {
          try {
            for (const rule of sheet.cssRules) {
              if (rule instanceof CSSFontFaceRule) {
                fontCSS += rule.cssText + '\n';
              }
            }
          } catch {
            // Skip cross-origin stylesheets
          }
        }

        const dataUrl = await toPng(canvas, {
          backgroundColor: document.body.classList.contains('body--dark') ? '#1d1d1d' : '#ffffff',
          quality: 1.0,
          pixelRatio: 2,
          skipFonts: true,
          fontEmbedCSS: fontCSS || undefined,
        });

        // Restore original viewport
        this.vueFlow.setViewport(savedViewport);

        const link = document.createElement('a');
        link.download = `${this.workflowName || 'workflow'}.png`;
        link.href = dataUrl;
        link.click();

        notify.success(
          this.$t('workflow_exported_as_image'),
        );
      } catch (err: any) {
        console.error('Error exporting image:', err);
        notify.error(
          this.$t('error_exporting_image')
        );
      } finally {
        this.hideLoading();
      }
    },
    searchNodes(query: string) {
      searchNodesImpl(this, query);
    },
  },
});
</script>

