<template>
  <div
    ref="menuWrapper"
    class="post-it-note"
    :style="{
      width: noteWidth + 'px',
      height: noteHeight + 'px',
      background: selectedColor,
    }"
  >
    <div v-if="!editing" class="node-tooltip-stack">
      <div class="node-custom-tooltip">{{ $t('double_click_to_edit_note') }}</div>
    </div>

    <div
      class="textarea-wrapper"
      @dblclick.stop="startEditing"
    >
      <textarea
        ref="textareaRef"
        v-model="content"
        :class="['nodrag', 'nowheel', { editing: editing }]"
        :placeholder="$t('write_here')"
        :readonly="!editing"
        :maxlength="NOTE_MAX_LENGTH"
        @blur="stopEditing"
        @keydown.escape="stopEditing"
      />
    </div>

    <!-- Manual resize handle (CSS resize won't work inside VueFlow nodes) -->
    <div
      class="resize-handle nodrag"
      @mousedown.stop.prevent="startResize"
    />
  </div>
</template>

<script>
import { NOTE_MAX_LENGTH } from '../workflow-advanced-models';

export default {
  emits: ['editNote', 'resizeNote'],
  props: {
    noteId: {
      type: String,
      required: true,
    },
    initialContent: {
      type: String,
      default: '',
    },
    color: {
      type: String,
      default: '#fef48a',
    },
    initialWidth: {
      type: Number,
      default: 280,
    },
    initialHeight: {
      type: Number,
      default: 80,
    },
    zoom: {
      type: Number,
      default: 1,
    },
  },
  data() {
    const MIN_W = 160;
    const MIN_H = 60;
    return {
      MIN_W,
      MIN_H,
      NOTE_MAX_LENGTH,
      content: this.initialContent,
      editing: false,
      selectedColor: null,
      noteWidth: Math.max(this.initialWidth, MIN_W),
      noteHeight: Math.max(this.initialHeight, MIN_H),
      resizeStartX: 0,
      resizeStartY: 0,
      resizeStartW: 0,
      resizeStartH: 0,
    };
  },
  mounted() {
    this.selectedColor = this.color;
  },
  unmounted() {
    document.removeEventListener('mousemove', this.onResize);
    document.removeEventListener('mouseup', this.stopResize);
  },
  watch: {
    initialContent(newVal) {
      if (newVal !== this.content) {
        this.content = newVal;
      }
    },
    color(newVal) {
      this.selectedColor = newVal;
    },
  },
  methods: {
    startEditing() {
      this.editing = true;
      this.$nextTick(() => {
        this.$refs.textareaRef?.focus();
      });
    },
    stopEditing() {
      if (!this.editing) return;
      this.editing = false;
      this.$emit('editNote', this.noteId, this.content);
    },
    startResize(e) {
      this.resizeStartX = e.clientX;
      this.resizeStartY = e.clientY;
      this.resizeStartW = this.noteWidth;
      this.resizeStartH = this.noteHeight;
      document.addEventListener('mousemove', this.onResize);
      document.addEventListener('mouseup', this.stopResize);
    },
    onResize(e) {
      const zoom = this.zoom || 1;
      const dx = (e.clientX - this.resizeStartX) / zoom;
      const dy = (e.clientY - this.resizeStartY) / zoom;
      this.noteWidth = Math.max(this.MIN_W, this.resizeStartW + dx);
      this.noteHeight = Math.max(this.MIN_H, this.resizeStartH + dy);
    },
    stopResize() {
      document.removeEventListener('mousemove', this.onResize);
      document.removeEventListener('mouseup', this.stopResize);
      this.$emit('resizeNote', this.noteId, this.noteWidth, this.noteHeight);
    },
  },
};
</script>

