/**
 * Workflow auto-save — localStorage draft persistence and reload detection.
 *
 * Extracted from workflow-designer-advanced.vue so the logic can be
 * unit-tested without mounting the full component.
 *
 * Pure functions operate on localStorage/sessionStorage directly.
 * Orchestration functions accept an AutoSaveContext (satisfied by `this`
 * in the component) to build drafts from live canvas state.
 */

import { getFlowEdges, cleanEdgesForHistory, snapshotWorkflowModel, restoreWorkflowModel } from './workflowHistory';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const AUTOSAVE_INTERVAL_MS = 30_000;
export const AUTOSAVE_EXPIRY_HOURS = 24;
export const AUTOSAVE_KEY_PREFIX = 'advancedWorkflow_autosave_';
export const RELOAD_FLAG_PREFIX = 'advancedWf_reload_';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface AutoSaveDraft {
  nodes: any[];
  edges: any[];
  workflowName: string;
  model: Record<string, any>;
  timestamp: string;
  lastModifiedOn?: string;
  /** Full undo stack so the user keeps their history across reloads. */
  history?: any[];
  redoHistory?: any[];
}

/**
 * Minimal interface that the component satisfies via `this`.
 * Orchestration functions accept this instead of the full component instance.
 */
export interface AutoSaveContext {
  nodes: any[];
  edges: any[];
  workflowModel: Record<string, any>;
  workflowName: string;
  workFlowId: string;
  hasUnsavedChanges: boolean;
  lastModifiedOn: string;
  history: any[];
  redoHistory: any[];
  flow: {
    getEdges?: { value: any[] };
  };
}

// ---------------------------------------------------------------------------
// Pure functions — storage key helpers
// ---------------------------------------------------------------------------

/** Build the localStorage key for a workflow's auto-save draft. */
export function getAutoSaveStorageKey(workflowId?: string, workflowName?: string): string {
  if (workflowId) {
    return `${AUTOSAVE_KEY_PREFIX}id_${workflowId}`;
  }
  return workflowName
    ? `${AUTOSAVE_KEY_PREFIX}${workflowName.replace(/[^a-zA-Z0-9]/g, '_')}`
    : `${AUTOSAVE_KEY_PREFIX}unnamed`;
}

/**
 * Search localStorage for an auto-save draft.
 *
 * - With a `workflowId`: looks up the specific ID-based key only.
 * - Without: scans all prefix-matching keys excluding ID-based ones
 *   (for new/unnamed workflows).
 */
export function findAutoSaveDraft(workflowId?: string): { key: string; draft: AutoSaveDraft } | null {
  if (workflowId) {
    const idKey = getAutoSaveStorageKey(workflowId);
    try {
      const raw = localStorage.getItem(idKey);
      if (raw) return { key: idKey, draft: JSON.parse(raw) };
    } catch {
      localStorage.removeItem(idKey);
    }
    return null;
  }
  // For new workflows, scan all prefix-matching keys (excluding id-based ones)
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith(AUTOSAVE_KEY_PREFIX) && !key.startsWith(`${AUTOSAVE_KEY_PREFIX}id_`)) {
      try {
        const draft = JSON.parse(localStorage.getItem(key) || '');
        return { key, draft };
      } catch {
        localStorage.removeItem(key);
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Pure functions — expiry & reload detection
// ---------------------------------------------------------------------------

/**
 * Check whether the workflow was modified on the server after the draft was saved.
 * Returns true if the draft is stale (someone else saved in the meantime).
 */
export function isAutoSaveStale(draft: AutoSaveDraft, serverLastModifiedOn?: string): boolean {
  if (!draft.lastModifiedOn || !serverLastModifiedOn) return false;
  return new Date(serverLastModifiedOn).getTime() > new Date(draft.lastModifiedOn).getTime();
}

/** Check whether a draft has exceeded the expiry window. */
export function isAutoSaveExpired(draft: AutoSaveDraft): boolean {
  const savedDate = new Date(draft.timestamp);
  const hoursSinceLastSave = (Date.now() - savedDate.getTime()) / (1000 * 60 * 60);
  return hoursSinceLastSave > AUTOSAVE_EXPIRY_HOURS;
}

/** Set a sessionStorage flag indicating the page is being reloaded. */
export function setReloadFlag(workflowId?: string): void {
  const flagKey = RELOAD_FLAG_PREFIX + (workflowId || 'new');
  sessionStorage.setItem(flagKey, '1');
}

/** Check and consume a reload flag. Returns true if the flag was present. */
export function checkReloadFlag(workflowId?: string): boolean {
  const flagKey = RELOAD_FLAG_PREFIX + (workflowId || 'new');
  if (sessionStorage.getItem(flagKey)) {
    sessionStorage.removeItem(flagKey);
    return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Orchestration — draft building (context-dependent)
// ---------------------------------------------------------------------------

/**
 * Build a serializable auto-save draft from live canvas state.
 *
 * Returns `null` if there's nothing to save (no nodes, no unsaved changes).
 */
export function buildAutoSaveDraft(ctx: AutoSaveContext): AutoSaveDraft | null {
  if (ctx.nodes.length === 0) return null;
  if (!ctx.hasUnsavedChanges) return null;

  return {
    nodes: JSON.parse(JSON.stringify(ctx.nodes)),
    edges: cleanEdgesForHistory(getFlowEdges(ctx.flow as any, ctx.edges)),
    workflowName: ctx.workflowName,
    model: snapshotWorkflowModel(ctx.workflowModel),
    timestamp: new Date().toISOString(),
    lastModifiedOn: ctx.lastModifiedOn || '',
    history: JSON.parse(JSON.stringify(ctx.history)),
    redoHistory: JSON.parse(JSON.stringify(ctx.redoHistory)),
  };
}

/**
 * Save a draft to localStorage. Returns true on success, false on quota error.
 */
export function saveDraftToStorage(draft: AutoSaveDraft, workflowId?: string, workflowName?: string): boolean {
  try {
    const storageKey = getAutoSaveStorageKey(workflowId, workflowName);
    localStorage.setItem(storageKey, JSON.stringify(draft));
    return true;
  } catch {
    return false;
  }
}

/**
 * Clear all auto-save keys for a workflow after a successful manual save.
 * Removes the ID-based key, the name-based key, and the unnamed key.
 */
export function clearAutoSaveAfterSave(workflowId?: string, workflowName?: string): void {
  const savedKey = getAutoSaveStorageKey(workflowId, workflowName);
  localStorage.removeItem(savedKey);
  const unnamedKey = getAutoSaveStorageKey(undefined, undefined);
  const namedKey = getAutoSaveStorageKey(undefined, workflowName);
  if (unnamedKey !== savedKey) localStorage.removeItem(unnamedKey);
  if (namedKey !== savedKey) localStorage.removeItem(namedKey);
}

/**
 * Clear a stale auto-save draft (used on fresh navigation when no reload flag is set).
 */
export function clearStaleAutoSave(workflowId?: string): void {
  if (workflowId) {
    const staleKey = getAutoSaveStorageKey(workflowId);
    localStorage.removeItem(staleKey);
  } else {
    const result = findAutoSaveDraft();
    if (result) localStorage.removeItem(result.key);
  }
}

// ---------------------------------------------------------------------------
// Orchestration — draft restore (context-dependent)
// ---------------------------------------------------------------------------

/**
 * Minimal interface for the restore target.
 * The component satisfies this via `this`.
 */
export interface RestoreContext {
  workFlowId: string;
  workflowName: string;
  workflowModel: Record<string, any>;
  nodes: any[];
  edges: any[];
  isRestoring: boolean;
  nodeIdCounter: number;
  edgeIdCounter: number;
  history: any[];
  redoHistory: any[];
  flow: {
    setNodes: (nodes: any[]) => void;
    setEdges: (edges: any[]) => void;
  };
  recreateEdgeData: (edge: any) => any;
  $nextTick: () => Promise<void>;
}

export interface ApplyDraftResult {
  nodeIdCounter: number;
  edgeIdCounter: number;
}

/**
 * Apply an auto-save draft onto the canvas.
 *
 * Sets `isRestoring` to bypass `isValidConnection` duplicate-edge checks
 * and the nodes watcher, calls `flow.setNodes`/`flow.setEdges`, restores
 * the workflowModel, counters, and undo history.
 *
 * Does NOT handle the dialog or variable re-initialization (those stay
 * in the component because they depend on Quasar and card helpers).
 */
export async function applyAutoSaveDraft(
  ctx: RestoreContext,
  draft: AutoSaveDraft,
): Promise<ApplyDraftResult> {
  // Restore workflow name for new (unsaved) workflows only
  if (!ctx.workFlowId) {
    ctx.workflowName = draft.workflowName || '';
  }

  // Restore workflowModel (selected variable values)
  if (draft.model) {
    restoreWorkflowModel(ctx.workflowModel, draft.model);
  }

  // Rebuild edges with visual properties (style, label, remove callback)
  const restoredNodes = JSON.parse(JSON.stringify(draft.nodes || []));
  const restoredEdges = JSON.parse(JSON.stringify(draft.edges || [])).map(
    (edge: any) => ctx.recreateEdgeData(edge),
  );

  // Guard: isRestoring bypasses isValidConnection's duplicate-edge check
  // and suppresses the nodes watcher.
  ctx.isRestoring = true;
  try {
    ctx.flow.setNodes(restoredNodes);
    ctx.flow.setEdges(restoredEdges);
    await ctx.$nextTick();
  } finally {
    ctx.isRestoring = false;
  }

  // Recalculate ID counters from restored data
  const nodeIdCounter = restoredNodes.reduce((max: number, node: any) => {
    const match = node.id.match(/\d+/);
    return match ? Math.max(max, parseInt(match[0])) : max;
  }, 0) + 1;

  const edgeIdCounter = restoredEdges.reduce((max: number, edge: any) => {
    const match = edge.id.match(/edge-(\d+)/);
    return match ? Math.max(max, parseInt(match[1])) : max;
  }, 0) + 1;

  // Restore full undo/redo history from before the reload
  if (draft.history?.length) {
    ctx.history = draft.history;
    ctx.redoHistory = draft.redoHistory || [];
  }

  return { nodeIdCounter, edgeIdCounter };
}
