/**
 * Functions for applying test result indicators, state classes,
 * and validation highlights to workflow nodes.
 *
 * Pure functions take node arrays and return transformed arrays.
 * Context functions operate on component state via minimal interfaces.
 */

import { PathResult, NodeExecutionStatus, type NodeExecutionResultData } from '../workflow-advanced-models';
import { getFlowEdges } from './workflowHistory';
import { buildNodeMessageMap } from './workflowCanvasHelpers';

// ── Pure functions ──────────────────────────────────────────────────

/**
 * Computes the CSS result class for a test result.
 */
export function getResultClass(result: NodeExecutionResultData | undefined): string {
  if (!result) return '';
  if (!result.executed) return 'test-result-skipped';
  if (result.path_taken === PathResult.FAILED_CONDITION) return 'test-result-failed-condition';
  if (result.path_taken === PathResult.ERROR || !result.success) return 'test-result-error';
  return 'test-result-success';
}

/**
 * Groups warnings by node_id.
 */
export function groupWarningsByNode(warnings: any[]): Record<string, any[]> {
  const result: Record<string, any[]> = {};
  for (const w of warnings) {
    if (w.node_id) {
      if (!result[w.node_id]) result[w.node_id] = [];
      result[w.node_id].push(w);
    }
  }
  return result;
}

/**
 * Builds execution order map (1-based) and per-node logs from execution logs.
 */
export function buildExecutionMaps(logs: any[]): {
  executionOrder: Record<string, number>;
  logsByNode: Record<string, any[]>;
} {
  const executionOrder: Record<string, number> = {};
  const logsByNode: Record<string, any[]> = {};
  logs.forEach((log: any, idx: number) => {
    if (log.node_id) {
      executionOrder[log.node_id] = idx + 1;
      logsByNode[log.node_id] = log.logs || [];
    }
  });
  return { executionOrder, logsByNode };
}

/**
 * Applies test result data to a nodes array (pure transformation).
 * Returns the new nodes array.
 */
export function applyTestResultsToNodesArray(
  nodes: any[],
  nodeResults: Record<string, NodeExecutionResultData>,
  warnings: any[],
  logs: any[],
): any[] {
  const warningsByNode = groupWarningsByNode(warnings);
  const { executionOrder, logsByNode } = buildExecutionMaps(logs);

  return nodes.map((node: any) => {
    const nodeId = node.data?.nodeId || node.id;
    const result = nodeResults[nodeId];
    const nodeWarnings = warningsByNode[nodeId];
    const order = executionOrder[nodeId];

    if (!result && !nodeWarnings && !order) return node;

    const newData = {
      ...node.data,
      testResult: result || node.data?.testResult,
      testWarnings: nodeWarnings || null,
      testLogs: logsByNode[nodeId] || null,
      executionOrder: order || null,
    };

    return { ...node, data: newData };
  });
}

/**
 * Clears test result data from a nodes array (pure transformation).
 * Returns the new nodes array.
 */
export function clearTestResultsFromNodes(nodes: any[]): any[] {
  return nodes.map((node: any) => {
    const newData = { ...node.data };
    delete newData.testResult;
    delete newData.testWarnings;
    delete newData.testLogs;
    delete newData.executionOrder;
    return { ...node, data: newData };
  });
}

/**
 * Applies success/error state classes from test results (pure transformation).
 */
export function applyNodeStates(
  nodes: any[],
  nodeResults: Record<string, any>,
): any[] {
  return nodes.map((node: any) => {
    const result = nodeResults[node.id];
    if (!result) return { ...node, class: '' };
    const status = result.success ? 'node-state-success' : 'node-state-error';
    return { ...node, class: status };
  });
}

/**
 * Clears node state classes (pure transformation).
 */
export function clearNodeStates(nodes: any[]): any[] {
  return nodes.map((node: any) => ({
    ...node,
    class: (node.class || '').replace(/node-state-\w+/g, '').trim(),
  }));
}

/**
 * Applies validation error highlighting (pure transformation).
 */
export function applyNodeHighlights(
  nodes: any[],
  errorMap: Map<string, string[]>,
): any[] {
  return nodes.map((node: any) => {
    if (errorMap.has(node.id)) {
      return {
        ...node,
        class: ((node.class || '') + ' validation-error-node').trim(),
        data: {
          ...node.data,
          validationErrors: errorMap.get(node.id),
        },
      };
    }
    return node;
  });
}

/**
 * Clears validation error highlighting (pure transformation).
 */
export function clearNodeHighlightsFromNodes(nodes: any[]): any[] {
  return nodes.map((node: any) => {
    const { validationErrors, ...restData } = node.data || {};
    return {
      ...node,
      class: (node.class || '').replace('validation-error-node', '').trim(),
      data: restData,
    };
  });
}

/**
 * Filters error logs and builds a node message map for highlighting.
 */
export function buildErrorLogMap(
  logs: any[],
  $t: (key: string) => string,
): Map<string, string[]> {
  const errorLogs = logs.filter(
    (l: any) => l.status === NodeExecutionStatus.ERROR,
  );
  if (errorLogs.length === 0) return new Map();
  return buildNodeMessageMap(
    errorLogs.map((l: any) => ({
      node_id: l.node_id,
      message: l.error || $t('execution_error'),
    })),
  );
}
