/**
 * Functions for node management in the workflow designer.
 *
 * Pure functions take data directly.
 * Context functions operate on component state via minimal interfaces.
 */

import {
  NodeType,
  VF_NODE_TYPE,
} from '../workflow-advanced-models';

// ── Pure functions ──────────────────────────────────────────────────

/**
 * Cleans up workflow model variables for a node being removed.
 */
export function cleanupNodeVariables(
  node: any,
  workflowModel: Record<string, any>,
): void {
  if (node?.data?.card?.variables) {
    for (const variable of node.data.card.variables) {
      if (variable.uuid && workflowModel[variable.uuid]) {
        delete workflowModel[variable.uuid];
      }
    }
  }
}

// ── Context-based functions ─────────────────────────────────────────

export interface ManageStartNodesContext {
  nodes: any[];
  flow: {
    setNodes: (nodes: any[]) => void;
  };
  $t: (key: string) => string;
}

/**
 * Manages START nodes based on WHEN node presence.
 *
 * Backend rules:
 * - If WHEN nodes exist: Must have 0 START nodes
 * - If no WHEN nodes: Must have exactly 1 START node
 */
export function manageStartNodes(
  ctx: ManageStartNodesContext,
  startNodePosition: { x: number; y: number },
): void {
  const whenNodes = ctx.nodes.filter(
    (n: any) =>
      n.data?.nodeType === NodeType.WHEN ||
      (n.type === VF_NODE_TYPE.LOGIC && n.data?.nodeType === NodeType.WHEN),
  );
  const startNodes = ctx.nodes.filter(
    (n: any) => n.type === VF_NODE_TYPE.START,
  );

  if (whenNodes.length > 0) {
    // WHEN nodes present - remove all START nodes
    if (startNodes.length > 0) {
      ctx.nodes = ctx.nodes.filter(
        (n: any) => n.type !== VF_NODE_TYPE.START,
      );
      ctx.flow.setNodes(ctx.nodes);
    }
  } else {
    // No WHEN nodes - ensure exactly 1 START node exists
    if (startNodes.length === 0) {
      const startNode = {
        id: 'start-1',
        type: VF_NODE_TYPE.START,
        position: { ...startNodePosition },
        data: {
          nodeId: 'start-1',
          cardIndex: ctx.nodes.length,
          label: 'Start',
          tooltip: ctx.$t('start_node_tooltip'),
        },
      };
      ctx.nodes.push(startNode);
      ctx.flow.setNodes(ctx.nodes);
    } else if (startNodes.length > 1) {
      const startNodeId = startNodes[0].id;
      ctx.nodes = ctx.nodes.filter(
        (n: any) =>
          n.type !== VF_NODE_TYPE.START || n.id === startNodeId,
      );
      ctx.flow.setNodes(ctx.nodes);
    }
  }
}

export interface RemoveNodeContext {
  nodes: any[];
  workflowModel: Record<string, any>;
  flow: {
    removeNodes: (ids: any[], ...args: any[]) => void;
  };
  saveHistory: (immediate: boolean) => void;
  manageStartNodes: () => void;
}

/**
 * Removes a node, cleans up its variables, and manages START nodes.
 */
export function removeNode(
  ctx: RemoveNodeContext,
  nodeId: string,
  skipHistory = false,
): void {
  if (!skipHistory) ctx.saveHistory(true);

  const node = ctx.nodes.find((n) => n.id === nodeId);
  cleanupNodeVariables(node, ctx.workflowModel);

  ctx.flow.removeNodes([nodeId], true, false);
  ctx.manageStartNodes();
}

export interface ConfirmDelayContext {
  nodes: any[];
  delayConfigNodeId: string;
  delayConfigValue: number;
  showDelayConfigDialog: boolean;
  flow: {
    updateNode: (id: string, data: any) => void;
  };
}

/**
 * Confirms delay node configuration.
 */
export function confirmDelayConfig(
  ctx: ConfirmDelayContext,
  maxDelaySeconds: number,
): void {
  if (ctx.delayConfigValue > 0 && ctx.delayConfigValue <= maxDelaySeconds) {
    const node = ctx.nodes.find((n: any) => n.id === ctx.delayConfigNodeId);
    if (node) {
      node.data.config = { delay_seconds: ctx.delayConfigValue };
      ctx.flow.updateNode(node.id, { ...node });
    }
    ctx.showDelayConfigDialog = false;
  }
}

export interface CancelDelayContext {
  nodes: any[];
  delayConfigNodeId: string;
  showDelayConfigDialog: boolean;
  flow: {
    setNodes: (nodes: any[]) => void;
  };
}

/**
 * Cancels delay config and removes the delay node.
 */
export function cancelDelayConfig(ctx: CancelDelayContext): void {
  ctx.nodes = ctx.nodes.filter(
    (n: any) => n.id !== ctx.delayConfigNodeId,
  );
  ctx.flow.setNodes(ctx.nodes);
  ctx.showDelayConfigDialog = false;
}
