<template>
  <Teleport to="body">
    <q-card
      ref="menuCard"
      v-show="menuVisible"
      class="custom-context-menu no-shadow"
      :class="$q.dark.isActive ? 'bg-dark' : 'bg-white'"
      flat
      bordered
      :style="{
        position: 'fixed',
        top: `${adjustedY}px`,
        left: `${adjustedX}px`,
        zIndex: 9999,
        minWidth: '220px',
      }"
    >
    <q-list class="action-popup q-py-sm" style="min-width: 220px">

      <!-- ═══════════════════════════════════════════ -->
      <!-- NOTE NODE CONTEXT MENU                      -->
      <!-- ═══════════════════════════════════════════ -->
      <template v-if="isNoteSelected">
        <!-- Note Color -->
        <q-item clickable class="item q-px-md q-py-xs">
