          </q-item-section>

          <q-menu anchor="top right" self="top left">
            <q-list style="min-width: 180px">
              <q-item
                v-for="(color, index) in noteColors"
                :key="`noteColor-${index}`"
                clickable
                v-close-popup
                tabindex="0"
                @click="closeMenu(); $emit('changeNoteColor', selectedNoteId, color.code)"
              >
                <q-item-section>
                  <q-item-label>{{ $t(color.name) }}</q-item-label>
                </q-item-section>
                <q-item-section side>
