                </q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-item>

        <q-separator color="grey-3" class="q-my-sm" inset />

        <!-- Copy Note Node -->
        <q-item
          clickable
          @click="closeMenu(); $emit('copyNode')"
          class="item q-px-md q-py-xs"
        >
          <q-item-section>
            <q-item-label style="font-size: 16px;">{{ $t('copy') }}</q-item-label>
          </q-item-section>
          <q-item-section side>
            <span style="font-size: 16px; font-family: -apple-system, BlinkMacSystemFont, sans-serif;" class="text-grey-5">{{ modKey }}C</span>
          </q-item-section>
        </q-item>

        <!-- Duplicate Note -->
        <q-item
          clickable
          @click="closeMenu(); $emit('duplicateNodes')"
          class="item q-px-md q-py-xs"
        >
          <q-item-section>
            <q-item-label style="font-size: 16px;">{{ $t('duplicate') }}</q-item-label>
          </q-item-section>
          <q-item-section side>
            <span style="font-size: 16px; font-family: -apple-system, BlinkMacSystemFont, sans-serif;" class="text-grey-5">{{ modKey }}D</span>
          </q-item-section>
        </q-item>

        <!-- Paste -->
        <q-item
          :disable="!canPaste"
          clickable
          @click="closeMenu(); $emit('pasteNodes', { x: positionX, y: positionY })"
          class="item q-px-md q-py-xs"
          :class="!canPaste ? 'text-grey-5' : ''"
        >
          <q-item-section>
            <q-item-label style="font-size: 16px;">{{ $t('paste') }}</q-item-label>
          </q-item-section>
          <q-item-section side>
            <span style="font-size: 16px; font-family: -apple-system, BlinkMacSystemFont, sans-serif;" :class="!canPaste ? 'text-grey-4' : 'text-grey-5'">{{ modKey }}V</span>
          </q-item-section>
        </q-item>

        <q-separator color="grey-3" class="q-my-sm" inset />

        <!-- Delete Note -->
        <q-item
          clickable
