          class="delete-item q-px-md q-py-xs"
        >
          <q-item-section>
            <q-item-label style="font-size: 16px;" class="text-negative">{{ $t('delete') }}</q-item-label>
          </q-item-section>
          <q-item-section side>
            <q-icon name="delete_outline" color="negative" size="sm" />
          </q-item-section>
        </q-item>
      </template>

      <!-- ═══════════════════════════════════════════ -->
      <!-- REGULAR NODE / CANVAS CONTEXT MENU          -->
      <!-- ═══════════════════════════════════════════ -->
      <template v-else>
        <!-- Add — always available -->
        <q-item clickable class="item q-px-md q-py-xs">
          <q-item-section>
            <q-item-label style="font-size: 16px;">{{ $t('advanced_workflow_menu_label_add') }}</q-item-label>
          </q-item-section>
          <q-item-section side>
            <q-icon name="keyboard_arrow_right" color="grey-5" size="sm" />
          </q-item-section>

          <q-menu ref="addSubmenu" anchor="top right" self="top left">
            <q-list style="min-width: 200px">
              <q-item
                v-for="(conditionItem, index) in conditionsList"
                :key="`conditionItem-${index}`"
                clickable
                tabindex="0"
                @click="closeMenu(); $emit('add-node', { type: 'condition', item: conditionItem })"
              >
                <q-item-section v-if="(conditionItem as any).icon" avatar>
                  <q-icon :name="(conditionItem as any).icon" :style="(conditionItem as any).color ? `color: ${(conditionItem as any).color}` : ''" size="sm" />
                </q-item-section>
                <q-item-section>
                  <q-item-label>{{ $t((conditionItem as any).name) }} ...</q-item-label>
                </q-item-section>
              </q-item>
              <q-separator inset />
              <q-item>
                <q-item-section>
                  <div class="text-grey-5 text-subtitle2">{{ $t('advanced_workflow_menu_label_start') }}</div>
                </q-item-section>
                <q-item-section side>
                  <div class="text-grey-5 text-subtitle2">1/1</div>
                </q-item-section>
              </q-item>
              <q-item
                v-for="(otherOption, index) in otherOptions"
                :key="`otherOption-${index}`"
                clickable
                tabindex="0"
                @click="closeMenu(); $emit('add-node', { type: 'other', item: otherOption })"
              >
                <q-item-section v-if="(otherOption as any).icon" avatar>
                  <q-icon :name="(otherOption as any).icon" :style="(otherOption as any).color ? `color: ${(otherOption as any).color}` : ''" size="sm" />
                </q-item-section>
                <q-item-section>
                  <q-item-label>{{ $t((otherOption as any).label) }}</q-item-label>
                </q-item-section>
              </q-item>
              <q-separator inset />
              <q-item
                v-for="(footerOption, index) in footerOptions"
                :key="`footerOption-${index}`"
                clickable
                tabindex="0"
                @click="closeMenu(); $emit('add-node', { type: 'other', item: footerOption })"
              >
                <q-item-section v-if="(footerOption as any).icon" avatar>
                  <q-icon :name="(footerOption as any).icon" :style="(footerOption as any).color ? `color: ${(footerOption as any).color}` : ''" size="sm" />
                </q-item-section>
                <q-item-section>
                  <q-item-label>{{ $t((footerOption as any).label) }}</q-item-label>
                </q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-item>

        <q-separator color="grey-3" class="q-my-sm" inset />

        <!-- Paste — always available -->
        <q-item
          :disable="!canPaste"
          clickable
          @click="closeMenu(); $emit('pasteNodes', { x: positionX, y: positionY })"
          class="item q-px-md q-py-xs"
          :class="!canPaste ? 'text-grey-5' : ''"
        >
          <q-item-section>
            <q-item-label style="font-size: 16px;">{{ $t('paste') }}</q-item-label>
          </q-item-section>
          <q-item-section side>
            <span style="font-size: 16px; font-family: -apple-system, BlinkMacSystemFont, sans-serif;" :class="!canPaste ? 'text-grey-4' : 'text-grey-5'">{{ modKey }}V</span>
          </q-item-section>
        </q-item>

        <!-- Node-specific actions — only when a workflow node is selected -->
        <template v-if="hasSelection">
          <q-separator color="grey-3" class="q-my-sm" inset />

          <!-- Copy -->
          <q-item
            :disable="!canCopy"
            clickable
            @click="closeMenu(); $emit('copyNode')"
            class="item q-px-md q-py-xs"
            :class="!canCopy ? 'text-grey-5' : ''"
          >
            <q-item-section>
              <q-item-label style="font-size: 16px;">{{ $t('copy') }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <span style="font-size: 16px; font-family: -apple-system, BlinkMacSystemFont, sans-serif;" :class="!canCopy ? 'text-grey-4' : 'text-grey-5'">{{ modKey }}C</span>
            </q-item-section>
          </q-item>

          <!-- Duplicate -->
          <q-item
            :disable="!canCopy"
            clickable
            @click="closeMenu(); $emit('duplicateNodes')"
            class="item q-px-md q-py-xs"
            :class="!canCopy ? 'text-grey-5' : ''"
          >
            <q-item-section>
              <q-item-label style="font-size: 16px;">{{ $t('duplicate') }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <span style="font-size: 16px; font-family: -apple-system, BlinkMacSystemFont, sans-serif;" :class="!canCopy ? 'text-grey-4' : 'text-grey-5'">{{ modKey }}D</span>
            </q-item-section>
          </q-item>

          <!-- Replace -->
          <q-item
            :disable="!canReplace"
            clickable
            @click="closeMenu(); $emit('replaceNode')"
            class="item q-px-md q-py-xs"
            :class="!canReplace ? 'text-grey-5' : ''"
          >
            <q-item-section>
              <q-item-label style="font-size: 16px;">{{ $t('replace') }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-icon name="swap_horiz" :color="!canReplace ? 'grey-4' : 'grey-7'" size="sm" />
            </q-item-section>
          </q-item>

          <!-- Reverse Condition -->
          <q-item
            :disable="!canReverse"
            clickable
            @click="closeMenu(); $emit('reverseNode')"
            class="item q-px-md q-py-xs"
            :class="!canReverse ? 'text-grey-5' : ''"
          >
            <q-item-section>
              <q-item-label style="font-size: 16px;">{{ $t('reverse_condition') }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-icon name="swap_vert" :color="!canReverse ? 'grey-4' : 'grey-7'" size="sm" />
            </q-item-section>
          </q-item>

          <!-- Test from Node -->
          <q-item
            :disable="!canTestFromNode"
            clickable
            @click.stop="closeMenu(); $emit('testFromNode')"
            class="item q-px-md q-py-xs"
            :class="!canTestFromNode ? 'text-grey-5' : ''"
          >
            <q-item-section>
              <q-item-label style="font-size: 16px;">{{ $t('test_from_node') }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-icon name="play_arrow" :color="!canTestFromNode ? 'grey-4' : 'grey-7'" size="sm" />
            </q-item-section>
          </q-item>

          <!-- Delete -->
          <q-separator color="grey-3" class="q-my-sm" inset />
          <q-item
            clickable
            @click="closeMenu(); $emit('removeNode')"
            class="delete-item q-px-md q-py-xs"
          >
            <q-item-section>
              <q-item-label style="font-size: 16px;" class="text-negative">{{ $t('delete') }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-icon name="delete_outline" color="negative" size="sm" />
            </q-item-section>
          </q-item>
        </template>
      </template>

    </q-list>
    </q-card>
  </Teleport>
</template>

<script lang="ts">
import { defineComponent, PropType, ref, watch, nextTick } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import Cache from 'src/utils/cache';
import helperMixin from 'src/mixins/helperMixin';
import { Platform } from 'quasar';
import { VF_NODE_TYPE, NodeType } from '../workflow-advanced-models';

const NOTE_COLORS = [
  { name: 'yellow', code: '#fef48a' },
  { name: 'red', code: '#ffcdd2' },
  { name: 'green', code: '#98fb98' },
  { name: 'blue', code: '#b3e5fc' },
  { name: 'purple', code: '#d1c4e9' },
  { name: 'orange', code: '#ffe0b2' },
];

export default defineComponent({
  name: 'AdvancedWorkflowContextMenu',
  mixins: [helperUtil, helperMixin, Cache],
  props: {
    modelValue: {
      type: Boolean,
      required: true,
    },
    positionX: {
      type: Number,
      default: 0,
    },
    positionY: {
      type: Number,
      default: 0,
    },
    conditionsList: {
      type: Array,
      required: true,
    },
    otherOptions: {
      type: Array,
      required: true,
    },
    footerOptions: {
      type: Array,
      required: true,
    },
    selectedNodes: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
    selectedEdges: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
    hasCopiedNodes: {
      type: Boolean,
      default: false,
    },
  },
  emits: [
    'update:modelValue',
    'add-node',
    'copyNode',
    'duplicateNodes',
    'replaceNode',
    'pasteNodes',
    'removeNode',
    'testFromNode',
    'reverseNode',
    'changeNoteColor',
    'deleteNote',
  ],
  setup(props) {
    const modKey = Platform.is.mac ? '⌘' : 'Ctrl+';
    const menuCard = ref<{ $el?: HTMLElement } | null>(null);
    const adjustedX = ref(0);
    const adjustedY = ref(0);
    const EDGE_PADDING = 8;

    watch(
      () => [props.modelValue, props.positionX, props.positionY],
      ([visible]) => {
        // Start at the requested position
        adjustedX.value = props.positionX;
        adjustedY.value = props.positionY;

        if (!visible) return;

        // After render, measure actual size and reposition if needed
        nextTick(() => {
          const el = menuCard.value?.$el as HTMLElement | undefined;
          if (!el) return;
          const rect = el.getBoundingClientRect();
          const vw = window.innerWidth;
          const vh = window.innerHeight;

          let x = props.positionX;
          let y = props.positionY;

          // Overflow right → flip to left of cursor
          if (x + rect.width > vw - EDGE_PADDING) {
            x = Math.max(EDGE_PADDING, x - rect.width);
          }
          // Overflow bottom → flip to above cursor
          if (y + rect.height > vh - EDGE_PADDING) {
            y = Math.max(EDGE_PADDING, y - rect.height);
          }

          adjustedX.value = x;
          adjustedY.value = y;
        });
      },
      { immediate: true },
    );

    return { modKey, menuCard, adjustedX, adjustedY, noteColors: NOTE_COLORS };
  },
  computed: {
    /** True when any node or edge is selected */
    hasSelection(): boolean {
      return this.selectedNodes.length > 0 || this.selectedEdges.length > 0;
    },
    /** True when exactly one note node is selected (and nothing else) */
    isNoteSelected(): boolean {
      return (
        this.selectedNodes.length === 1 &&
        this.selectedEdges.length === 0 &&
        this.selectedNodes[0].type === VF_NODE_TYPE.NOTE
      );
    },
    /** The selected note's node ID (only valid when isNoteSelected) */
    selectedNoteId(): string | null {
      if (!this.isNoteSelected) return null;
      return this.selectedNodes[0].id;
    },
    /** Workflow nodes only (excludes START and NOTE nodes) */
    workflowSelected(): any[] {
      return this.selectedNodes.filter(
        (n: any) => n.type !== VF_NODE_TYPE.START && n.type !== VF_NODE_TYPE.NOTE,
      );
    },
    canCopy(): boolean {
      return this.workflowSelected.length > 0;
    },
    canDelete(): boolean {
      return this.selectedNodes.length > 0 || this.selectedEdges.length > 0;
    },
    menuVisible: {
      get() {
        return this.modelValue;
      },
      set(val: boolean) {
        this.$emit('update:modelValue', val);
      },
    },
    canPaste(): boolean {
      return this.hasCopiedNodes;
    },
    canReplace(): boolean {
      if (this.workflowSelected.length !== 1) return false;
      const selected = this.selectedNodes.filter((n: any) => n.type === VF_NODE_TYPE.LOGIC);
      if (selected.length !== 1) return false;
      const nodeType = selected[0].data?.nodeType;
      return nodeType === NodeType.WHEN || nodeType === NodeType.AND || nodeType === NodeType.THEN;
    },
    canReverse(): boolean {
      const selected = this.selectedNodes.filter((n: any) => n.type === VF_NODE_TYPE.LOGIC);
      if (selected.length !== 1) return false;
      const nodeType = selected[0].data?.nodeType;
      return nodeType === NodeType.WHEN || nodeType === NodeType.AND;
    },
    canTestFromNode(): boolean {
      return this.workflowSelected.length === 1;
    },
  },
  methods: {
    closeMenu() {
      (this.$refs.addSubmenu as any)?.hide?.();
      this.$emit('update:modelValue', false);
    },
  },
});
</script>

