<template>
  <g
    class="edge-group"
    @mouseenter="hovered = true"
    @mouseleave="hovered = false"
  >
    <!-- Hit area: wide invisible stroke for easy hover -->
    <path
      :d="edgePath"
      fill="none"
      stroke="transparent"
      stroke-width="20"
      style="cursor: pointer"
    />
    <!-- Glow: white background stroke, visible on hover -->
    <path
      :d="edgePath"
      fill="none"
      :stroke="WORKFLOW_GLOW"
      :stroke-width="hovered ? 6 : 0"
      style="transition: stroke-width 0.2s cubic-bezier(0.25, 0, 0.5, 1)"
    />
    <!-- Main line (dimmed when test results are active or tree highlight is on for unrelated edges) -->
    <path
      :d="edgePath"
      fill="none"
      :stroke="isDimmed ? '#ccc' : data?.color || WORKFLOW_GRAY"
      :stroke-width="isDimmed ? 1.5 : isTreeHighlighted ? 2.5 : 2"
      :stroke-opacity="isDimmed ? 0.4 : 1"
      style="
        transition:
          stroke 0.2s,
          stroke-width 0.2s,
          stroke-opacity 0.2s;
      "
    />
    <!-- Selected/animated dashes (shown when edge is selected) -->
    <path
      v-if="$attrs.selected"
      :d="edgePath"
      fill="none"
      :stroke="data?.color || WORKFLOW_BLUE"
      stroke-width="3"
      stroke-dasharray="8 4"
      class="animated-dash"
    />
    <!-- Test execution animation (shown when path was taken during test) -->
    <path
      v-if="data?.testExecuting"
      :d="edgePath"
      fill="none"
      :stroke="testStatusColor"
      stroke-width="3"
      stroke-dasharray="8 4"
      class="test-flow-dash"
    />
    <!-- Persistent test result indicator (after animation completes) -->
    <path
      v-if="data?.testResult && !data?.testExecuting"
      :d="edgePath"
      fill="none"
      :stroke="testResultColor"
      stroke-width="3"
      stroke-dasharray="8 4"
      stroke-opacity="0.7"
    />
  </g>
  <!-- Delete button rendered above nodes via EdgeLabelRenderer -->
  <EdgeLabelRenderer>
    <div
      class="edge-delete-overlay"
      :class="{ 'edge-delete-visible': hovered }"
      :style="{ transform: `translate(-50%, -50%) translate(${labelX}px, ${labelY}px)` }"
      @mouseenter="hovered = true"
      @mouseleave="hovered = false"
      @click="removeEdge"
    >
      <div class="edge-delete-btn">✕</div>
    </div>
  </EdgeLabelRenderer>
</template>

<script>
import { getBezierPath, EdgeLabelRenderer } from '@vue-flow/core';
import { WORKFLOW_BLUE, WORKFLOW_GLOW, WORKFLOW_GRAY } from './workflowColors';
import { getNodeStatusHexColor } from '../composables/useNodeStatusDisplay';

export default {
  name: 'cardEdge',
  components: { EdgeLabelRenderer },
  props: {
    id: String,
    sourceX: Number,
    sourceY: Number,
    targetX: Number,
    targetY: Number,
    sourcePosition: String,
    targetPosition: String,
    data: Object,
  },
  data() {
    return {
      hovered: false,
      WORKFLOW_BLUE,
      WORKFLOW_GLOW,
      WORKFLOW_GRAY,
    };
  },
  computed: {
    bezierResult() {
      return getBezierPath({
        sourceX: this.sourceX,
        sourceY: this.sourceY,
        targetX: this.targetX,
        targetY: this.targetY,
        sourcePosition: this.sourcePosition,
        targetPosition: this.targetPosition,
      });
    },
    edgePath() {
      return this.bezierResult[0];
    },
    labelX() {
      return this.bezierResult[1];
    },
    labelY() {
      return this.bezierResult[2];
    },
    testStatusColor() {
      return getNodeStatusHexColor(this.data?.testStatus, '#2196f3');
    },
    testResultColor() {
      return getNodeStatusHexColor(this.data?.testResult);
    },
    isGreyedOut() {
      // Grey out edges that weren't executed when test results are showing
      return (
        this.data?.hasTestResults &&
        !this.data?.testExecuting &&
        !this.data?.testResult
      );
    },
    isTreeDimmed() {
      return this.data?.treeDimmed === true;
    },
    isTreeHighlighted() {
      return this.data?.treeHighlight === true;
    },
    isDimmed() {
      return this.isGreyedOut || this.isTreeDimmed;
    },
  },
  methods: {
    removeEdge() {
      if (!this.data) {
        console.error('[cardEdge] ERROR: No data object found');
        return;
      }

      if (!this.data.remove) {
        console.error('[cardEdge] ERROR: No remove callback found');
        console.error(
          '[cardEdge] Available data keys:',
          Object.keys(this.data),
        );
        return;
      }

      try {
        const position = {
          sourceX: this.sourceX,
          sourceY: this.sourceY,
          targetX: this.targetX,
          targetY: this.targetY,
        };

        this.data.remove(this.id, position);
      } catch (error) {
        console.error('[cardEdge] ERROR during removal:', error);
        console.error('[cardEdge] Stack:', error.stack);
      }
    },
  },
};
</script>

<style scoped>
.animated-dash {
  animation: dash-flow 0.8s linear infinite;
  stroke-width: 4;
}
@keyframes dash-flow {
  to {
    stroke-dashoffset: -24;
  }
}
/*
Animation used for paths in test execution from @workflow-designer-advanced
*/
.test-flow-dash {
  animation: test-flow 0.8s linear infinite;
  stroke-width: 4;
}
@keyframes test-flow {
  to {
    stroke-dashoffset: -24;
  }
}
</style>

<style>
.edge-delete-overlay {
  position: absolute;
  width: 24px;
  height: 24px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s ease;
}
.edge-delete-overlay.edge-delete-visible {
  pointer-events: all;
  opacity: 1;
}
.edge-delete-btn {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #f44336;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: white;
  font-size: 14px;
  font-weight: bold;
}
</style>
