<template>
  <div :class="['toolbar-wrapper', 'q-pa-sm', { 'toolbar-wrapper--dark': $q.dark.isActive }]">
    <transition name="slide-up">
      <q-toolbar v-show="isToolbarVisible" class="modern-workflow-toolbar shadow-3 rounded-borders" dense>
      <!-- Dropdown for Workflow Conditions -->
      <AdvancedWorkflowNodesDropDown
        v-bind="{} as any"
        :conditionsList="conditionsList"
        :otherOptions="otherOptions"
        :footerOptions="footerOptions"
        @add-node="handleAddNode"
      />

      <q-separator vertical inset class="q-mx-sm" />
      
      <q-btn flat round dense icon="undo" @click="undo">
        <q-tooltip>{{ $t('undo') }} (Ctrl+Z)</q-tooltip>
      </q-btn>
      <q-btn flat round dense icon="redo" @click="redo">
        <q-tooltip>{{ $t('redo') }} (Ctrl+Shift+Z)</q-tooltip>
      </q-btn>
      
      <q-separator vertical inset class="q-mx-sm" />
      
      <q-btn flat round dense icon="zoom_out" @click="zoomOut">
        <q-tooltip>{{ $t('zoom_out') }}</q-tooltip>
      </q-btn>
      <q-btn flat round dense icon="zoom_in" @click="zoomIn">
        <q-tooltip>{{ $t('zoom_in') }}</q-tooltip>
      </q-btn>
      
      <q-separator vertical inset class="q-mx-sm" />

      <q-input
        v-model="workflowNameLocal"
        dense
        borderless
        :placeholder="$t('workflow_name')"
        class="workflow-name-input q-px-sm"
        style="min-width: 150px"
      />

      <q-btn flat round dense icon="description" @click="$emit('edit-description')">
        <q-tooltip>{{ $t('edit_description') }}</q-tooltip>
      </q-btn>

      <div v-if="lastAutoSave" class="auto-save-indicator q-mx-sm text-grey-6 text-caption">
        <q-icon name="cloud_done" size="xs" class="q-mr-xs" />
        <span>{{ autoSaveText }}</span>
        <q-tooltip>{{ $t('last_autosave') }}</q-tooltip>
      </div>

      <q-btn flat round dense data-test="awf-variables" icon="data_object" @click="$emit('show-variables')">
        <q-tooltip>{{ $t('variables') }}</q-tooltip>
      </q-btn>

      <q-btn flat round dense data-test="awf-shortcuts" icon="help_outline" @click="$emit('show-shortcuts')">
        <q-tooltip>{{ $t('keyboard_shortcuts_and_help') }}</q-tooltip>
      </q-btn>

      <q-separator vertical inset class="q-mx-sm" />

      <q-btn
        flat
        round
        dense
        data-test="awf-validate"
        class="q-mr-xs"
        :loading="validating"
        @click="$emit('validate')"
        icon="check_circle"
      >
        <q-tooltip>{{ $t('validate') }}</q-tooltip>
