        round
        dense
        class="q-ml-xs"
        @click="$emit('open-logs')"
        icon="list_alt"
      >
        <q-tooltip>{{ $t('logs') }}</q-tooltip>
      </q-btn> -->
      <!-- hide log button until it is clear what we do with it, logs require the document id and individual test results depend on state of workflow in designer -->

      <q-separator vertical inset class="q-mx-sm" />

      <q-btn flat round dense icon="image" @click="$emit('export-image')">
        <q-tooltip>{{ $t('export_image') }}</q-tooltip>
      </q-btn>
      <!-- <q-btn flat round dense icon="bookmark_add" @click="$emit('save-as-template')">
        <q-tooltip>{{ $t('save_as_template') }}</q-tooltip>
      </q-btn> --> 
      <!-- remove templates for now before support is added -->

      <q-btn
        color="primary"
        unelevated
        round
        class="q-ml-sm"
        :loading="saving"
        @click="$emit('save')"
        icon="save"
      >
        <q-tooltip>{{ $t('save') }} (Ctrl+S)</q-tooltip>
      </q-btn>

      <q-btn
        flat
        round
        dense
        :disable="!workflowId"
        :icon="workflowEnabled ? 'toggle_on' : 'toggle_off'"
        :color="!workflowId ? 'grey-5' : workflowEnabled ? 'positive' : 'grey-6'"
        @click="$emit('toggle-enabled')"
      >
        <q-tooltip>
          {{ !workflowId
            ? $t('save_workflow_first')
            : workflowEnabled
              ? $t('deactivate_workflow')
              : $t('activate_workflow')
          }}
        </q-tooltip>
      </q-btn>

      <q-separator vertical inset class="q-mx-sm" />

      <q-btn
        flat
        round
        dense
        class="text-grey-5"
        icon="expand_more"
        @click="isToolbarVisible = false"
      >
        <q-tooltip>{{ $t('hide_toolbar') }}</q-tooltip>
      </q-btn>
      </q-toolbar>
    </transition>

    <transition name="slide-up">
      <div v-show="!isToolbarVisible" class="show-toolbar-btn-container q-mt-sm">
        <q-btn
          color="white"
          text-color="primary"
          round
          icon="expand_less"
          class="shadow-3"
          @click="isToolbarVisible = true"
        >
          <q-tooltip>{{ $t('show_toolbar') }}</q-tooltip>
        </q-btn>
      </div>
    </transition>
  </div>
</template>

<script lang="ts">

import { defineComponent, ref, computed, onMounted, onUnmounted } from 'vue';
import AdvancedWorkflowNodesDropDown from 'src/pages/WorkflowBuilder/WorkflowComponnets/AdvancedWorkflowNodesDropDown.vue';
import { formatAutoSaveTime } from './workflowToolbarUtils';
export default defineComponent({
  name: 'AdvancedWorkflowToolbar',
  components: {
    AdvancedWorkflowNodesDropDown,
    
  },
  emits: [
    'add-node',
    'zoom-in',
    'zoom-out',
    'undo',
    'redo',
    'save',
    'validate',
    'test',
    'open-logs',
    'toggle-snap',
    'toggle-minimap',
    'save-as-template',
    'update:workflowName',
    'show-shortcuts',
    'export-image',
    'edit-description',
    'show-variables',
    'search-nodes',
    'toggle-enabled',
  ],
  props: {
    conditionsList: {
      type: Array,
      default: () => [],
    },
    otherOptions: {
      type: Array,
      default: () => [],
    },
    footerOptions: {
      type: Array,
      default: () => [],
    },
    workflowName: {
      type: String,
      default: '',
    },
    saving: {
      type: Boolean,
      default: false,
    },
    validating: {
      type: Boolean,
      default: false,
    },
    testing: {
      type: Boolean,
      default: false,
    },
    snapEnabled: {
      type: Boolean,
      default: true,
    },
    lastAutoSave: {
      type: Date as any,
      default: null,
    },
    workflowId: {
      type: String,
      default: '',
    },
    workflowEnabled: {
      type: Boolean,
      default: false,
    },
  },
  setup(props, { emit }) {
    const isToolbarVisible = ref(true);
    const now = ref(Date.now());
    let tickTimer: ReturnType<typeof setInterval> | null = null;

    onMounted(() => {
      tickTimer = setInterval(() => { now.value = Date.now(); }, 30_000);
    });
    onUnmounted(() => {
      if (tickTimer) clearInterval(tickTimer);
    });

    const autoSaveText = computed(() =>
      formatAutoSaveTime(props.lastAutoSave, now.value),
    );

    const zoomIn = () => emit('zoom-in');
    const zoomOut = () => emit('zoom-out');
    const undo = () => emit('undo');
    const redo = () => emit('redo');

    const handleAddNode = (payload: { type: string; item: any }) => {
      emit('add-node', payload);
    };

    const workflowNameLocal = computed({
      get: () => props.workflowName,
      set: (val: string) => emit('update:workflowName', val),
    });


    return {
      isToolbarVisible,
      workflowNameLocal,
      handleAddNode,
      autoSaveText,
      zoomIn,
      zoomOut,
      undo,
      redo,
    };
  },
});
</script>

