/**
 * Pure functions for looking up cards in the workflow card catalog.
 *
 * These are stateless helpers — they take card category arrays as parameters
 * instead of accessing component state via `this`.
 */

export interface CardCategory {
  category: string;
  svg_background_color?: string;
  cards?: { id: string; [key: string]: any }[];
  [key: string]: any;
}

/**
 * Checks if a card ID exists in any of the provided card categories.
 */
export function checkCardExists(cardId: string, allCardCategories: CardCategory[]): boolean {
  for (const category of allCardCategories) {
    if (category.cards) {
      const found = category.cards.find((c) => c.id === cardId);
      if (found) return true;
    }
  }
  return false;
}

/**
 * Gets a card object from the catalog by ID.
 */
export function getCardById(cardId: string, allCardCategories: CardCategory[]): any | null {
  for (const category of allCardCategories) {
    if (category.cards) {
      const found = category.cards.find((c) => c.id === cardId);
      if (found) return found;
    }
  }
  return null;
}

/**
 * Gets the category color (svg_background_color) by category name.
 */
export function getCategoryColor(
  categoryName: string | null | undefined,
  allCardCategories: CardCategory[],
): string | null {
  if (!categoryName) return null;

  for (const category of allCardCategories) {
    if (category.category === categoryName) {
      return category.svg_background_color || null;
    }
  }

  return null;
}

/**
 * Gets a card from a specific store (keyed by node type) with category color merged.
 */
export function getCardFromStore(
  cardId: string,
  categoryName: string,
  nodeType: string,
  cardStoreMap: Record<string, CardCategory[]>,
): any | null {
  const cardStore = cardStoreMap[nodeType];
  if (!cardStore) return null;

  const category = cardStore.find((cat) => cat.category === categoryName);
  if (!category || !category.cards) return null;

  const card = category.cards.find((c) => c.id === cardId);
  if (card) {
    return {
      ...card,
      svg_background_color: category.svg_background_color,
    };
  }
  return null;
}
