/**
 * Node-level operations for the advanced workflow designer.
 *
 * Note mutations, batch deletion, and keyboard shortcut dispatch.
 * Extracted from workflow-designer-advanced.vue for testability.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Context for note mutation and batch deletion operations. */
export interface NoteContext {
  nodes: any[];
  flow: {
    addNodes: (nodes: any[]) => void;
    removeNodes: (ids: any[], ...args: any[]) => void;
  };
  saveHistory: (immediate: boolean) => void;
}

export interface BatchContext extends NoteContext {
  removeNode: (nodeId: string, skipHistory: boolean) => void;
}

export interface KeydownContext {
  saveWorkflow: () => void;
  undoCanvas: () => void;
  redoCanvas: () => void;
  copySelectedNodes: () => void;
  duplicateSelectedNodes: () => void;
  pasteNodes: () => void;
  validateWorkflow: () => void;
  testWorkflow: () => void;
  removeSelectedNodes: () => void;
  showShortcutsHelp: boolean;
  nodes: any[];
  flow?: { setNodes: (nodes: any[]) => void };
}

// ---------------------------------------------------------------------------
// Note operations (save history before mutation)
// ---------------------------------------------------------------------------

export function updateNoteContent(ctx: NoteContext, noteId: string, content: any): void {
  const node = ctx.nodes.find((n: any) => n.id === noteId);
  if (node?.data) {
    ctx.saveHistory(true);
    node.data.content = content;
  }
}

export function changeNoteColor(ctx: NoteContext, noteId: string, color: string): void {
  const node = ctx.nodes.find((n: any) => n.id === noteId);
  if (node?.data) {
    ctx.saveHistory(true);
    node.data.color = color;
  }
}

export function resizeNote(ctx: NoteContext, noteId: string, width: number, height: number): void {
  const node = ctx.nodes.find((n: any) => n.id === noteId);
  if (node?.data) {
    ctx.saveHistory(true);
    node.data.noteWidth = width;
    node.data.noteHeight = height;
  }
}

export function deleteNote(ctx: NoteContext, noteId: string, skipHistory = false): void {
  if (!skipHistory) ctx.saveHistory(true);
  ctx.flow.removeNodes([noteId]);
}

// ---------------------------------------------------------------------------
// Batch operations (single history entry for multi-node actions)
// ---------------------------------------------------------------------------

export function removeSelectedNodes(ctx: BatchContext): void {
  const selectedNodes = ctx.nodes.filter((n: any) => n.selected);
  if (selectedNodes.length === 0) return;
  ctx.saveHistory(true);
  selectedNodes.forEach((node: any) => {
    if (node.type === 'noteNode') {
      deleteNote(ctx, node.id, true);
    } else {
      ctx.removeNode(node.id, true);
    }
  });
}

// ---------------------------------------------------------------------------
// Keyboard shortcut dispatcher
// ---------------------------------------------------------------------------

interface Shortcut {
  /** Key(s) to match — lowercase comparison unless exact match needed. */
  key: string | string[];
  /** Require Ctrl (Windows/Linux) or Cmd (macOS). Default false. */
  mod?: boolean;
  /** Require Shift. Default false. */
  shift?: boolean;
  /** When true, require that mod is NOT pressed. Default false. */
  noMod?: boolean;
  /** Skip this shortcut when an input/textarea/contentEditable is focused. Default false. */
  noInput?: boolean;
  /** Callback to execute when the shortcut matches. */
  action: (ctx: KeydownContext) => void;
}

const SHORTCUTS: Shortcut[] = [
  // Ctrl+S — save (works in inputs)
  { key: 's', mod: true, action: (ctx) => ctx.saveWorkflow() },
  // Ctrl+Z — undo (not in inputs, no shift)
  { key: 'z', mod: true, noInput: true, action: (ctx) => ctx.undoCanvas() },
  // Ctrl+Shift+Z — redo (not in inputs; browsers may report 'z' or 'Z' with shift)
  { key: ['z', 'Z'], mod: true, shift: true, noInput: true, action: (ctx) => ctx.redoCanvas() },
  // Ctrl+C — copy (not in inputs)
  { key: 'c', mod: true, noInput: true, action: (ctx) => ctx.copySelectedNodes() },
  // Ctrl+D — duplicate (not in inputs)
  { key: 'd', mod: true, noInput: true, action: (ctx) => ctx.duplicateSelectedNodes() },
  // Ctrl+V — paste (not in inputs)
  { key: 'v', mod: true, noInput: true, action: (ctx) => ctx.pasteNodes() },
  // Ctrl+Shift+V — validate workflow (works in inputs)
  { key: 'V', mod: true, shift: true, action: (ctx) => ctx.validateWorkflow() },
  // Ctrl+Shift+T — test workflow (works in inputs)
  { key: 'T', mod: true, shift: true, action: (ctx) => ctx.testWorkflow() },
  // ? — show shortcuts help (no mod key, not in inputs)
  { key: '?', noMod: true, noInput: true, action: (ctx) => { ctx.showShortcutsHelp = true; } },
  // Ctrl+A — select all nodes (not in inputs)
  {
    key: 'a',
    mod: true,
    noInput: true,
    action: (ctx) => {
      ctx.nodes.forEach((n: any) => { n.selected = true; });
      if (ctx.flow?.setNodes) ctx.flow.setNodes([...ctx.nodes]);
    },
  },
  // Delete / Backspace — remove selected nodes (not in inputs)
  { key: ['Delete', 'Backspace'], noInput: true, action: (ctx) => ctx.removeSelectedNodes() },
];

export function handleKeydown(ctx: KeydownContext, e: KeyboardEvent): void {
  const tag = (e.target as HTMLElement)?.tagName;
  const isInputFocused = tag === 'INPUT' || tag === 'TEXTAREA' || (e.target as HTMLElement)?.isContentEditable;
  const hasMod = e.ctrlKey || e.metaKey;

  for (const shortcut of SHORTCUTS) {
    // Key match — support single string or array of strings
    const keys = Array.isArray(shortcut.key) ? shortcut.key : [shortcut.key];
    if (!keys.includes(e.key)) continue;

    // Modifier checks
    if (shortcut.mod && !hasMod) continue;
    if (shortcut.noMod && hasMod) continue;
    if (shortcut.shift && !e.shiftKey) continue;
    // When shift is not required, reject if shift IS pressed (avoids Ctrl+Z matching Ctrl+Shift+Z)
    if (!shortcut.shift && shortcut.mod && e.shiftKey) continue;

    // Input focus check
    if (shortcut.noInput && isInputFocused) continue;

    e.preventDefault();
    shortcut.action(ctx);
    return;
  }
}
