// ---------------------------------------------------------------------------
// Pure functions (no context)
// ---------------------------------------------------------------------------

export function buildNodeMessageMap(
  entries: any[],
  idKey = 'node_id',
  msgKey = 'message',
): Map<string, string[]> {
  const map = new Map<string, string[]>();
  entries
    .filter((e: any) => e[idKey])
    .forEach((e: any) => {
      if (!map.has(e[idKey])) map.set(e[idKey], []);
      map.get(e[idKey])!.push(e[msgKey] || 'Error');
    });
  return map;
}

export function getTestResultNodeClass(
  result: NodeExecutionResultData | undefined,
  hasWarnings = false,
): string {
  let cls = '';
  if (!result) {
    return hasWarnings ? 'test-result-warning' : '';
  }
  if (!result.executed) {
    cls = 'test-result-skipped';
  } else if (result.path_taken === PathResult.FAILED_CONDITION) {
    cls = 'test-result-failed-condition';
  } else if (result.path_taken === PathResult.ERROR || !result.success) {
    cls = 'test-result-error';
  } else {
    cls = 'test-result-success';
  }
  if (hasWarnings) {
    cls += ' test-result-warning';
  }
  return cls;
}

export function getTestResultBadgeClass(result: NodeExecutionResultData): string {
  if (!result.executed) return 'badge-skipped';
  if (result.path_taken === PathResult.FAILED_CONDITION) return 'badge-failed-condition';
  if (result.path_taken === PathResult.ERROR || !result.success) return 'badge-error';
  return 'badge-success';
}

export function getTestResultIcon(result: NodeExecutionResultData): string {
  if (!result.executed) return getNodeStatusIcon(NodeExecutionStatus.SKIPPED);
  if (result.path_taken === PathResult.FAILED_CONDITION) return getNodeStatusIcon(NodeExecutionStatus.FAILED_CONDITION);
  if (result.path_taken === PathResult.ERROR || !result.success) return getNodeStatusIcon(NodeExecutionStatus.ERROR);
  return getNodeStatusIcon(NodeExecutionStatus.SUCCESS);
}

export function isTreeDimmed(
  treeHighlightSet: Set<string> | null,
  nodeId: string,
): boolean {
  return treeHighlightSet !== null && !treeHighlightSet.has(nodeId);
}

export function getAllChildNodesAndSelf(
  edges: any[],
  parentId: string,
): string[] {
  const adj = new Map<string, string[]>();
  for (const edge of edges) {
    const list = adj.get(edge.source);
    if (list) list.push(edge.target);
    else adj.set(edge.source, [edge.target]);
  }

  const visited = new Set<string>();
  const queue = [parentId];
  const result: string[] = [];

  while (queue.length > 0) {
    const node = queue.shift()!;
    if (visited.has(node)) continue;
    visited.add(node);
    result.push(node);
    const children = adj.get(node);
    if (children) {
      for (const child of children) {
        if (!visited.has(child)) queue.push(child);
      }
    }
  }

  return result;
}

