// -- formatAutoSaveTime --

export interface FormatTimeContext {
  $t: (key: string, params?: any) => string;
}

export function formatAutoSaveTime(ctx: FormatTimeContext, date: Date): string {
  const now = Date.now();
  const diff = now - date.getTime();
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);

  if (minutes < 1) return ctx.$t('just_now');
  if (minutes === 1) return ctx.$t('1_minute_ago');
  if (minutes < 60) return ctx.$t('n_minutes_ago', { n: minutes });

  const hours = Math.floor(minutes / 60);
  if (hours === 1) return ctx.$t('1_hour_ago');
  return ctx.$t('n_hours_ago', { n: hours });
}

// -- getConnectionErrorReason --

export interface ConnectionReasonContext {
  nodes: any[];
  edges: any[];
  $t: (key: string) => string;
}

export function getConnectionErrorReason(ctx: ConnectionReasonContext, params: any): string {
  if (params.source === params.target) {
    return ctx.$t('connection_error_self_loop');
  }
  const targetNode = ctx.nodes.find((n: any) => n.id === params.target);
  const sourceNode = ctx.nodes.find((n: any) => n.id === params.source);
  if (targetNode?.data?.nodeType === NodeType.NOTE || sourceNode?.data?.nodeType === NodeType.NOTE) {
    return ctx.$t('connection_error_note_node');
  }
  if (targetNode?.data?.nodeType === NodeType.WHEN || targetNode?.type === VF_NODE_TYPE.START) {
    return ctx.$t('connection_error_trigger_target');
  }
  const duplicate = ctx.edges.some(
    (e: any) =>
      e.source === params.source &&
      e.sourceHandle === params.sourceHandle &&
      e.target === params.target &&
      e.targetHandle === params.targetHandle,
  );
  if (duplicate) {
    return ctx.$t('connection_error_duplicate');
  }
  return ctx.$t('invalid_connection');
}

// -- isValidConnection --

export interface ValidConnectionContext {
  isRestoring: boolean;
  nodes: any[];
  edges: any[];
}

export function isValidConnection(ctx: ValidConnectionContext, connection: any): boolean {
  if (ctx.isRestoring) return true;

  if (connection.source === connection.target) return false;

  const duplicate = ctx.edges.some(
    (e: any) =>
      e.source === connection.source &&
      e.sourceHandle === connection.sourceHandle &&
      e.target === connection.target &&
      e.targetHandle === connection.targetHandle,
  );
  if (duplicate) return false;

  const targetNode = ctx.nodes.find((n: any) => n.id === connection.target);
  const sourceNode = ctx.nodes.find((n: any) => n.id === connection.source);
  if (
    targetNode?.data?.nodeType === NodeType.NOTE ||
    sourceNode?.data?.nodeType === NodeType.NOTE
  ) {
    return false;
  }
  if (
    targetNode?.data?.nodeType === NodeType.WHEN ||
    targetNode?.type === VF_NODE_TYPE.START
  ) {
    return false;
  }

  const validSourceHandles = [HandleType.SUCCESS, HandleType.FAILED_CONDITION, HandleType.ERROR];
  const validTargetHandles = [HandleType.INPUT];

  if (!validSourceHandles.includes(connection.sourceHandle)) return false;
  if (!validTargetHandles.includes(connection.targetHandle)) return false;

  return true;
}

// -- getNewNodePosition --

export interface NodePositionContext {
  lastContextMenuFlowPosition: { x: number; y: number } | null;
  $el: HTMLElement;
  flow: { screenToFlowCoordinate: (pos: { x: number; y: number }) => { x: number; y: number } };
  nodes: any[];
}

export function getNewNodePosition(ctx: NodePositionContext): { x: number; y: number } {
  let pos: { x: number; y: number };

  if (ctx.lastContextMenuFlowPosition) {
    pos = { ...ctx.lastContextMenuFlowPosition };
    ctx.lastContextMenuFlowPosition = null;
  } else {
    const el = ctx.$el;
    const cx = (el?.clientWidth || 800) / 2;
    const cy = (el?.clientHeight || 600) / 2;
    pos = ctx.flow.screenToFlowCoordinate({ x: cx, y: cy });
  }

  const OVERLAP_THRESHOLD = 50;
  const NUDGE = 60;
  let attempts = 0;
  while (attempts < 10) {
    const overlaps = ctx.nodes.some((n: any) =>
      Math.abs((n.position?.x || 0) - pos.x) < OVERLAP_THRESHOLD &&
      Math.abs((n.position?.y || 0) - pos.y) < OVERLAP_THRESHOLD,
    );
    if (!overlaps) break;
    pos.x += NUDGE;
    pos.y += NUDGE;
    attempts++;
  }

  return pos;
}

// -- Tree highlight --

export interface TreeHighlightContext {
  nodes: any[];
  edges: any[];
  treeHighlightSet: Set<string> | null;
  treeEdgeIds: Set<string> | null;
  flow: { updateEdgeData: (id: string, data: any) => void };
}

export function applyTreeHighlight(ctx: TreeHighlightContext, nodeId: string): void {
  const nodeTypes = new Map<string, string>(
    ctx.nodes.map((n: any) => [n.id, n.data?.nodeType]),
  );
  const { upstream, downstream, edgeIds } = getExecutionTree(nodeId, ctx.edges, nodeTypes);
  ctx.treeHighlightSet = new Set([...upstream, ...downstream, nodeId]);
  ctx.treeEdgeIds = edgeIds;

  // Batch: only update edges whose highlight/dimmed state actually changed
  for (const edge of ctx.edges) {
    const shouldHighlight = edgeIds.has(edge.id);
    const shouldDim = !shouldHighlight;
    if (shouldHighlight !== !!edge.data?.treeHighlight || shouldDim !== !!edge.data?.treeDimmed) {
      ctx.flow?.updateEdgeData(edge.id, {
        treeHighlight: shouldHighlight,
        treeDimmed: shouldDim,
      });
    }
  }
}

export function clearTreeHighlight(ctx: TreeHighlightContext): void {
  if (ctx.treeHighlightSet === null) return;
  ctx.treeHighlightSet = null;
  ctx.treeEdgeIds = null;

  for (const edge of ctx.edges) {
    if (edge.data?.treeHighlight || edge.data?.treeDimmed) {
      ctx.flow?.updateEdgeData(edge.id, { treeHighlight: false, treeDimmed: false });
    }
  }
}

// -- copyNode / copySelectedNodes --

export interface CopyContext {
  nodes: any[];
  edges: any[];
  hasCopiedNodes: boolean;
  workflowModel: any;
  docOperatorVariables?: any;
  docOperatorVariablesSensitive?: any;
  docOperatorLockedSensitiveData?: any;
  setDataToLocalStorage: (key: string, value: string) => void;
  $t: (key: string, params?: any) => string;
}

/**
 * Snapshot current workflowModel values and docOperator data for every variable on the given nodes.
 * Returns a map from variable UUID → deep-cloned workflowModel entry,
 * plus a docOperatorData map for script_data variables.
 */
export function collectVariableValues(nodes: any[], workflowModel: any, ctx?: CopyContext): {
  variableValues: Record<string, any>;
  docOperatorData: Record<string, { variables: any; sensitive: any; locked: any }>;
} {
  const variableValues: Record<string, any> = {};
  const docOperatorData: Record<string, { variables: any; sensitive: any; locked: any }> = {};
  for (const node of nodes) {
    if (node.type !== VF_NODE_TYPE.LOGIC || !node.data?.card?.variables) continue;
    for (const variable of node.data.card.variables) {
      if (variable.uuid && workflowModel[variable.uuid]) {
        variableValues[variable.uuid] = JSON.parse(JSON.stringify(workflowModel[variable.uuid]));
      }
      // Capture docOperator state for script_data variables
      if (variable.uuid && variable.display_name === 'script_data' && ctx?.docOperatorVariables?.[variable.uuid]) {
        docOperatorData[variable.uuid] = {
          variables: JSON.parse(JSON.stringify(ctx.docOperatorVariables[variable.uuid])),
          sensitive: ctx.docOperatorVariablesSensitive?.[variable.uuid]
            ? [...ctx.docOperatorVariablesSensitive[variable.uuid]]
            : [],
          locked: ctx.docOperatorLockedSensitiveData?.[variable.uuid]
            ? [...ctx.docOperatorLockedSensitiveData[variable.uuid]]
            : [],
        };
      }
    }
  }
  return { variableValues, docOperatorData };
}

/**
 * Write workflow copy data to both system clipboard (for cross-tab/share)
 * and localStorage (as fallback).
 */
async function writeToCopyTargets(ctx: CopyContext, copyData: any): Promise<void> {
  const json = JSON.stringify(copyData, null, 2);
  ctx.setDataToLocalStorage('copiedWorkflowNodes', json);
  ctx.hasCopiedNodes = true;
  try {
    await navigator.clipboard.writeText(json);
  } catch {
    // Clipboard API not available (e.g. no HTTPS) — localStorage fallback is fine
  }
}

/**
 * Read workflow copy data from system clipboard first, then localStorage fallback.
 */
export async function readFromCopyTargets(ctx: CopyContext): Promise<any | null> {
  try {
    const text = await navigator.clipboard.readText();
    const parsed = JSON.parse(text);
    if (parsed?.nodes && Array.isArray(parsed.nodes)) return parsed;
  } catch {
    // Clipboard not available or doesn't contain valid workflow JSON
  }
  // Fallback to localStorage
  try {
    const raw = localStorage.getItem('copiedWorkflowNodes');
    if (raw) return JSON.parse(raw);
  } catch { /* empty */ }
  return null;
}

export async function copyNode(ctx: CopyContext, nodeId: string): Promise<void> {
  const nodeToCopy = ctx.nodes.find((node: any) => node.id === nodeId);
  if (!nodeToCopy || nodeToCopy.type === VF_NODE_TYPE.START) return;

  const collected = collectVariableValues([nodeToCopy], ctx.workflowModel, ctx);
  const copyData = {
    nodes: JSON.parse(JSON.stringify([nodeToCopy])),
    edges: [],
    variableValues: collected.variableValues,
    docOperatorData: collected.docOperatorData,
  };
  await writeToCopyTargets(ctx, copyData);

  notify.info(ctx.$t('nodes_copied', { count: 1 }), { duration: 1500 });
}

export async function copySelectedNodes(ctx: CopyContext): Promise<void> {
  const selectedNodes = ctx.nodes.filter((n: any) => n.selected && n.type !== VF_NODE_TYPE.START);
  if (selectedNodes.length === 0) return;

  const selectedIds = selectedNodes.map((n: any) => n.id);
  const edgesToCopy = ctx.edges.filter(
    (edge: any) => selectedIds.includes(edge.source) && selectedIds.includes(edge.target),
  );

  const collected = collectVariableValues(selectedNodes, ctx.workflowModel, ctx);
  const copyData = {
    nodes: JSON.parse(JSON.stringify(selectedNodes)),
    edges: JSON.parse(JSON.stringify(edgesToCopy)),
    variableValues: collected.variableValues,
    docOperatorData: collected.docOperatorData,
  };
  await writeToCopyTargets(ctx, copyData);

  notify.info(ctx.$t('nodes_copied', { count: selectedNodes.length }), { duration: 1500 });
}

// -- searchNodes --

export interface SearchContext {
  nodes: any[];
  flow: {
    setNodes: (nodes: any[]) => void;
    fitView: (opts: any) => void;
  };
  clearTreeHighlight: () => void;
  clearNodeHighlights: () => void;
  $t: (key: string, params?: any) => string;
}

export function searchNodes(ctx: SearchContext, query: string): void {
  ctx.clearTreeHighlight();
  if (!query || query.trim().length === 0) {
    ctx.clearNodeHighlights();
    return;
  }

  const searchLower = query.toLowerCase();
  const matchingNodes = ctx.nodes.filter((node: any) => {
    const label = node.data?.card?.text || node.data?.label || '';
    const cardType = node.data?.nodeType || '';
    return (
      label.toLowerCase().includes(searchLower) ||
      cardType.toLowerCase().includes(searchLower)
    );
  });

  if (matchingNodes.length > 0) {
    // Apply search classes and let setNodes propagate via v-model sync
    const updatedNodes = ctx.nodes.map((node: any) => ({
      ...node,
      class: matchingNodes.includes(node)
        ? 'search-highlight-node'
        : 'search-dimmed-node',
    }));
    ctx.flow.setNodes(updatedNodes);

    ctx.flow.fitView({
      nodes: matchingNodes,
      duration: 500,
      padding: 0.2,
      maxZoom: 1.5,
    });

    notify.info(
      ctx.$t('found_n_nodes', { count: matchingNodes.length }) ||
        `Found ${matchingNodes.length} matching node(s)`,
    );
  } else {
    notify.warning(ctx.$t('no_nodes_found'));
    ctx.clearNodeHighlights();
  }
}

// -- saveHistory wrapper --

export interface SaveHistoryContext {
  hasTestResults: boolean;
  clearTestResults: () => void;
  saveHistoryImmediate: () => void;
  debouncedSaveHistory: () => void;
}

export function saveHistory(ctx: SaveHistoryContext, immediate = false): void {
  if (immediate) {
    if (ctx.hasTestResults) {
      ctx.clearTestResults();
    }
    ctx.saveHistoryImmediate();
  } else {
    ctx.debouncedSaveHistory();
  }
}
