/**
 * Functions for edge management in the workflow designer.
 *
 * Pure functions take data params directly.
 * Context functions operate on component state via a minimal interface.
 */

import { HandleType } from '../workflow-advanced-models';
import { getEdgeStrokeColor } from '../composables/useNodeStatusDisplay';

// ── Edge label style (shared constant) ──────────────────────────────

export const EDGE_LABEL_STYLE = { fontWeight: 700, fontSize: 14 };

// ── Pure functions ──────────────────────────────────────────────────

/**
 * Gets the edge label character for a given source handle type.
 */
export function getEdgeLabel(sourceHandle: string): string {
  if (sourceHandle === HandleType.SUCCESS) return '✓';
  if (sourceHandle === HandleType.FAILED_CONDITION) return '✗';
  if (sourceHandle === HandleType.ERROR) return '⚠';
  return '';
}

/**
 * Gets incoming/outgoing connections for a node, categorized by handle type.
 */
export function getNodeConnections(
  edges: any[],
  nodeId: string,
): {
  in: string[];
  success: string[];
  failed_condition: string[];
  error: string[];
} {
  const incoming = edges.filter((e: any) => e.target === nodeId);
  const outgoing = edges.filter((e: any) => e.source === nodeId);

  return {
    in: incoming.map((e: any) => e.source),
    success: outgoing
      .filter((e: any) => e.sourceHandle === 'success')
      .map((e: any) => e.target),
    failed_condition: outgoing
      .filter((e: any) => e.sourceHandle === 'failed_condition')
      .map((e: any) => e.target),
    error: outgoing
      .filter((e: any) => e.sourceHandle === 'error')
      .map((e: any) => e.target),
  };
}

// ── Context-based functions ─────────────────────────────────────────

export interface RecreateEdgeContext {
  edges: any[];
  flow: {
    removeEdges: (edges: any[]) => void;
  };
  getEdges: () => any[];
  saveHistory: (immediate: boolean) => void;
}

/**
 * Recreates full edge configuration (style, label, data.remove) after JSON serialization.
 * Uses lazy recreation - skips if data already complete (performance optimization).
 */
export function recreateEdgeData(
  ctx: RecreateEdgeContext,
  edge: any,
  edgeLabelStyle: Record<string, any> = EDGE_LABEL_STYLE,
): any {
  if (edge.style && edge.label !== undefined && edge.data?.remove) {
    return edge;
  }

  const color = getEdgeStrokeColor(edge.sourceHandle);
  const edgeLabel = getEdgeLabel(edge.sourceHandle);

  edge.style = { stroke: color };
  edge.label = edgeLabel;
  edge.labelStyle = { fill: color, ...edgeLabelStyle };

  if (!edge.data) {
    edge.data = {};
  }
  edge.data.color = color;

  edge.data.remove = (id: string, _pos: any) => {
    const currentEdges = ctx.getEdges();
    const edgeToRemove = currentEdges.find((e) => e.id === id);
    if (edgeToRemove) {
      ctx.saveHistory(true);
      ctx.flow.removeEdges([edgeToRemove]);
    }
  };

  return edge;
}

export interface OnConnectContext {
  nodes: any[];
  edges: any[];
  edgeIdCounter: number;
  flow: {
    addEdges: (edges: any[]) => void;
    removeEdges: (edges: any[]) => void;
    updateNode: (id: string, data: any) => void;
  };
  isValidConnection: (params: any) => boolean;
  getConnectionErrorReason: (params: any) => string;
  getEdges: () => any[];
  saveHistory: (immediate: boolean) => void;
  notify: {
    warning: (msg: string) => void;
  };
}

/**
 * Handles a new edge connection between two nodes.
 * Validates the connection, creates the edge with correct styling, and updates handle colors.
 */
export function onConnect(
  ctx: OnConnectContext,
  params: any,
  edgeLabelStyle: Record<string, any> = EDGE_LABEL_STYLE,
): void {
  if (!ctx.isValidConnection(params)) {
    ctx.notify.warning(ctx.getConnectionErrorReason(params));
    return;
  }

  ctx.saveHistory(true);

  const edgeId = `edge-${ctx.edgeIdCounter}`;
  ctx.edgeIdCounter++;

  const color = getEdgeStrokeColor(params.sourceHandle);
  const edgeLabel = getEdgeLabel(params.sourceHandle);

  ctx.flow.addEdges([
    {
      id: edgeId,
      source: params.source,
      target: params.target,
      sourceHandle: params.sourceHandle,
      targetHandle: params.targetHandle,
      style: { stroke: color },
      label: edgeLabel,
      labelStyle: { fill: color, ...edgeLabelStyle },
      data: {
        color: color,
        remove: (id: string, _pos: any) => {
          // Use getEdges() to read the current reactive array — ctx.edges is a stale
          // snapshot because VueFlow's v-model replaces the array on every change.
          const currentEdges = ctx.getEdges();
          const edgeToRemove = currentEdges.find((edge) => edge.id === id);
          if (edgeToRemove) {
            ctx.saveHistory(true);
            ctx.flow.removeEdges([edgeToRemove]);
          } else {
            console.error('[Edge Delete] ERROR: Edge not found:', id);
            console.error(
              '[Edge Delete] Available edges:',
              currentEdges.map((e) => e.id),
            );
          }
        },
      },
    },
  ]);

  const sourceNode = ctx.nodes.find((node) => node.id === params.source);
  const targetNode = ctx.nodes.find((node) => node.id === params.target);

  if (targetNode) {
    if (!targetNode.data.handleColors) {
      targetNode.data.handleColors = {};
    }
    targetNode.data.handleColors[HandleType.INPUT] = color;
    ctx.flow.updateNode(targetNode.id, { ...targetNode });
  }

  if (sourceNode) {
    if (!sourceNode.data.handleColors) {
      sourceNode.data.handleColors = {};
    }
    sourceNode.data.handleColors[params.sourceHandle] = color;
    ctx.flow.updateNode(sourceNode.id, { ...sourceNode });
  }
}
